import json
with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)

def summarize_schema(s):
    if not s:
        return None
    if "$ref" in s:
        return s["$ref"]
    if "oneOf" in s:
        return {"oneOf": [summarize_schema(x) for x in s["oneOf"]]}
    if "allOf" in s:
        return {"allOf": [summarize_schema(x) for x in s["allOf"]]}
    t = s.get("type")
    if t == "object":
        props = {}
        req = set(s.get("required", []))
        for k, v in s.get("properties", {}).items():
            mark = "*" if k in req else ""
            props[k + mark] = summarize_schema(v)
        if not props and s.get("additionalProperties"):
            return "object(any)"
        return props
    if t == "array":
        return [summarize_schema(s.get("items"))]
    desc = t or "any"
    if "enum" in s:
        desc += f" enum={s['enum']}"
    if "format" in s:
        desc += f" ({s['format']})"
    return desc

for path, item in spec["paths"].items():
    for method, op in item.items():
        print(f"=== {method.upper()} {path} (opId: {op.get('operationId')}, sec: {op.get('security')}) ===")
        if op.get("parameters"):
            print("  PARAMS:", json.dumps(op["parameters"]))
        if "requestBody" in op:
            rb = op["requestBody"]["content"]["application/json"]["schema"]
            print("  REQ:", json.dumps(summarize_schema(rb)))
        for status, resp in op.get("responses", {}).items():
            content = resp.get("content", {})
            if "application/json" in content:
                rs = content["application/json"]["schema"]
                print(f"  RESP {status}:", json.dumps(summarize_schema(rs)))
            else:
                print(f"  RESP {status}: {list(content.keys())}")
EOF

