import json
with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)

for path, item in spec["paths"].items():
    for method, op in item.items():
        print(f"*** {method.upper()} {path} ({op['operationId']}) ***")
        if "requestBody" in op:
            schema = op["requestBody"]["content"]["application/json"]["schema"]
            print("  Request required:", schema.get("required", []))
            for prop, pschema in schema.get("properties", {}).items():
                print(f"    req.{prop}: {json.dumps(pschema)}")
        for code, resp in op["responses"].items():
            if code.startswith("2"):
                schema = resp.get("content", {}).get("application/json", {}).get("schema", {})
                if "properties" in schema and "data" in schema["properties"]:
                    dschema = schema["properties"]["data"]
                    print(f"  Resp {code} data: {json.dumps(dschema)}")
                else:
                    print(f"  Resp {code}: {json.dumps(schema)}")
            else:
                schema = resp.get("content", {}).get("application/json", {}).get("schema", {})
                codes = schema.get("properties", {}).get("code", {}).get("enum", [])
                print(f"  Err {code}: {codes}")
EOF

