import json
from collections import defaultdict

with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)

by_code = defaultdict(list)
for path, item in spec["paths"].items():
    for method, op in item.items():
        op_id = op["operationId"]
        for status, resp in op["responses"].items():
            if not status.startswith("2") and status != "101":
                schema = resp.get("content", {}).get("application/json", {}).get("schema", {})
                codes = schema.get("properties", {}).get("code", {}).get("enum", [])
                for c in codes:
                    by_code[(status, c)].append(op_id)

for (status, c), ops in sorted(by_code.items()):
    print(f"HTTP {status} | {c:32s} -> {', '.join(ops)}")
EOF

