func isCooledRequired(st *SampleTypeModel) bool {
	if st == nil {
		return false
	}
	if st.RequiresCooledRoute || strings.EqualFold(st.Name, "Frost") {
		return true
	}
	if st.TemperatureMaxC <= 8 {
		return true
	}
	return false
}

func isPulseSampleType(st *SampleTypeModel) bool {
	if st == nil {
		return false
	}
	return strings.EqualFold(st.Name, "Pulse") || !st.BatchingAllowed
}

func areSampleTypesCompatible(a, b *SampleTypeModel) bool {
	if a == nil || b == nil {
		return false
	}
	if isPulseSampleType(a) || isPulseSampleType(b) {
		return false
	}
	if (strings.EqualFold(a.Name, "Amber") && strings.EqualFold(b.Name, "Indigo")) ||
		(strings.EqualFold(a.Name, "Indigo") && strings.EqualFold(b.Name, "Amber")) {
		return false
	}
	for _, id := range a.IncompatibleSampleTypes {
		if id == b.SampleTypeID {
			return false
		}
	}
	for _, id := range b.IncompatibleSampleTypes {
		if id == a.SampleTypeID {
			return false
		}
	}
	// Temperature ranges must overlap and cooling requirement must be compatible
	if isCooledRequired(a) != isCooledRequired(b) {
		return false
	}
	overlapMin := math.Max(a.TemperatureMinC, b.TemperatureMinC)
	overlapMax := math.Min(a.TemperatureMaxC, b.TemperatureMaxC)
	if overlapMin > overlapMax {
		return false
	}
	return true
}

func hasResourceCapacity(cap Capacity, cooled bool, units int) bool {
	if units <= 0 {
		units = 1
	}
	if cooled {
		return cap.CooledAvailableUnits >= units
	}
	return cap.AvailableUnits >= units
}

func reserveCapacityOnPool(cap *Capacity, cooled bool, units int) bool {
	if units <= 0 {
		units = 1
	}
	if cooled {
		if cap.CooledAvailableUnits < units {
			return false
		}
		cap.CooledReservedUnits += units
		cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
		return true
	}
	if cap.AvailableUnits < units {
		return false
	}
	cap.ReservedUnits += units
	cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
	return true
}

func releaseCapacityOnPool(cap *Capacity, cooled bool, units int) {
	if units <= 0 {
		units = 1
	}
	if cooled {
		cap.CooledReservedUnits -= units
		if cap.CooledReservedUnits < 0 {
			cap.CooledReservedUnits = 0
		}
		cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
		return
	}
	cap.ReservedUnits -= units
	if cap.ReservedUnits < 0 {
		cap.ReservedUnits = 0
	}
	cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
}

type routeSearchResult struct {
	Serviceable      bool
	Reason           string
	ConflictCode     string
	StartNodeID      string
	TargetLabID      string
	NodePath         []string
	ConnectionPath   []string
	TotalTravelMins  int
	TotalCost        float64
	EstimatedArrival time.Time
}

type pathItem struct {
	nodeID      string
	nodes       []string
	conns       []string
	travelMins  int
	cost        float64
	index       int
}

type pathQueue []*pathItem

func (pq pathQueue) Len() int { return len(pq) }
func (pq pathQueue) Less(i, j int) bool {
	if pq[i].travelMins != pq[j].travelMins {
		return pq[i].travelMins < pq[j].travelMins
	}
	return pq[i].cost < pq[j].cost
}
func (pq pathQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}
func (pq *pathQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*pathItem)
	item.index = n
	*pq = append(*pq, item)
}
func (pq *pathQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	item.index = -1
	*pq = old[0 : n-1]
	return item
}

func (s *Store) evaluateServiceabilityAndRouteLocked(
	origin Coordinate,
	originType string,
	originNodeID string,
	sampleType *SampleTypeModel,
	startBaseTime time.Time,
	deadline time.Time,
	units int,
	allowPresealedStartNode bool,
) routeSearchResult {
	if sampleType == nil {
		return routeSearchResult{
			Serviceable:  false,
			Reason:       "handling_rules_unsatisfiable",
			ConflictCode: "invalid_plan",
		}
	}
	if sampleType.ContainerType == "" || sampleType.TemperatureMinC > sampleType.TemperatureMaxC {
		return routeSearchResult{
			Serviceable:  false,
			Reason:       "handling_rules_unsatisfiable",
			ConflictCode: "invalid_plan",
		}
	}

	cooled := isCooledRequired(sampleType)
	if units <= 0 {
		units = 1
	}

	// Step 1: Identify candidate start collection points within 5km (and within node's coverageKm)
	var candidateStarts []*LocationModel
	if originNodeID != "" {
		loc, exists := s.state.Locations[originNodeID]
		if loc != nil && exists && loc.Active {
			if allowPresealedStartNode || loc.Functions.CollectionPoint {
				cov := loc.CoverageKm
				if cov <= 0 || cov > 5 {
					cov = 5
				}
				dist := haversineKm(origin, loc.Coordinate)
				if originType == "node" || dist <= math.Min(5.0, cov)+1e-6 {
					candidateStarts = append(candidateStarts, loc)
				}
			}
		}
	} else {
		var ids []string
		for id := range s.state.Locations {
			ids = append(ids, id)
		}
		sort.Strings(ids)
		for _, id := range ids {
			loc := s.state.Locations[id]
			if !loc.Active {
				continue
			}
			if !allowPresealedStartNode && !loc.Functions.CollectionPoint {
				continue
			}
			if allowPresealedStartNode && !loc.Functions.CollectionPoint && !loc.Functions.TransferPoint && !loc.Functions.Hub {
				continue
			}
			cov := loc.CoverageKm
			if cov <= 0 || cov > 5 {
				cov = 5
			}
			dist := haversineKm(origin, loc.Coordinate)
			if dist <= math.Min(5.0, cov)+1e-6 {
				candidateStarts = append(candidateStarts, loc)
			}
		}
		sort.Slice(candidateStarts, func(i, j int) bool {
			di := haversineKm(origin, candidateStarts[i].Coordinate)
			dj := haversineKm(origin, candidateStarts[j].Coordinate)
			if math.Abs(di-dj) > 1e-6 {
				return di < dj
			}
			return candidateStarts[i].LocationID < candidateStarts[j].LocationID
		})
	}

	if len(candidateStarts) == 0 {
		return routeSearchResult{
			Serviceable:  false,
			Reason:       "outside_service_coverage",
			ConflictCode: "no_valid_route",
		}
	}

	// Step 2: Check if any active laboratory accepts this sampleType
	var acceptingLabs []*LocationModel
	for _, loc := range s.state.Locations {
		if loc.Active && loc.Functions.Laboratory && loc.AcceptedSampleTypes[sampleType.SampleTypeID] {
			acceptingLabs = append(acceptingLabs, loc)
		}
	}
	if len(acceptingLabs) == 0 {
		return routeSearchResult{
			Serviceable:  false,
			Reason:       "no_accepting_laboratory",
			ConflictCode: "invalid_destination",
		}
	}

	// Step 3: Search for paths from candidateStarts to any acceptingLab
	// First check if a structural route exists (ignoring capacity and deadline) so we can return the most specific reason!
	foundStructuralRoute := false
	foundCooledRoute := false
	foundCapacityRoute := false
	var bestDeadlineFailed *routeSearchResult
	var bestValid *routeSearchResult

	for _, startLoc := range candidateStarts {
		// Run Dijkstra / BFS over active connections
		resValid, resCapFail, resCoolFail, resDeadFail := s.searchPathsFromStartLocked(startLoc, sampleType, cooled, units, startBaseTime, deadline)
		if resCoolFail {
			foundStructuralRoute = true
		}
		if resCapFail {
			foundStructuralRoute = true
			foundCooledRoute = true
		}
		if resDeadFail != nil {
			foundStructuralRoute = true
			foundCooledRoute = true
			foundCapacityRoute = true
			if bestDeadlineFailed == nil || resDeadFail.EstimatedArrival.Before(bestDeadlineFailed.EstimatedArrival) {
				bestDeadlineFailed = resDeadFail
			}
		}
		if resValid != nil {
			foundStructuralRoute = true
			foundCooledRoute = true
			foundCapacityRoute = true
			if bestValid == nil ||
				resValid.TotalTravelMins < bestValid.TotalTravelMins ||
				(resValid.TotalTravelMins == bestValid.TotalTravelMins && resValid.TotalCost < bestValid.TotalCost) {
				bestValid = resValid
			}
		}
	}

	if bestValid != nil {
		return *bestValid
	}
	if bestDeadlineFailed != nil {
		return *bestDeadlineFailed
	}
	if foundCooledRoute && !foundCapacityRoute {
		cCode := "capacity_exhausted"
		if cooled {
			cCode = "cooled_capacity_exhausted"
		}
		return routeSearchResult{
			Serviceable:  false,
			Reason:       "insufficient_capacity",
			ConflictCode: cCode,
		}
	}
	if foundStructuralRoute && !foundCooledRoute {
		// Route existed structurally, but connections were not cooled for a cooled sample!
		return routeSearchResult{
			Serviceable:  false,
			Reason:       "no_route",
			ConflictCode: "no_valid_route",
		}
	}
	return routeSearchResult{
		Serviceable:  false,
		Reason:       "no_route",
		ConflictCode: "no_valid_route",
	}
}

func (s *Store) searchPathsFromStartLocked(
	startLoc *LocationModel,
	sampleType *SampleTypeModel,
	cooled bool,
	units int,
	startBaseTime time.Time,
	deadline time.Time,
) (validRes *routeSearchResult, hadCapFail bool, hadCoolFail bool, deadFailRes *routeSearchResult) {
	// Also support 0-hop if startLoc itself is an active accepting laboratory
	if startLoc.Functions.Laboratory && startLoc.AcceptedSampleTypes[sampleType.SampleTypeID] {
		if !hasResourceCapacity(startLoc.Capacity, cooled, units) {
			hadCapFail = true
		} else {
			arr := startBaseTime.Add(time.Duration(startLoc.HandlingMinutes) * time.Minute)
			r := &routeSearchResult{
				Serviceable:      !arr.After(deadline),
				Reason:           "serviceable",
				StartNodeID:      startLoc.LocationID,
				TargetLabID:      startLoc.LocationID,
				NodePath:         []string{startLoc.LocationID},
				ConnectionPath:   []string{},
				TotalTravelMins:  startLoc.HandlingMinutes,
				TotalCost:        0,
				EstimatedArrival: arr,
			}
			if arr.After(deadline) {
				r.Reason = "deadline_unreachable"
				r.ConflictCode = "delivery_deadline_exceeded"
				deadFailRes = r
			} else {
				return r, false, false, nil
			}
		}
	}

	// Build adjacency list of active connections
	adj := make(map[string][]*ConnectionModel)
	for _, conn := range s.state.Connections {
		if !conn.Active {
			continue
		}
		fromLoc := s.state.Locations[conn.FromLocationID]
		toLoc := s.state.Locations[conn.ToLocationID]
		if fromLoc == nil || !fromLoc.Active || toLoc == nil || !toLoc.Active {
			continue
		}
		adj[conn.FromLocationID] = append(adj[conn.FromLocationID], conn)
	}
	for k := range adj {
		sort.Slice(adj[k], func(i, j int) bool {
			if adj[k][i].TravelMinutes != adj[k][j].TravelMinutes {
				return adj[k][i].TravelMinutes < adj[k][j].TravelMinutes
			}
			if adj[k][i].CostUnits != adj[k][j].CostUnits {
				return adj[k][i].CostUnits < adj[k][j].CostUnits
			}
			return adj[k][i].ConnectionID < adj[k][j].ConnectionID
		})
	}

	// Pass 1: Search with capacity + cooling enforced
	pq := &pathQueue{}
	heap.Init(pq)
	startCapOK := hasResourceCapacity(startLoc.Capacity, cooled, units)

	if startCapOK {
		heap.Push(pq, &pathItem{
			nodeID:     startLoc.LocationID,
			nodes:      []string{startLoc.LocationID},
			conns:      []string{},
			travelMins: startLoc.HandlingMinutes,
			cost:       0,
		})
	}

	bestDist := make(map[string]int)
	for pq.Len() > 0 {
		curr := heap.Pop(pq).(*pathItem)
		if prev, seen := bestDist[curr.nodeID]; seen && curr.travelMins > prev {
			continue
		}
		bestDist[curr.nodeID] = curr.travelMins

		loc := s.state.Locations[curr.nodeID]
		if len(curr.conns) > 0 && loc.Functions.Laboratory && loc.AcceptedSampleTypes[sampleType.SampleTypeID] {
			arr := startBaseTime.Add(time.Duration(curr.travelMins) * time.Minute)
			res := &routeSearchResult{
				Serviceable:      !arr.After(deadline),
				Reason:           "serviceable",
				StartNodeID:      startLoc.LocationID,
				TargetLabID:      loc.LocationID,
				NodePath:         curr.nodes,
				ConnectionPath:   curr.conns,
				TotalTravelMins:  curr.travelMins,
				TotalCost:        curr.cost,
				EstimatedArrival: arr,
			}
			if !arr.After(deadline) {
				return res, hadCapFail, hadCoolFail, deadFailRes
			}
			res.Reason = "deadline_unreachable"
			res.ConflictCode = "delivery_deadline_exceeded"
			if deadFailRes == nil || arr.Before(deadFailRes.EstimatedArrival) {
				deadFailRes = res
			}
		}

		// Intermediate node must be startLoc or have transfer_point / hub / collection_point active
		if curr.nodeID != startLoc.LocationID && !loc.Functions.TransferPoint && !loc.Functions.Hub && !loc.Functions.CollectionPoint {
			continue
		}

		for _, conn := range adj[curr.nodeID] {
			if cooled && !conn.Cooled {
				continue
			}
			if !hasResourceCapacity(conn.Capacity, cooled, units) {
				continue
			}
			nextLoc := s.state.Locations[conn.ToLocationID]
			if nextLoc == nil || !nextLoc.Active {
				continue
			}
			// Avoid cycles
			inPath := false
			for _, nid := range curr.nodes {
				if nid == nextLoc.LocationID {
					inPath = true
					break
				}
			}
			if inPath {
				continue
			}
			isDestLab := nextLoc.Functions.Laboratory && nextLoc.AcceptedSampleTypes[sampleType.SampleTypeID]
			isTransit := nextLoc.Functions.TransferPoint || nextLoc.Functions.Hub || nextLoc.Functions.CollectionPoint
			if !isDestLab && !isTransit {
				continue
			}
			if !hasResourceCapacity(nextLoc.Capacity, cooled, units) {
				continue
			}

			nextNodes := append([]string{}, curr.nodes...)
			nextNodes = append(nextNodes, nextLoc.LocationID)
			nextConns := append([]string{}, curr.conns...)
			nextConns = append(nextConns, conn.ConnectionID)
			nextMins := curr.travelMins + conn.TravelMinutes + nextLoc.HandlingMinutes
			nextCost := curr.cost + conn.CostUnits

			heap.Push(pq, &pathItem{
				nodeID:     nextLoc.LocationID,
				nodes:      nextNodes,
				conns:      nextConns,
				travelMins: nextMins,
				cost:       nextCost,
			})
		}
	}

	// Pass 2: Diagnostic pass ignoring capacity (and checking cooling) to distinguish no_route vs insufficient_capacity
	visitedCool := map[string]bool{startLoc.LocationID: true}
	queueCool := []string{startLoc.LocationID}
	for len(queueCool) > 0 {
		currID := queueCool[0]
		queueCool = queueCool[1:]
		loc := s.state.Locations[currID]
		if currID != startLoc.LocationID && loc.Functions.Laboratory && loc.AcceptedSampleTypes[sampleType.SampleTypeID] {
			hadCapFail = true
			break
		}
		if currID != startLoc.LocationID && !loc.Functions.TransferPoint && !loc.Functions.Hub && !loc.Functions.CollectionPoint {
			continue
		}
		for _, conn := range adj[currID] {
			if cooled && !conn.Cooled {
				continue
			}
			nextLoc := s.state.Locations[conn.ToLocationID]
			if nextLoc == nil || !nextLoc.Active || visitedCool[nextLoc.LocationID] {
				continue
			}
			isDestLab := nextLoc.Functions.Laboratory && nextLoc.AcceptedSampleTypes[sampleType.SampleTypeID]
			isTransit := nextLoc.Functions.TransferPoint || nextLoc.Functions.Hub || nextLoc.Functions.CollectionPoint
			if !isDestLab && !isTransit {
				continue
			}
			visitedCool[nextLoc.LocationID] = true
			queueCool = append(queueCool, nextLoc.LocationID)
		}
	}

	if !hadCapFail && cooled {
		visitedAny := map[string]bool{startLoc.LocationID: true}
		queueAny := []string{startLoc.LocationID}
		for len(queueAny) > 0 {
			currID := queueAny[0]
			queueAny = queueAny[1:]
			loc := s.state.Locations[currID]
			if currID != startLoc.LocationID && loc.Functions.Laboratory && loc.AcceptedSampleTypes[sampleType.SampleTypeID] {
				hadCoolFail = true
				break
			}
			if currID != startLoc.LocationID && !loc.Functions.TransferPoint && !loc.Functions.Hub && !loc.Functions.CollectionPoint {
				continue
			}
			for _, conn := range adj[currID] {
				nextLoc := s.state.Locations[conn.ToLocationID]
				if nextLoc == nil || !nextLoc.Active || visitedAny[nextLoc.LocationID] {
					continue
				}
				isDestLab := nextLoc.Functions.Laboratory && nextLoc.AcceptedSampleTypes[sampleType.SampleTypeID]
				isTransit := nextLoc.Functions.TransferPoint || nextLoc.Functions.Hub || nextLoc.Functions.CollectionPoint
				if !isDestLab && !isTransit {
					continue
				}
				visitedAny[nextLoc.LocationID] = true
				queueAny = append(queueAny, nextLoc.LocationID)
			}
		}
	}

	return nil, hadCapFail, hadCoolFail, deadFailRes
}
