func extractBearerToken(r *http.Request) string {
	auth := strings.TrimSpace(r.Header.Get("Authorization"))
	if auth != "" {
		if strings.HasPrefix(strings.ToLower(auth), "bearer ") {
			return strings.TrimSpace(auth[7:])
		}
		return auth
	}
	wsProto := strings.TrimSpace(r.Header.Get("Sec-WebSocket-Protocol"))
	if wsProto != "" {
		parts := strings.Split(wsProto, ",")
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if strings.HasPrefix(strings.ToLower(p), "bearer ") {
				return strings.TrimSpace(p[7:])
			}
			if strings.HasPrefix(strings.ToLower(p), "bearer.") {
				return strings.TrimSpace(p[7:])
			}
			if strings.ToLower(p) != "bearer" && strings.ToLower(p) != "json" && p != "" {
				return p
			}
		}
	}
	if q := strings.TrimSpace(r.URL.Query().Get("token")); q != "" {
		return q
	}
	if q := strings.TrimSpace(r.URL.Query().Get("sessionToken")); q != "" {
		return q
	}
	return ""
}

func (s *Store) authAndRoleLocked(w http.ResponseWriter, r *http.Request, action, entityType string, requireRoleSelected bool, allowedRoles ...string) (*User, *Session, bool) {
	now := time.Now().UTC()
	token := extractBearerToken(r)
	if token == "" {
		s.recordAuditLocked("anonymous", "unselected", action, entityType, "auth", false, now, map[string]interface{}{"reason": "missing_token"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return nil, nil, false
	}
	sess, ok := s.state.Sessions[token]
	if !ok || sess == nil {
		s.recordAuditLocked("anonymous", "unselected", action, entityType, "auth", false, now, map[string]interface{}{"reason": "invalid_token"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusUnauthorized, "unauthorized", "Invalid session token")
		return nil, nil, false
	}
	u, ok := s.state.Users[sess.UserID]
	if !ok || u == nil || !u.Active {
		s.recordAuditLocked(sess.UserID, sess.ActiveRole, action, entityType, "auth", false, now, map[string]interface{}{"reason": "inactive_user"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusUnauthorized, "unauthorized", "User is not active")
		return nil, nil, false
	}

	// Verify active role is still held by user
	if sess.ActiveRole != "" && !hasRole(u, sess.ActiveRole) {
		sess.ActiveRole = ""
		sess.ExplicitlySelected = false
	}
	if len(u.Roles) > 1 && !sess.ExplicitlySelected {
		sess.ActiveRole = ""
	}
	if len(u.Roles) == 1 && sess.ActiveRole == "" {
		sess.ActiveRole = u.Roles[0]
	}

	if requireRoleSelected && sess.ActiveRole == "" {
		s.recordAuditLocked(u.UserID, "unselected", action, entityType, u.UserID, false, now, map[string]interface{}{"reason": "role_not_selected"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "role_not_selected", "User must explicitly select an active role")
		return nil, nil, false
	}

	if len(allowedRoles) > 0 {
		roleAllowed := false
		for _, ar := range allowedRoles {
			if sess.ActiveRole == ar {
				roleAllowed = true
				break
			}
		}
		if !roleAllowed {
			s.recordAuditLocked(u.UserID, sess.ActiveRole, action, entityType, u.UserID, false, now, map[string]interface{}{
				"reason":       "forbidden",
				"activeRole":   sess.ActiveRole,
				"allowedRoles": allowedRoles,
			})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "Role is not permitted for this operation")
			return nil, nil, false
		}
	}

	return u, sess, true
}

func (s *Store) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Username *string `json:"username"`
		Password *string `json:"password"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.Username == nil || req.Password == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	username := strings.TrimSpace(*req.Username)
	password := *req.Password

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	if username == "" || password == "" {
		s.recordAuditLocked("anonymous", "unselected", "authenticate_user", "user", username, false, now, map[string]interface{}{"username": username, "reason": "empty_credentials"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "Invalid username or password")
		return
	}

	var matchedUser *User
	for _, u := range s.state.Users {
		if u.Username == username {
			matchedUser = u
			break
		}
	}

	if matchedUser == nil || !matchedUser.Active || matchedUser.PasswordHash != hashString(password) {
		actor := "anonymous"
		if matchedUser != nil {
			actor = matchedUser.UserID
		}
		s.recordAuditLocked(actor, "unselected", "authenticate_user", "user", username, false, now, map[string]interface{}{"username": username, "reason": "invalid_credentials"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "Invalid username or password")
		return
	}

	activeRole := ""
	explicit := false
	if len(matchedUser.Roles) == 1 {
		activeRole = matchedUser.Roles[0]
		explicit = true
	}

	token := newUUID() + "-" + newUUID()
	sess := &Session{
		Token:              token,
		UserID:             matchedUser.UserID,
		ActiveRole:         activeRole,
		ExplicitlySelected: explicit,
		CreatedAt:          formatTime(now),
	}
	s.state.Sessions[token] = sess

	auditRole := activeRole
	if auditRole == "" && len(matchedUser.Roles) > 0 {
		auditRole = matchedUser.Roles[0]
	}
	s.recordAuditLocked(matchedUser.UserID, auditRole, "authenticate_user", "user", matchedUser.UserID, true, now, map[string]interface{}{
		"username":   matchedUser.Username,
		"roles":      matchedUser.Roles,
		"activeRole": activeRole,
	})
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusOK, map[string]interface{}{
		"sessionToken": token,
		"userId":       matchedUser.UserID,
		"roles":        matchedUser.Roles,
		"activeRole":   activeRole,
	})
}

func (s *Store) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Role *string `json:"role"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.Role == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	role := strings.TrimSpace(*req.Role)

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	u, sess, ok := s.authAndRoleLocked(w, r, "select_active_role", "user", false)
	if !ok {
		return
	}

	if !validRoles[role] {
		s.recordAuditLocked(u.UserID, sess.ActiveRole, "select_active_role", "user", u.UserID, false, now, map[string]interface{}{"requestedRole": role, "reason": "invalid_role"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_role", "Invalid role")
		return
	}

	if !hasRole(u, role) {
		s.recordAuditLocked(u.UserID, sess.ActiveRole, "select_active_role", "user", u.UserID, false, now, map[string]interface{}{"requestedRole": role, "reason": "role_not_held"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "role_not_held", "User does not hold the requested role")
		return
	}

	sess.ActiveRole = role
	sess.ExplicitlySelected = true

	s.recordAuditLocked(u.UserID, role, "select_active_role", "user", u.UserID, true, now, map[string]interface{}{
		"activeRole": role,
		"roles":      u.Roles,
	})
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusOK, map[string]interface{}{
		"activeRole": role,
		"roles":      u.Roles,
	})
}

func (s *Store) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Username           *string         `json:"username"`
		InitialPassword    *string         `json:"initialPassword"`
		Email              string          `json:"email"`
		FullName           string          `json:"fullName"`
		Phone              string          `json:"phone"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             *bool           `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.Username == nil || req.InitialPassword == nil || req.Active == nil || req.Roles == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "create_user", "user", true, "administrator")
	if !ok {
		return
	}

	uname := strings.TrimSpace(*req.Username)
	pass := *req.InitialPassword
	if uname == "" || pass == "" || len(req.Roles) == 0 {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_user", "user", uname, false, now, map[string]interface{}{"reason": "invalid_user"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_user", "Invalid user fields")
		return
	}
	for _, rl := range req.Roles {
		if !validRoles[rl] {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_user", "user", uname, false, now, map[string]interface{}{"reason": "invalid_user"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_user", "Invalid role in roles")
			return
		}
	}
	if req.AssignedLocationID != "" {
		if !isValidUUID(req.AssignedLocationID) || s.state.Locations[req.AssignedLocationID] == nil {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_user", "user", uname, false, now, map[string]interface{}{"reason": "invalid_user"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_user", "Invalid assignedLocationId")
			return
		}
	}

	// Validate certifications
	for _, cert := range req.Certifications {
		if strings.TrimSpace(cert.Code) == "" {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_user", "user", uname, false, now, map[string]interface{}{"reason": "invalid_certification"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_certification", "Certification code is required")
			return
		}
		if cert.ExpiresAt != "" {
			if _, err := parseTime(cert.ExpiresAt); err != nil {
				s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_user", "user", uname, false, now, map[string]interface{}{"reason": "invalid_certification"})
				_ = s.persistLocked(r.Context())
				writeError(w, http.StatusBadRequest, "invalid_certification", "Invalid certification expiresAt")
				return
			}
		}
	}

	for _, existing := range s.state.Users {
		if existing.Username == uname {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_user", "user", uname, false, now, map[string]interface{}{"reason": "username_exists"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusConflict, "username_exists", "Username already exists")
			return
		}
	}

	quals := req.Qualifications
	if quals == nil {
		quals = []string{}
	}
	certs := req.Certifications
	if certs == nil {
		certs = []Certification{}
	}
	// Sync active certification codes into qualifications if not already present
	for _, c := range certs {
		if c.Active {
			found := false
			for _, q := range quals {
				if strings.EqualFold(q, c.Code) {
					found = true
					break
				}
			}
			if !found {
				quals = append(quals, c.Code)
			}
		}
	}

	newUser := &User{
		UserID:             newUUID(),
		Username:           uname,
		PasswordHash:       hashString(pass),
		Email:              req.Email,
		FullName:           req.FullName,
		Phone:              req.Phone,
		Roles:              req.Roles,
		Qualifications:     quals,
		Certifications:     certs,
		Active:             *req.Active,
		AssignedLocationID: req.AssignedLocationID,
		Available:          *req.Active,
		CapacityUnits:      10,
		AssignmentLocSeq:   make(map[string]int),
		CreatedAt:          formatTime(now),
	}
	s.state.Users[newUser.UserID] = newUser

	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_user", "user", newUser.UserID, true, now, map[string]interface{}{
		"userId":             newUser.UserID,
		"username":           newUser.Username,
		"roles":              newUser.Roles,
		"qualifications":     newUser.Qualifications,
		"assignedLocationId": newUser.AssignedLocationID,
		"active":             newUser.Active,
	})
	s.emitRealtimeLocked("user.created", "user", newUser.UserID, map[string]interface{}{
		"userId":   newUser.UserID,
		"username": newUser.Username,
		"roles":    newUser.Roles,
	})
	_ = s.persistLocked(r.Context())

	respData := map[string]interface{}{
		"userId":         newUser.UserID,
		"username":       newUser.Username,
		"roles":          newUser.Roles,
		"qualifications": newUser.Qualifications,
		"certifications": newUser.Certifications,
		"active":         newUser.Active,
	}
	if newUser.Email != "" {
		respData["email"] = newUser.Email
	}
	if newUser.FullName != "" {
		respData["fullName"] = newUser.FullName
	}
	if newUser.Phone != "" {
		respData["phone"] = newUser.Phone
	}
	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		UserID             *string          `json:"userId"`
		Roles              *[]string        `json:"roles"`
		Qualifications     *[]string        `json:"qualifications"`
		Certifications     *[]Certification `json:"certifications"`
		Active             *bool            `json:"active"`
		AssignedLocationID *string          `json:"assignedLocationId"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.UserID == nil || req.Roles == nil || req.Active == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if !isValidUUID(*req.UserID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid userId")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "update_user_access", "user", true, "administrator")
	if !ok {
		return
	}

	if len(*req.Roles) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_json", "At least one role is required")
		return
	}
	for _, rl := range *req.Roles {
		if !validRoles[rl] {
			writeError(w, http.StatusBadRequest, "invalid_json", "Invalid role")
			return
		}
	}
	if req.Certifications != nil {
		for _, cert := range *req.Certifications {
			if strings.TrimSpace(cert.Code) == "" {
				s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_user_access", "user", *req.UserID, false, now, map[string]interface{}{"reason": "invalid_certification"})
				_ = s.persistLocked(r.Context())
				writeError(w, http.StatusBadRequest, "invalid_certification", "Invalid certification code")
				return
			}
			if cert.ExpiresAt != "" {
				if _, err := parseTime(cert.ExpiresAt); err != nil {
					s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_user_access", "user", *req.UserID, false, now, map[string]interface{}{"reason": "invalid_certification"})
					_ = s.persistLocked(r.Context())
					writeError(w, http.StatusBadRequest, "invalid_certification", "Invalid certification expiresAt")
					return
				}
			}
		}
	}

	target := s.state.Users[*req.UserID]
	if target == nil {
		writeError(w, http.StatusNotFound, "not_found", "User not found")
		return
	}

	target.Roles = *req.Roles
	target.Active = *req.Active
	if req.Qualifications != nil {
		target.Qualifications = *req.Qualifications
	}
	if req.Certifications != nil {
		target.Certifications = *req.Certifications
	}
	if req.AssignedLocationID != nil {
		target.AssignedLocationID = *req.AssignedLocationID
	}

	// Update any existing sessions of target user if their activeRole is no longer held
	for _, usess := range s.state.Sessions {
		if usess.UserID == target.UserID {
			if usess.ActiveRole != "" && !hasRole(target, usess.ActiveRole) {
				usess.ActiveRole = ""
				usess.ExplicitlySelected = false
			}
		}
	}

	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_user_access", "user", target.UserID, true, now, map[string]interface{}{
		"userId":             target.UserID,
		"roles":              target.Roles,
		"qualifications":     target.Qualifications,
		"certifications":     target.Certifications,
		"active":             target.Active,
		"assignedLocationId": target.AssignedLocationID,
	})
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, map[string]interface{}{
		"userId":         target.UserID,
		"roles":          target.Roles,
		"qualifications": target.Qualifications,
		"certifications": target.Certifications,
		"active":         target.Active,
	})
}

func (s *Store) handleReadUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	userID := strings.TrimPrefix(r.URL.Path, "/api/read-user/")
	userID = strings.TrimSpace(userID)

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "read_user", "user", true)
	if !ok {
		return
	}

	// Only administrator, dispatcher, or the user themselves can read user
	if sess.ActiveRole != "administrator" && sess.ActiveRole != "dispatcher" && actor.UserID != userID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "read_user", "user", userID, false, now, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Cannot read another user")
		return
	}

	target := s.state.Users[userID]
	if target == nil {
		writeError(w, http.StatusNotFound, "not_found", "User not found")
		return
	}

	respData := map[string]interface{}{
		"userId":         target.UserID,
		"username":       target.Username,
		"roles":          target.Roles,
		"qualifications": target.Qualifications,
		"certifications": target.Certifications,
		"active":         target.Active,
	}
	if target.Email != "" {
		respData["email"] = target.Email
	}
	if target.FullName != "" {
		respData["fullName"] = target.FullName
	}
	if target.Phone != "" {
		respData["phone"] = target.Phone
	}
	writeData(w, http.StatusOK, respData)
}

func parseLocationFunctionsSlice(funcs []string) (LocationFunctionStates, bool) {
	var st LocationFunctionStates
	if len(funcs) == 0 {
		return st, false
	}
	for _, f := range funcs {
		if !validLocationFunctions[f] {
			return st, false
		}
		switch f {
		case "collection_point":
			st.CollectionPoint = true
		case "transfer_point":
			st.TransferPoint = true
		case "hub":
			st.Hub = true
		case "laboratory":
			st.Laboratory = true
		}
	}
	return st, true
}

func locationToDTO(loc *LocationModel) map[string]interface{} {
	return map[string]interface{}{
		"locationId":      loc.LocationID,
		"name":            loc.Name,
		"coordinate":      loc.Coordinate,
		"coverageKm":      loc.CoverageKm,
		"handlingMinutes": loc.HandlingMinutes,
		"active":          loc.Active,
		"functions":       loc.Functions,
	}
}

func (s *Store) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Name            *string     `json:"name"`
		Coordinate      *Coordinate `json:"coordinate"`
		CoverageKm      *float64    `json:"coverageKm"`
		HandlingMinutes *int        `json:"handlingMinutes"`
		Active          *bool       `json:"active"`
		Functions       []string    `json:"functions"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.Name == nil || req.Coordinate == nil || req.Active == nil || req.Functions == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "create_location", "location", true, "administrator")
	if !ok {
		return
	}

	if strings.TrimSpace(*req.Name) == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "Location name is required")
		return
	}
	if !isValidCoordinate(*req.Coordinate) {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_location", "location", *req.Name, false, now, map[string]interface{}{"reason": "invalid_coordinate"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_coordinate", "Invalid coordinate")
		return
	}

	covKm := 5.0
	if req.CoverageKm != nil {
		covKm = *req.CoverageKm
		if math.IsNaN(covKm) || math.IsInf(covKm, 0) || covKm <= 0 || covKm > 5 {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_location", "location", *req.Name, false, now, map[string]interface{}{"reason": "invalid_node_coverage"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_node_coverage", "coverageKm must be in (0, 5]")
			return
		}
	}

	handlingMins := 0
	if req.HandlingMinutes != nil {
		handlingMins = *req.HandlingMinutes
		if handlingMins < 0 || handlingMins > 1440 {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_location", "location", *req.Name, false, now, map[string]interface{}{"reason": "invalid_handling_time"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_handling_time", "handlingMinutes must be between 0 and 1440")
			return
		}
	}

	fnStates, okFn := parseLocationFunctionsSlice(req.Functions)
	if !okFn {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_location", "location", *req.Name, false, now, map[string]interface{}{"reason": "invalid_location_function"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_location_function", "Invalid location functions")
		return
	}

	loc := &LocationModel{
		LocationID:          newUUID(),
		Name:                strings.TrimSpace(*req.Name),
		Coordinate:          *req.Coordinate,
		CoverageKm:          covKm,
		HandlingMinutes:     handlingMins,
		Active:              *req.Active,
		Functions:           fnStates,
		ConfiguredFunctions: fnStates,
		Capacity: Capacity{
			CapacityUnits:        100,
			ReservedUnits:        0,
			AvailableUnits:       100,
			CooledCapacityUnits:  100,
			CooledReservedUnits:  0,
			CooledAvailableUnits: 100,
		},
		AcceptedSampleTypes: make(map[string]bool),
	}
	s.state.Locations[loc.LocationID] = loc
	s.recomputeServiceabilitySnapshotLocked()

	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_location", "location", loc.LocationID, true, now, map[string]interface{}{
		"locationId": loc.LocationID,
		"name":       loc.Name,
		"active":     loc.Active,
		"functions":  loc.Functions,
	})
	s.emitRealtimeLocked("location.created", "location", loc.LocationID, locationToDTO(loc))
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, locationToDTO(loc))
}

func (s *Store) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		LocationID      *string     `json:"locationId"`
		Name            *string     `json:"name"`
		Coordinate      *Coordinate `json:"coordinate"`
		CoverageKm      *float64    `json:"coverageKm"`
		HandlingMinutes *int        `json:"handlingMinutes"`
		Functions       *[]string   `json:"functions"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.LocationID == nil || req.Name == nil || req.Coordinate == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if !isValidUUID(*req.LocationID) || strings.TrimSpace(*req.Name) == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid locationId or name")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "update_location", "location", true, "administrator")
	if !ok {
		return
	}

	if !isValidCoordinate(*req.Coordinate) {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_location", "location", *req.LocationID, false, now, map[string]interface{}{"reason": "invalid_coordinate"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_coordinate", "Invalid coordinate")
		return
	}
	if req.CoverageKm != nil {
		cov := *req.CoverageKm
		if math.IsNaN(cov) || math.IsInf(cov, 0) || cov <= 0 || cov > 5 {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_location", "location", *req.LocationID, false, now, map[string]interface{}{"reason": "invalid_node_coverage"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_node_coverage", "coverageKm must be in (0, 5]")
			return
		}
	}
	if req.HandlingMinutes != nil {
		hm := *req.HandlingMinutes
		if hm < 0 || hm > 1440 {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_location", "location", *req.LocationID, false, now, map[string]interface{}{"reason": "invalid_handling_time"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_handling_time", "handlingMinutes must be between 0 and 1440")
			return
		}
	}
	var newFn LocationFunctionStates
	if req.Functions != nil {
		var okFn bool
		newFn, okFn = parseLocationFunctionsSlice(*req.Functions)
		if !okFn {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_location", "location", *req.LocationID, false, now, map[string]interface{}{"reason": "invalid_location_function"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_location_function", "Invalid location functions")
			return
		}
	}

	loc := s.state.Locations[*req.LocationID]
	if loc == nil {
		writeError(w, http.StatusNotFound, "not_found", "Location not found")
		return
	}

	loc.Name = strings.TrimSpace(*req.Name)
	loc.Coordinate = *req.Coordinate
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMinutes = *req.HandlingMinutes
	}
	if req.Functions != nil {
		loc.Functions = newFn
		loc.ConfiguredFunctions = newFn
	}
	s.recomputeServiceabilitySnapshotLocked()

	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_location", "location", loc.LocationID, true, now, locationToDTO(loc))
	s.emitRealtimeLocked("location.updated", "location", loc.LocationID, locationToDTO(loc))
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, locationToDTO(loc))
}

