		s.state.Locations[fromID] == nil || s.state.Locations[toID] == nil ||
		*req.TravelMinutes < 1 || *req.CostUnits < 0 || math.IsNaN(*req.CostUnits) || math.IsInf(*req.CostUnits, 0) {
