		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_connection", "Invalid connection parameters")
		return
	}

	cooled := false
	if req.Cooled != nil {
		cooled = *req.Cooled
	}

	conn := &ConnectionModel{
		ConnectionID:   newUUID(),
		FromLocationID: fromID,
		ToLocationID:   toID,
