	s.recomputeServiceabilitySnapshotLocked()

	resp := map[string]interface{}{
		"connectionId":   conn.ConnectionID,
		"fromLocationId": conn.FromLocationID,
		"toLocationId":   conn.ToLocationID,
		"travelMinutes":  conn.TravelMinutes,
		"costUnits":      conn.CostUnits,
		"cooled":         conn.Cooled,
		"active":         conn.Active,
	}
	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "create_connection", "connection", conn.ConnectionID, true, now, resp)
	s.emitRealtimeLocked("connection.created", "connection", conn.ConnectionID, resp)
