		writeError(w, http.StatusConflict, "capacity_reserved", "Cannot reduce capacity below currently reserved units")
		return
	}

	targetCap.CapacityUnits = capUnits
	targetCap.AvailableUnits = capUnits - targetCap.ReservedUnits
	targetCap.CooledCapacityUnits = cooledUnits
	targetCap.CooledAvailableUnits = cooledUnits - targetCap.CooledReservedUnits

	s.recomputeServiceabilitySnapshotLocked()

	resp := map[string]interface{}{
