func (s *Store) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		WorkerID      *string `json:"workerId"`
		Available     *bool   `json:"available"`
		CapacityUnits *int    `json:"capacityUnits"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.WorkerID == nil || req.Available == nil || req.CapacityUnits == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if !isValidUUID(*req.WorkerID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid workerId")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "set_worker_availability", "user", true)
	if !ok {
		return
	}

	if sess.ActiveRole != "administrator" && sess.ActiveRole != "dispatcher" && actor.UserID != *req.WorkerID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "set_worker_availability", "user", *req.WorkerID, false, now, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Forbidden")
		return
	}

	if *req.CapacityUnits < 0 {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "set_worker_availability", "user", *req.WorkerID, false, now, map[string]interface{}{"reason": "invalid_capacity"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_capacity", "capacityUnits must be >= 0")
		return
	}

	worker := s.state.Users[*req.WorkerID]
	if worker == nil {
		writeError(w, http.StatusNotFound, "not_found", "Worker not found")
		return
	}

	if *req.CapacityUnits < worker.ReservedUnits {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "set_worker_availability", "user", worker.UserID, false, now, map[string]interface{}{"reason": "capacity_reserved"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "capacity_reserved", "Cannot reduce worker capacity below currently reserved units")
		return
	}

	worker.Available = *req.Available
	worker.CapacityUnits = *req.CapacityUnits

	// If worker just became available, check if any pending assignments can be offered to them
	if worker.Available && worker.Active {
		for _, a := range s.state.Assignments {
			if a.Status == "pending" && a.WorkerID == "" {
				j := s.state.Journeys[a.JourneyID]
				if j == nil || (j.Status != "active" && j.Status != "in_progress" && j.Status != "exception") {
					continue
				}
				smp := s.state.Samples[a.SampleID]
				var st *SampleTypeModel
				if smp != nil {
					st = s.state.SampleTypes[smp.SampleTypeID]
				}
				if okElig, _ := s.isWorkerEligibleForAssignmentLocked(worker, a, st, now, true); okElig {
					s.offerAssignmentToWorkerLocked(a, worker, now)
					if smp != nil && smp.Status == "exception" {
						smp.Status = "scheduled"
						smp.Exception = nil
					}
					if j.Status == "exception" {
						j.Status = "active"
					}
				}
			}
		}
	}

	resp := map[string]interface{}{
		"workerId":      worker.UserID,
		"available":     worker.Available,
		"capacityUnits": worker.CapacityUnits,
	}
	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "set_worker_availability", "user", worker.UserID, true, now, resp)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusOK, resp)
}
