package main

import (
	"math"
	"net/http"
	"strings"
	"time"
)

func (s *Store) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Origin               *Coordinate `json:"origin"`
		OriginType           *string     `json:"originType"`
		OriginNodeID         string      `json:"originNodeId"`
		SampleTypeID         *string     `json:"sampleTypeId"`
		RequestedAt          *string     `json:"requestedAt"`
		DeliveryDeadline     *string     `json:"deliveryDeadline"`
		EarliestCollectionAt string      `json:"earliestCollectionAt"`
		LatestCollectionAt   string      `json:"latestCollectionAt"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.Origin == nil || req.SampleTypeID == nil || req.RequestedAt == nil || req.DeliveryDeadline == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	_, _, ok := s.authAndRoleLocked(w, r, "check_serviceability", "serviceability", true, "requester", "dispatcher", "administrator")
	if !ok {
		return
	}

	if !isValidCoordinate(*req.Origin) {
		writeError(w, http.StatusBadRequest, "invalid_origin", "Invalid origin coordinate")
		return
	}
	originType := "home"
	if req.OriginType != nil {
		originType = strings.TrimSpace(*req.OriginType)
		if originType != "home" && originType != "clinic" && originType != "node" {
			writeError(w, http.StatusBadRequest, "invalid_origin_type", "Invalid originType")
			return
		}
	}
	if req.OriginNodeID != "" && !isValidUUID(req.OriginNodeID) {
		writeError(w, http.StatusBadRequest, "invalid_origin", "Invalid originNodeId")
		return
	}
	if !isValidUUID(*req.SampleTypeID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid sampleTypeId")
		return
	}

	reqAt, err1 := parseTime(*req.RequestedAt)
	deadAt, err2 := parseTime(*req.DeliveryDeadline)
	if err1 != nil || err2 != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid timestamp")
		return
	}
	earliestAt := reqAt
	latestAt := deadAt
	if req.EarliestCollectionAt != "" {
		t, err := parseTime(req.EarliestCollectionAt)
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_time", "Invalid earliestCollectionAt")
			return
		}
		earliestAt = t
	}
	if req.LatestCollectionAt != "" {
		t, err := parseTime(req.LatestCollectionAt)
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_time", "Invalid latestCollectionAt")
			return
		}
		latestAt = t
	}
	if earliestAt.After(latestAt) {
		writeError(w, http.StatusBadRequest, "invalid_collection_window", "earliestCollectionAt must not be after latestCollectionAt")
		return
	}
	if !deadAt.After(reqAt) || !deadAt.After(earliestAt) {
		writeError(w, http.StatusBadRequest, "invalid_deadline", "deliveryDeadline must be after requestedAt and earliestCollectionAt")
		return
	}

	st := s.state.SampleTypes[*req.SampleTypeID]
	if st == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample type not found")
		return
	}

	snap := s.getPublishedSnapshot()
	// Pure dry-run evaluation: do not modify state, do not record sample/journey/reservation
	route := s.evaluateServiceabilityAndRouteLocked(*req.Origin, originType, req.OriginNodeID, st, earliestAt, deadAt, 1, false)

	resp := map[string]interface{}{
		"serviceable":           route.Serviceable,
		"reason":                route.Reason,
		"serviceabilityVersion": snap.Version,
	}
	if route.TargetLabID != "" {
		resp["targetLaboratoryId"] = route.TargetLabID
	}
	if !route.EstimatedArrival.IsZero() {
		resp["estimatedArrivalAt"] = formatTime(route.EstimatedArrival)
	}
	writeData(w, http.StatusOK, resp)
}

func (s *Store) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req map[string]interface{}
	if r.ContentLength > 0 {
		if _, err := decodeStrictJSON(r, &req); err != nil || len(req) > 0 {
			writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
			return
		}
	}

	s.mu.Lock()
	_, _, ok := s.authAndRoleLocked(w, r, "read_serviceability_snapshot", "serviceability", true)
	s.mu.Unlock()
	if !ok {
		return
	}

	snap := s.getPublishedSnapshot()
	regions := snap.Regions
	if regions == nil {
		regions = []ServiceabilityRegion{}
	}
	writeData(w, http.StatusOK, map[string]interface{}{
		"version":                    snap.Version,
		"status":                     "complete",
		"computedAt":                 snap.ComputedAt,
		"networkRevision":            snap.NetworkRevision,
		"regions":                    regions,
		"activeCollectionPointCount": snap.ActiveCollectionPointCount,
	})
}

func (s *Store) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	s.handleRequestOrIngest(w, r, false)
}

func (s *Store) handleIngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	s.handleRequestOrIngest(w, r, true)
}

func (s *Store) handleRequestOrIngest(w http.ResponseWriter, r *http.Request, presealed bool) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	opID := "create_collection_request"
	if presealed {
		opID = "ingest_presealed_sample"
	}

	var req struct {
		RequesterID             string      `json:"requesterId"`
		Origin                  *Coordinate `json:"origin"`
		OriginType              *string     `json:"originType"`
		OriginNodeID            string      `json:"originNodeId"`
		RequestedAt             *string     `json:"requestedAt"`
		DeliveryDeadline        *string     `json:"deliveryDeadline"`
		EarliestCollectionAt    string      `json:"earliestCollectionAt"`
		LatestCollectionAt      string      `json:"latestCollectionAt"`
		SampleTypeID            *string     `json:"sampleTypeId"`
		ContainerType           *string     `json:"containerType"`
		TemperatureMinC         *float64    `json:"temperatureMinC"`
		TemperatureMaxC         *float64    `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string    `json:"incompatibleSampleTypes"`
		IdempotencyKey          string      `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.Origin == nil || req.RequestedAt == nil || req.DeliveryDeadline == nil || req.SampleTypeID == nil || req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	var allowedRoles []string
	if presealed {
		allowedRoles = []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}
	} else {
		allowedRoles = []string{"requester", "dispatcher", "administrator"}
	}

	actor, sess, ok := s.authAndRoleLocked(w, r, opID, "sample", true, allowedRoles...)
	if !ok {
		return
	}

	if req.IdempotencyKey != "" {
		stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked(opID, actor.UserID, req.IdempotencyKey, rawBody)
		if conflict {
			writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
			return
		}
		if exists {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(stCode)
			_, _ = w.Write(cachedResp)
			return
		}
	}

	if !isValidCoordinate(*req.Origin) {
		writeError(w, http.StatusBadRequest, "invalid_origin", "Invalid origin coordinate")
		return
	}

	originType := "home"
	if presealed {
		originType = "node"
	}
	if req.OriginType != nil {
		originType = strings.TrimSpace(*req.OriginType)
	}
	if presealed {
		if originType != "clinic" && originType != "node" {
			writeError(w, http.StatusBadRequest, "invalid_origin_type", "Presealed sample origin must be clinic or node")
			return
		}
	} else {
		if originType != "home" && originType != "clinic" && originType != "node" {
			writeError(w, http.StatusBadRequest, "invalid_origin_type", "Invalid originType")
			return
		}
	}

	if req.OriginNodeID != "" {
		if !isValidUUID(req.OriginNodeID) {
			writeError(w, http.StatusBadRequest, "invalid_origin", "Invalid originNodeId")
			return
		}
		loc := s.state.Locations[req.OriginNodeID]
		if loc == nil {
			writeError(w, http.StatusNotFound, "not_found", "Origin node not found")
			return
		}
		if !loc.Active || (!presealed && !loc.Functions.CollectionPoint) {
			writeError(w, http.StatusBadRequest, "invalid_origin_state", "Origin node is inactive")
			return
		}
		if presealed && sess.ActiveRole == "node_handler" && actor.AssignedLocationID != "" && actor.AssignedLocationID != req.OriginNodeID {
			writeError(w, http.StatusBadRequest, "invalid_holder", "Node handler can only ingest presealed samples at their assigned node")
			return
		}
	}

	reqAt, err1 := parseTime(*req.RequestedAt)
	deadAt, err2 := parseTime(*req.DeliveryDeadline)
	if err1 != nil || err2 != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid timestamp")
		return
	}
	earliestAt := reqAt
	latestAt := deadAt
	if req.EarliestCollectionAt != "" {
		t, err := parseTime(req.EarliestCollectionAt)
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_time", "Invalid earliestCollectionAt")
			return
		}
		earliestAt = t
	}
	if req.LatestCollectionAt != "" {
		t, err := parseTime(req.LatestCollectionAt)
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_time", "Invalid latestCollectionAt")
			return
		}
		latestAt = t
	}
	if earliestAt.After(latestAt) {
		writeError(w, http.StatusBadRequest, "invalid_collection_window", "earliestCollectionAt must not be after latestCollectionAt")
		return
	}
	if !deadAt.After(reqAt) || !deadAt.After(earliestAt) {
		writeError(w, http.StatusBadRequest, "invalid_deadline", "deliveryDeadline must be after requestedAt and earliestCollectionAt")
		return
	}

	if !isValidUUID(*req.SampleTypeID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid sampleTypeId")
		return
	}
	st := s.state.SampleTypes[*req.SampleTypeID]
	if st == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample type not found")
		return
	}

	// Check handling rules match sampleType
	if strings.TrimSpace(*req.ContainerType) != st.ContainerType ||
		math.IsNaN(*req.TemperatureMinC) || math.IsNaN(*req.TemperatureMaxC) ||
		*req.TemperatureMinC > *req.TemperatureMaxC ||
		*req.TemperatureMinC < st.TemperatureMinC-1e-6 ||
		*req.TemperatureMaxC > st.TemperatureMaxC+1e-6 {
		writeError(w, http.StatusBadRequest, "handling_mismatch", "Request handling attributes do not match sample type rules")
		return
	}

	requesterID := actor.UserID
	if req.RequesterID != "" {
		if !isValidUUID(req.RequesterID) {
			writeError(w, http.StatusBadRequest, "invalid_json", "Invalid requesterId")
			return
		}
		if sess.ActiveRole == "requester" && req.RequesterID != actor.UserID {
			writeError(w, http.StatusForbidden, "forbidden", "Requester cannot create request for another user")
			return
		}
		requesterID = req.RequesterID
	}

	incomp := req.IncompatibleSampleTypes
	if len(incomp) == 0 {
		incomp = append([]string{}, st.IncompatibleSampleTypes...)
	}

	// Evaluate route and serviceability
	route := s.evaluateServiceabilityAndRouteLocked(*req.Origin, originType, req.OriginNodeID, st, earliestAt, deadAt, 1, presealed)
	if !route.Serviceable {
		if route.Reason == "insufficient_capacity" {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, opID, "sample", "none", false, now, map[string]interface{}{"reason": route.ConflictCode})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusConflict, route.ConflictCode, "Insufficient capacity available")
			return
		}
		// Unserviceable request: record sample with serviceability="unserviceable" and return 201
		reqID := newUUID()
		smpID := newUUID()
		smp := &SampleModel{
			SampleID:                 smpID,
			RequestID:                reqID,
			RequesterID:              requesterID,
			Origin:                   *req.Origin,
			OriginType:               originType,
			OriginNodeID:             req.OriginNodeID,
			RequestedAt:              formatTime(reqAt),
			DeliveryDeadline:         formatTime(deadAt),
			EarliestCollectionAt:     formatTime(earliestAt),
			LatestCollectionAt:       formatTime(latestAt),
			SampleTypeID:             st.SampleTypeID,
			ContainerType:            *req.ContainerType,
			TemperatureMinC:          *req.TemperatureMinC,
			TemperatureMaxC:          *req.TemperatureMaxC,
			IncompatibleSampleTypes:  incomp,
			Serviceability:           "unserviceable",
			ServiceabilityReason:     route.Reason,
			Status:                   "unserviceable",
			Sealed:                   presealed,
			CompletedLegIDs:          []string{},
			ActiveReplacementPlanIDs: []string{},
			Timeline:                 []TimelineEntry{},
			LatestLocation:           req.Origin,
			LocationRecordedAt:       formatTime(reqAt),
		}
		if presealed {
			smp.CurrentHolderID = actor.UserID
			smp.SealedAt = formatTime(reqAt)
		}
		ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, opID, "sample", smp.SampleID, true, reqAt, map[string]interface{}{
			"requestId":            reqID,
			"sampleId":             smpID,
			"serviceability":       "unserviceable",
			"serviceabilityReason": route.Reason,
		})
		smp.Timeline = append(smp.Timeline, ev)
		s.state.Samples[smp.SampleID] = smp

		respData := map[string]interface{}{
			"requestId":            reqID,
			"sampleId":             smpID,
			"serviceability":       "unserviceable",
			"serviceabilityReason": route.Reason,
			"activeAssignmentIds":  []string{},
			"earliestCollectionAt": smp.EarliestCollectionAt,
			"latestCollectionAt":   smp.LatestCollectionAt,
			"alreadySealed":        presealed,
			"originType":           originType,
		}
		s.saveIdempotencyLocked(opID, actor.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		_ = s.persistLocked(r.Context())
		writeData(w, http.StatusCreated, respData)
		return
	}

	reqID := newUUID()
	smpID := newUUID()
	initStatus := "scheduled"
	if presealed {
		initStatus = "sealed"
	}
	smp := &SampleModel{
		SampleID:                 smpID,
		RequestID:                reqID,
		RequesterID:              requesterID,
		Origin:                   *req.Origin,
		OriginType:               originType,
		OriginNodeID:             route.StartNodeID,
		RequestedAt:              formatTime(reqAt),
		DeliveryDeadline:         formatTime(deadAt),
		EarliestCollectionAt:     formatTime(earliestAt),
		LatestCollectionAt:       formatTime(latestAt),
		SampleTypeID:             st.SampleTypeID,
		ContainerType:            *req.ContainerType,
		TemperatureMinC:          *req.TemperatureMinC,
		TemperatureMaxC:          *req.TemperatureMaxC,
		IncompatibleSampleTypes:  incomp,
		Serviceability:           "serviceable",
		ServiceabilityReason:     "serviceable",
		Status:                   initStatus,
		Sealed:                   presealed,
		TargetLaboratoryID:       route.TargetLabID,
		CurrentLocationID:        route.StartNodeID,
		CompletedLegIDs:          []string{},
		ActiveReplacementPlanIDs: []string{},
		Timeline:                 []TimelineEntry{},
		LatestLocation:           req.Origin,
		LocationRecordedAt:       formatTime(reqAt),
	}
	if presealed {
		smp.CurrentHolderID = actor.UserID
		smp.SealedAt = formatTime(reqAt)
	}
	s.state.Samples[smp.SampleID] = smp

	evCreate := s.recordAuditLocked(actor.UserID, sess.ActiveRole, opID, "sample", smp.SampleID, true, reqAt, map[string]interface{}{
		"requestId":          reqID,
		"sampleId":           smpID,
		"originType":         originType,
		"alreadySealed":      presealed,
		"targetLaboratoryId": route.TargetLabID,
	})
	smp.Timeline = append(smp.Timeline, evCreate)

	journey, activeAssignIDs, _ := s.buildJourneyForSampleLocked(smp, st, route, presealed, actor.UserID, sess.ActiveRole, reqAt)
	smp.ActiveJourneyID = journey.JourneyID
	if activeAssignIDs == nil {
		activeAssignIDs = []string{}
	}

	// If presealed, also create a synthetic holder assignment if needed so the holder can initiate handoff from an assignment
	if presealed && len(activeAssignIDs) > 0 {
		// If the actor is the worker offered the first transport leg, or if they need a fromAssignmentId
		firstAss := s.state.Assignments[activeAssignIDs[0]]
		if firstAss != nil && firstAss.WorkerID == actor.UserID {
			firstAss.Status = "accepted"
		}
	}

	respData := map[string]interface{}{
		"requestId":            reqID,
		"sampleId":             smpID,
		"serviceability":       "serviceable",
		"serviceabilityReason": "serviceable",
		"activeAssignmentIds":  activeAssignIDs,
		"earliestCollectionAt": smp.EarliestCollectionAt,
		"latestCollectionAt":   smp.LatestCollectionAt,
		"journeyId":            journey.JourneyID,
		"targetLaboratoryId":   route.TargetLabID,
		"alreadySealed":        presealed,
		"originType":           originType,
	}
	s.saveIdempotencyLocked(opID, actor.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("sample.created", "sample", smp.SampleID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) isSampleLocationStaleLocked(smp *SampleModel) bool {
	if smp == nil || smp.LocationRecordedAt == "" {
		return false
	}
	if smp.Status == "received" || smp.Status == "cancelled" || smp.Status == "expired" {
		return false
	}
	t, err := parseTime(smp.LocationRecordedAt)
	if err != nil {
		return false
	}
	now := time.Now().UTC()
	if now.Sub(t) > 15*time.Minute {
		return true
	}
	// Also check if sample has a worker who recorded a stale/older location or if last progress is > 15m after locationRecordedAt
	if smp.ActiveJourneyID != "" {
		if j := s.state.Journeys[smp.ActiveJourneyID]; j != nil {
			for _, aid := range j.AssignmentIDs {
				if a := s.state.Assignments[aid]; a != nil && a.LastProgressAt != "" {
					if pt, err := parseTime(a.LastProgressAt); err == nil {
						if pt.Sub(t) > 15*time.Minute {
							return true
						}
					}
				}
			}
		}
	}
	return false
}

func (s *Store) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		Role   *string `json:"role"`
		Status *string `json:"status"`
	}
	if r.ContentLength > 0 {
		if _, err := decodeStrictJSON(r, &req); err != nil {
			writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
			return
		}
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "list_role_work", "work", true)
	if !ok {
		return
	}

	role := sess.ActiveRole
	if req.Role != nil && *req.Role != "" {
		rName := strings.TrimSpace(*req.Role)
		if !validRoles[rName] {
			writeError(w, http.StatusBadRequest, "invalid_role", "Invalid role")
			return
		}
		if rName != sess.ActiveRole {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "list_role_work", "work", actor.UserID, false, now, map[string]interface{}{"requestedRole": rName, "activeRole": sess.ActiveRole, "reason": "forbidden"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "Cannot list work for a role different from activeRole")
			return
		}
		role = rName
	}

	pending := []interface{}{}
	inProgress := []interface{}{}
	completed := []interface{}{}

	switch role {
	case "requester":
		for _, smp := range s.state.Samples {
			if smp.RequesterID != actor.UserID {
				continue
			}
			hist := smp.Timeline
			if hist == nil {
				hist = []TimelineEntry{}
			}
			item := map[string]interface{}{
				"kind":                 "sample",
				"sampleId":             smp.SampleID,
				"sample_id":            smp.SampleID,
				"requestId":            smp.RequestID,
				"status":               smp.Status,
				"serviceability":       smp.Serviceability,
				"requestedAt":          smp.RequestedAt,
				"deliveryDeadline":     smp.DeliveryDeadline,
				"earliestCollectionAt": smp.EarliestCollectionAt,
				"latestCollectionAt":   smp.LatestCollectionAt,
				"requesterId":          smp.RequesterID,
				"history":              hist,
				"locationStale":        s.isSampleLocationStaleLocked(smp),
			}
			if smp.ActiveJourneyID != "" {
				item["journeyId"] = smp.ActiveJourneyID
				item["activeJourneyId"] = smp.ActiveJourneyID
			}
			if smp.TargetLaboratoryID != "" {
				item["laboratoryId"] = smp.TargetLaboratoryID
			}
			if smp.CurrentHolderID != "" {
				item["currentHolderId"] = smp.CurrentHolderID
			}
			if smp.LocationRecordedAt != "" {
				item["locationRecordedAt"] = smp.LocationRecordedAt
			}
			switch smp.Status {
			case "received", "completed", "cancelled", "expired":
				completed = append(completed, item)
			case "sealed", "in_transit", "at_node":
				inProgress = append(inProgress, item)
			default:
				pending = append(pending, item)
			}
		}

	case "dispatcher", "administrator":
		for _, j := range s.state.Journeys {
			hist := j.History
			if hist == nil {
				hist = []TimelineEntry{}
			}
			sids := j.SampleIDs
			if sids == nil {
				sids = []string{}
			}
			item := map[string]interface{}{
				"kind":                "journey",
				"journeyId":           j.JourneyID,
				"journey_id":          j.JourneyID,
				"status":              j.Status,
				"routeMode":           j.RouteMode,
				"planVersion":         j.PlanVersion,
				"sampleIds":           sids,
				"estimatedDeliveryAt": j.EstimatedDeliveryAt,
				"assignmentCount":     len(j.AssignmentIDs),
				"history":             hist,
			}
			switch j.Status {
			case "completed", "cancelled", "replaced", "expired":
				completed = append(completed, item)
			case "in_progress":
				inProgress = append(inProgress, item)
			default:
				pending = append(pending, item)
			}
		}

	case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		wantKind := ""
		switch role {
		case "collection_professional":
			wantKind = "collection"
		case "delivery_partner":
			wantKind = "transport"
		case "node_handler":
			wantKind = "node"
		case "laboratory_team":
			wantKind = "laboratory"
		}
		for _, a := range s.state.Assignments {
			if a.Kind != wantKind {
				continue
			}
			// Check if assigned/offered to this worker, or in their history
			isMine := a.WorkerID == actor.UserID || a.OfferedToWorkerID == actor.UserID
			if !isMine && (a.Status == "pending" || a.Status == "offered") && a.WorkerID == "" {
				smp := s.state.Samples[a.SampleID]
				var st *SampleTypeModel
				if smp != nil {
					st = s.state.SampleTypes[smp.SampleTypeID]
				}
				if okElig, _ := s.isWorkerEligibleForAssignmentLocked(actor, a, st, now, false); okElig {
					isMine = true
				}
			}
			if !isMine {
				continue
			}

			hist := a.History
			if hist == nil {
				hist = []TimelineEntry{}
			}
			item := map[string]interface{}{
				"kind":          a.Kind,
				"assignmentId":  a.AssignmentID,
				"assignment_id": a.AssignmentID,
				"sampleId":      a.SampleID,
				"sample_id":     a.SampleID,
				"status":        a.Status,
				"journeyId":     a.JourneyID,
				"sequence":      a.Sequence,
				"history":       hist,
			}
			if a.FromLocationID != "" {
				item["fromLocationId"] = a.FromLocationID
			}
			if a.ToLocationID != "" {
				item["toLocationId"] = a.ToLocationID
			}
			if a.OfferExpiresAt != "" {
				item["offerExpiresAt"] = a.OfferExpiresAt
			}
			if a.NodeID != "" {
				item["nodeId"] = a.NodeID
				if loc := s.state.Locations[a.NodeID]; loc != nil {
					item["destinationCapacity"] = loc.Capacity
				}
			}
			if a.IncomingFromLocationID != "" {
				item["incomingFromLocationId"] = a.IncomingFromLocationID
			}
			if a.OutgoingToLocationID != "" {
				item["outgoingToLocationId"] = a.OutgoingToLocationID
			}
			if a.LaboratoryID != "" {
				item["laboratoryId"] = a.LaboratoryID
				if loc := s.state.Locations[a.LaboratoryID]; loc != nil {
					item["destinationCapacity"] = loc.Capacity
				}
			}
			if a.ExpectedSampleTypeID != "" {
				item["expectedSampleTypeId"] = a.ExpectedSampleTypeID
			}
			if _, hasCap := item["destinationCapacity"]; !hasCap && a.ToLocationID != "" {
				if loc := s.state.Locations[a.ToLocationID]; loc != nil {
					item["destinationCapacity"] = loc.Capacity
				}
			}

			switch a.Status {
			case "completed", "delivered", "cancelled", "declined":
				completed = append(completed, item)
			case "accepted", "at_pickup", "picked_up", "in_transit", "arrived", "in_progress":
				inProgress = append(inProgress, item)
			default:
				pending = append(pending, item)
			}
		}
	}

	writeData(w, http.StatusOK, map[string]interface{}{
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	})
}

func (s *Store) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		AssignmentID   *string `json:"assignmentId"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.AssignmentID == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.AssignmentID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid assignmentId")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "accept_assignment", "assignment", true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("accept_assignment", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	a := s.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "Assignment not found")
		return
	}

	j := s.state.Journeys[a.JourneyID]
	if j != nil && (j.Status == "cancelled" || j.Status == "replaced" || j.Status == "expired") {
		writeError(w, http.StatusConflict, "assignment_inactive", "Assignment belongs to an inactive journey")
		return
	}
	if a.Status == "cancelled" || a.Status == "completed" || a.Status == "delivered" {
		writeError(w, http.StatusConflict, "assignment_inactive", "Assignment is no longer active")
		return
	}

	// Check role matches assignment kind
	expectedRole := ""
	switch a.Kind {
	case "collection":
		expectedRole = "collection_professional"
	case "transport":
		expectedRole = "delivery_partner"
	case "node":
		expectedRole = "node_handler"
	case "laboratory":
		expectedRole = "laboratory_team"
	}
	if sess.ActiveRole != expectedRole {
		s.state.IneligibleAttempts++
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, false, now, map[string]interface{}{"reason": "ineligible_worker"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "ineligible_worker", "Active role does not match assignment kind")
		return
	}

	smp := s.state.Samples[a.SampleID]
	var st *SampleTypeModel
	if smp != nil {
		st = s.state.SampleTypes[smp.SampleTypeID]
	}

	okQual, errCode := s.isWorkerEligibleForAssignmentLocked(actor, a, st, now, false)
	if !okQual {
		s.state.IneligibleAttempts++
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, false, now, map[string]interface{}{"reason": errCode})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "ineligible_worker", "Worker is not eligible for this assignment")
		return
	}

	if !actor.Available || actor.CapacityUnits <= 0 {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, false, now, map[string]interface{}{"reason": "worker_unavailable"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "worker_unavailable", "Worker is unavailable")
		return
	}

	// Check if offered to someone else or already accepted by someone else
	if a.Status == "accepted" || a.Status == "in_progress" || a.Status == "at_pickup" || a.Status == "picked_up" || a.Status == "in_transit" || a.Status == "arrived" {
		if a.WorkerID != actor.UserID {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, false, now, map[string]interface{}{"reason": "assignment_taken"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusConflict, "assignment_taken", "Assignment already accepted by another worker")
			return
		}
	}

	if a.OfferedToWorkerID != "" && a.OfferedToWorkerID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, false, now, map[string]interface{}{"reason": "offer_not_offered"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "offer_not_offered", "Assignment was not offered to this worker")
		return
	}
	if a.OfferedToWorkerID == "" && a.WorkerID != "" && a.WorkerID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, false, now, map[string]interface{}{"reason": "offer_not_offered"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "offer_not_offered", "Assignment was not offered to this worker")
		return
	}

	a.WorkerID = actor.UserID
	a.OfferedToWorkerID = actor.UserID
	a.Status = "accepted"
	a.AcceptedAt = formatTime(now)
	if !a.CapacityReserved {
		a.CapacityReserved = true
		actor.ReservedUnits++
		if j != nil {
			j.Reservations = append(j.Reservations, CapacityReservation{
				ResourceID: actor.UserID,
				Kind:       "worker",
				Regular:    1,
			})
		}
	}

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, true, now, map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"workerId":     actor.UserID,
		"status":       "accepted",
	})
	a.History = append(a.History, ev)
	if smp != nil {
		smp.Timeline = append(smp.Timeline, ev)
	}
	if j != nil {
		j.History = append(j.History, ev)
	}

	respData := map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"workerId":     actor.UserID,
		"status":       "accepted",
	}
	s.saveIdempotencyLocked("accept_assignment", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("assignment.accepted", "assignment", a.AssignmentID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		AssignmentID   *string `json:"assignmentId"`
		Reason         string  `json:"reason"`
		DeclinedAt     string  `json:"declinedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.AssignmentID == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.AssignmentID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid assignmentId")
		return
	}

	declinedTime := time.Now().UTC()
	if req.DeclinedAt != "" {
		t, err := parseTime(req.DeclinedAt)
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_time", "Invalid declinedAt timestamp")
			return
		}
		declinedTime = t
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "decline_assignment", "assignment", true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("decline_assignment", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	a := s.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "Assignment not found")
		return
	}

	if (a.OfferedToWorkerID != "" && a.OfferedToWorkerID != actor.UserID) ||
		(a.OfferedToWorkerID == "" && a.WorkerID != "" && a.WorkerID != actor.UserID) ||
		a.Status == "completed" || a.Status == "delivered" || a.Status == "cancelled" {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "decline_assignment", "assignment", a.AssignmentID, false, declinedTime, map[string]interface{}{"reason": "offer_not_available"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "offer_not_available", "Offer is not available to this worker")
		return
	}

	if a.DeclinedByWorkerIDs == nil {
		a.DeclinedByWorkerIDs = make(map[string]bool)
	}
	a.DeclinedByWorkerIDs[actor.UserID] = true
	actor.DeclineCount++
	actor.LastDeclinedAt = formatTime(declinedTime)
	if a.CapacityReserved {
		a.CapacityReserved = false
		actor.ReservedUnits--
		if actor.ReservedUnits < 0 {
			actor.ReservedUnits = 0
		}
	}

	a.WorkerID = ""
	a.OfferedToWorkerID = ""
	a.Status = "pending"

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "decline_assignment", "assignment", a.AssignmentID, true, declinedTime, map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"declinedBy":   actor.UserID,
		"reason":       req.Reason,
	})
	a.History = append(a.History, ev)

	smp := s.state.Samples[a.SampleID]
	var st *SampleTypeModel
	if smp != nil {
		smp.Timeline = append(smp.Timeline, ev)
		st = s.state.SampleTypes[smp.SampleTypeID]
	}

	// Re-offer to next eligible worker (without excluding forever if only declined workers remain)
	nextW, _ := s.selectFairEligibleWorkerLocked(a, st, declinedTime, false)
	if nextW == nil {
		// Check if any other eligible worker exists besides actor; if none, keep pending or reoffer
	}
	reofferedTo := ""
	if nextW != nil {
		s.offerAssignmentToWorkerLocked(a, nextW, declinedTime)
		reofferedTo = nextW.UserID
	}

	respData := map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"status":       "pending",
		"declinedBy":   actor.UserID,
		"declinedAt":   formatTime(declinedTime),
	}
	if reofferedTo != "" {
		respData["reofferedTo"] = reofferedTo
	}
	s.saveIdempotencyLocked("decline_assignment", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("assignment.declined", "assignment", a.AssignmentID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		SampleID             *string  `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		CollectedAt          *string  `json:"collectedAt"`
		ContainerType        *string  `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey       *string  `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.SampleID == nil || req.AssignmentID == nil || req.CollectedAt == nil || req.ContainerType == nil || req.ObservedTemperatureC == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.SampleID) || !isValidUUID(*req.AssignmentID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid UUID")
		return
	}
	collectedAt, err := parseTime(*req.CollectedAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid collectedAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "collect_and_seal_sample", "sample", true, "collection_professional")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("collect_and_seal_sample", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	smp := s.state.Samples[*req.SampleID]
	a := s.state.Assignments[*req.AssignmentID]
	if smp == nil || a == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample or assignment not found")
		return
	}
	if a.SampleID != smp.SampleID || a.Kind != "collection" {
		writeError(w, http.StatusConflict, "collection_not_ready", "Assignment is not the collection assignment for this sample")
		return
	}
	j := s.state.Journeys[a.JourneyID]
	if (j != nil && (j.Status == "cancelled" || j.Status == "replaced" || j.Status == "expired")) || a.Status == "cancelled" {
		writeError(w, http.StatusConflict, "assignment_inactive", "Assignment is inactive")
		return
	}
	if a.WorkerID != actor.UserID && a.OfferedToWorkerID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", smp.SampleID, false, collectedAt, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Worker is not assigned to this collection")
		return
	}
	if a.Status != "accepted" && a.Status != "in_progress" && a.Status != "at_pickup" {
		writeError(w, http.StatusConflict, "collection_not_ready", "Collection assignment must be accepted before collecting and sealing")
		return
	}
	if smp.Sealed || smp.Status == "sealed" || smp.Status == "in_transit" || smp.Status == "received" || smp.Status == "cancelled" {
		writeError(w, http.StatusConflict, "invalid_sample_state", "Sample is already sealed or in terminal state")
		return
	}

	st := s.state.SampleTypes[smp.SampleTypeID]
	hasQual, certActive := isWorkerCertifiedForSampleType(actor, st, collectedAt)
	if !hasQual {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", smp.SampleID, false, collectedAt, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Collector does not hold required qualification")
		return
	}
	if !certActive {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", smp.SampleID, false, collectedAt, map[string]interface{}{"reason": "certification_inactive"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "certification_inactive", "Collector certification is inactive or expired")
		return
	}

	// Check collection window
	earliest, errE := parseTime(smp.EarliestCollectionAt)
	latest, errL := parseTime(smp.LatestCollectionAt)
	if errE == nil && errL == nil {
		if collectedAt.Before(earliest) || collectedAt.After(latest) {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", smp.SampleID, false, collectedAt, map[string]interface{}{"reason": "outside_collection_window"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusConflict, "outside_collection_window", "Collection timestamp is outside the allowed collection window")
			return
		}
	}
	if reqAt, errR := parseTime(smp.RequestedAt); errR == nil && collectedAt.Before(reqAt) {
		writeError(w, http.StatusConflict, "invalid_collection_time", "Collection time cannot be before request time")
		return
	}

	// Check handling compliance
	obsTemp := *req.ObservedTemperatureC
	obsCont := strings.TrimSpace(*req.ContainerType)
	if obsCont != smp.ContainerType || math.IsNaN(obsTemp) || obsTemp < smp.TemperatureMinC || obsTemp > smp.TemperatureMaxC {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", smp.SampleID, false, collectedAt, map[string]interface{}{"reason": "handling_noncompliant"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusBadRequest, "handling_noncompliant", "Observed container or temperature is non-compliant")
		return
	}

	smp.Sealed = true
	smp.SealedAt = formatTime(collectedAt)
	smp.Status = "sealed"
	smp.CurrentHolderID = actor.UserID
	smp.LocationRecordedAt = formatTime(collectedAt)

	a.Status = "completed"
	a.CompletedAt = formatTime(collectedAt)
	a.LastProgressAt = formatTime(collectedAt)
	smp.CompletedLegIDs = append(smp.CompletedLegIDs, a.AssignmentID)

	if j != nil && len(j.OrderedStops) > 0 {
		j.OrderedStops[0].CompletedAt = formatTime(collectedAt)
		j.Status = "in_progress"
	}

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", smp.SampleID, true, collectedAt, map[string]interface{}{
		"sampleId":             smp.SampleID,
		"assignmentId":         a.AssignmentID,
		"currentHolderId":      actor.UserID,
		"sealedAt":             smp.SealedAt,
		"containerType":        obsCont,
		"observedTemperatureC": obsTemp,
	})
	smp.Timeline = append(smp.Timeline, ev)
	a.History = append(a.History, ev)
	if j != nil {
		j.History = append(j.History, ev)
	}

	respData := map[string]interface{}{
		"sampleId":          smp.SampleID,
		"status":            "sealed",
		"currentHolderId":   actor.UserID,
		"sealedAt":          smp.SealedAt,
		"handlingCompliant": true,
	}
	s.saveIdempotencyLocked("collect_and_seal_sample", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("sample.sealed", "sample", smp.SampleID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		AssignmentID   *string `json:"assignmentId"`
		Status         *string `json:"status"`
		OccurredAt     *string `json:"occurredAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.AssignmentID == nil || req.Status == nil || req.OccurredAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.AssignmentID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid assignmentId")
		return
	}
	validStatuses := map[string]bool{
		"at_pickup":   true,
		"picked_up":   true,
		"in_transit":  true,
		"arrived":     true,
		"delivered":   true,
		"in_progress": true,
		"completed":   true,
	}
	newStatus := strings.TrimSpace(*req.Status)
	if !validStatuses[newStatus] {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid status")
		return
	}
	occAt, err := parseTime(*req.OccurredAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid occurredAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "update_assignment_progress", "assignment", true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("update_assignment_progress", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	a := s.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "Assignment not found")
		return
	}

	if a.WorkerID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", a.AssignmentID, false, occAt, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		if a.Status == "offered" || a.Status == "pending" {
			writeError(w, http.StatusConflict, "assignment_not_ready", "Assignment must be accepted first")
			return
		}
		writeError(w, http.StatusForbidden, "forbidden", "Worker is not assigned to this assignment")
		return
	}

	j := s.state.Journeys[a.JourneyID]
	if (j != nil && (j.Status == "cancelled" || j.Status == "replaced" || j.Status == "expired")) || a.Status == "cancelled" {
		writeError(w, http.StatusConflict, "assignment_inactive", "Assignment belongs to an inactive journey")
		return
	}
	if a.Status == "offered" || a.Status == "pending" {
		writeError(w, http.StatusConflict, "assignment_not_ready", "Assignment has not been accepted yet")
		return
	}
	if a.Status == "completed" || a.Status == "delivered" {
		writeError(w, http.StatusConflict, "invalid_transition", "Assignment is already completed")
		return
	}

	if a.LastProgressAt != "" {
		if prevT, err := parseTime(a.LastProgressAt); err == nil && occAt.Before(prevT) {
			writeError(w, http.StatusConflict, "invalid_progress_time", "Progress timestamp precedes previous progress timestamp")
			return
		}
	}
	if a.AcceptedAt != "" {
		if accT, err := parseTime(a.AcceptedAt); err == nil && occAt.Before(accT) {
			writeError(w, http.StatusConflict, "invalid_progress_time", "Progress timestamp precedes acceptance timestamp")
			return
		}
	}

	smp := s.state.Samples[a.SampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample not found")
		return
	}

	// Check deadline if delivering
	if deadT, err := parseTime(smp.DeliveryDeadline); err == nil && occAt.After(deadT) && (newStatus == "delivered" || newStatus == "completed") {
		writeError(w, http.StatusConflict, "delivery_deadline_exceeded", "Delivery deadline exceeded")
		return
	}

	if a.Kind == "transport" {
		if !smp.Sealed {
			writeError(w, http.StatusConflict, "collection_required", "Sample must be collected and sealed before transport")
			return
		}
		// Check prior leg completion
		if j != nil {
			for _, aid := range j.AssignmentIDs {
				if aid == a.AssignmentID {
					break
				}
				prev := s.state.Assignments[aid]
				if prev != nil && (prev.Kind == "collection" || prev.Kind == "transport") {
					if prev.Status != "completed" && prev.Status != "delivered" {
						writeError(w, http.StatusConflict, "prior_leg_incomplete", "Prior leg is not yet complete")
						return
					}
				}
			}
		}

		// Transition ordering: pickup must happen before delivery, and custody is required for picked_up / in_transit / arrived / delivered
		switch newStatus {
		case "at_pickup":
			if a.Status != "accepted" && a.Status != "at_pickup" {
				writeError(w, http.StatusConflict, "invalid_transition", "Cannot transition to at_pickup from current status")
				return
			}
		case "picked_up", "in_transit":
			if smp.CurrentHolderID != actor.UserID {
				writeError(w, http.StatusConflict, "custody_required", "Worker must hold custody of the sample before transport")
				return
			}
			if a.Status == "delivered" || a.Status == "completed" {
				writeError(w, http.StatusConflict, "invalid_transition", "Invalid status transition")
				return
			}
		case "arrived", "delivered", "completed":
			if smp.CurrentHolderID != actor.UserID {
				writeError(w, http.StatusConflict, "custody_required", "Worker must hold custody of the sample")
				return
			}
			if a.Status == "accepted" || a.Status == "at_pickup" {
				writeError(w, http.StatusConflict, "invalid_transition", "Sample must be picked_up or in_transit before delivery")
				return
			}
		}
	} else if a.Kind == "node" || a.Kind == "laboratory" {
		if !smp.Sealed {
			writeError(w, http.StatusConflict, "collection_required", "Sample must be collected and sealed first")
			return
		}
	}

	// Apply status update to assignment (and all batched samples on this assignment if any)
	a.Status = newStatus
	a.LastProgressAt = formatTime(occAt)
	if a.StartedAt == "" {
		a.StartedAt = formatTime(occAt)
	}
	if newStatus == "delivered" || newStatus == "completed" {
		a.CompletedAt = formatTime(occAt)
		alreadyCompleted := false
		for _, cid := range smp.CompletedLegIDs {
			if cid == a.AssignmentID {
				alreadyCompleted = true
				break
			}
		}
		if !alreadyCompleted {
			smp.CompletedLegIDs = append(smp.CompletedLegIDs, a.AssignmentID)
		}
		if a.ToLocationID != "" {
			smp.CurrentLocationID = a.ToLocationID
			if loc := s.state.Locations[a.ToLocationID]; loc != nil {
				c := loc.Coordinate
				smp.LatestLocation = &c
				smp.LocationRecordedAt = formatTime(occAt)
			}
		}
	} else if newStatus == "picked_up" || newStatus == "in_transit" {
		smp.Status = "in_transit"
	} else if newStatus == "arrived" {
		if a.ToLocationID != "" {
			smp.CurrentLocationID = a.ToLocationID
			if loc := s.state.Locations[a.ToLocationID]; loc != nil {
				c := loc.Coordinate
				smp.LatestLocation = &c
				smp.LocationRecordedAt = formatTime(occAt)
			}
		}
	}

	if j != nil && j.Status == "active" {
		j.Status = "in_progress"
	}

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", a.AssignmentID, true, occAt, map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"sampleId":     a.SampleID,
		"status":       newStatus,
	})
	a.History = append(a.History, ev)
	smp.Timeline = append(smp.Timeline, ev)
	if j != nil {
		j.History = append(j.History, ev)
	}

	respData := map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"sampleId":     a.SampleID,
		"status":       newStatus,
	}
	s.saveIdempotencyLocked("update_assignment_progress", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("assignment.progress", "assignment", a.AssignmentID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		AssignmentID *string     `json:"assignmentId"`
		Coordinate   *Coordinate `json:"coordinate"`
		Sequence     *int        `json:"sequence"`
		RecordedAt   *string     `json:"recordedAt"`
	}
	if _, err := decodeStrictJSON(r, &req); err != nil || req.AssignmentID == nil || req.Coordinate == nil || req.Sequence == nil || req.RecordedAt == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if !isValidUUID(*req.AssignmentID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid assignmentId")
		return
	}
	if !isValidCoordinate(*req.Coordinate) {
		writeError(w, http.StatusBadRequest, "invalid_coordinate", "Invalid coordinate")
		return
	}
	if *req.Sequence < 1 {
		writeError(w, http.StatusBadRequest, "invalid_sequence", "sequence must be >= 1")
		return
	}
	recAt, err := parseTime(*req.RecordedAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid recordedAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "record_worker_location", "assignment", true, "collection_professional", "delivery_partner")
	if !ok {
		return
	}

	a := s.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "Assignment not found")
		return
	}
	if a.WorkerID != actor.UserID && a.OfferedToWorkerID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "record_worker_location", "assignment", a.AssignmentID, false, recAt, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Worker is not assigned to this assignment")
		return
	}

	if actor.AssignmentLocSeq == nil {
		actor.AssignmentLocSeq = make(map[string]int)
	}
	prevSeq := actor.AssignmentLocSeq[a.AssignmentID]
	if *req.Sequence <= prevSeq {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "record_worker_location", "assignment", a.AssignmentID, false, recAt, map[string]interface{}{"reason": "stale_location"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "stale_location", "Out-of-order or duplicate location sequence")
		return
	}
	if actor.LocationRecordedAt != "" {
		if prevT, err := parseTime(actor.LocationRecordedAt); err == nil && recAt.Before(prevT) {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "record_worker_location", "assignment", a.AssignmentID, false, recAt, map[string]interface{}{"reason": "stale_location"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusConflict, "stale_location", "Location timestamp is older than latest recorded location")
			return
		}
	}

	actor.AssignmentLocSeq[a.AssignmentID] = *req.Sequence
	c := *req.Coordinate
	actor.LatestLocation = &c
	actor.LocationRecordedAt = formatTime(recAt)

	// Update sample location if worker holds custody of sample or is active on it
	for _, sid := range a.SampleIDs {
		if smp := s.state.Samples[sid]; smp != nil {
			if smp.CurrentHolderID == actor.UserID || smp.CurrentHolderID == "" {
				sc := *req.Coordinate
				smp.LatestLocation = &sc
				smp.LocationRecordedAt = formatTime(recAt)
			}
		}
	}
	if smp := s.state.Samples[a.SampleID]; smp != nil {
		if smp.CurrentHolderID == actor.UserID || smp.CurrentHolderID == "" {
			sc := *req.Coordinate
			smp.LatestLocation = &sc
			smp.LocationRecordedAt = formatTime(recAt)
		}
	}

	respData := map[string]interface{}{
		"assignmentId": a.AssignmentID,
		"coordinate":   *req.Coordinate,
		"sequence":     *req.Sequence,
		"recordedAt":   formatTime(recAt),
	}
	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "record_worker_location", "assignment", a.AssignmentID, true, recAt, respData)
	a.History = append(a.History, ev)
	s.emitRealtimeLocked("worker.location", "user", actor.UserID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		SampleID         *string `json:"sampleId"`
		FromAssignmentID *string `json:"fromAssignmentId"`
		ToAssignmentID   *string `json:"toAssignmentId"`
		ReceiverID       *string `json:"receiverId"`
		InitiatedAt      *string `json:"initiatedAt"`
		IdempotencyKey   *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.SampleID == nil || req.FromAssignmentID == nil || req.ToAssignmentID == nil || req.ReceiverID == nil || req.InitiatedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.SampleID) || !isValidUUID(*req.FromAssignmentID) || !isValidUUID(*req.ToAssignmentID) || !isValidUUID(*req.ReceiverID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid UUID")
		return
	}
	initAt, err := parseTime(*req.InitiatedAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid initiatedAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "initiate_handoff", "handoff", true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("initiate_handoff", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	smp := s.state.Samples[*req.SampleID]
	fromA := s.state.Assignments[*req.FromAssignmentID]
	toA := s.state.Assignments[*req.ToAssignmentID]
	receiver := s.state.Users[*req.ReceiverID]

	if smp == nil || fromA == nil || toA == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample or assignment not found")
		return
	}
	if receiver == nil || !receiver.Active {
		writeError(w, http.StatusBadRequest, "invalid_receiver", "Receiver not found or inactive")
		return
	}
	if fromA.WorkerID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "initiate_handoff", "handoff", smp.SampleID, false, initAt, map[string]interface{}{"reason": "sender_assignment_mismatch"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "sender_assignment_mismatch", "Sender does not own fromAssignmentId")
		return
	}
	if smp.CurrentHolderID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "initiate_handoff", "handoff", smp.SampleID, false, initAt, map[string]interface{}{"reason": "not_current_holder"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusConflict, "not_current_holder", "Only the current sample holder may initiate a handoff")
		return
	}
	if smp.PendingHandoffID != "" {
		if ph := s.state.Handoffs[smp.PendingHandoffID]; ph != nil && ph.Status == "pending" {
			writeError(w, http.StatusConflict, "pending_handoff_exists", "Sample already has a pending handoff")
			return
		}
	}
	if toA.WorkerID != receiver.UserID {
		if toA.OfferedToWorkerID == receiver.UserID && toA.Status == "offered" {
			writeError(w, http.StatusConflict, "invalid_assignment_state", "Receiver has not accepted the target assignment yet")
			return
		}
		writeError(w, http.StatusConflict, "receiver_assignment_mismatch", "Receiver is not assigned to toAssignmentId")
		return
	}
	if !receiver.Available {
		writeError(w, http.StatusConflict, "receiver_unavailable", "Receiver is currently unavailable")
		return
	}
	if toA.Status != "accepted" && toA.Status != "at_pickup" && toA.Status != "in_progress" {
		writeError(w, http.StatusConflict, "invalid_assignment_state", "Target assignment is not in an accepted/ready state")
		return
	}

	// Verify fromA is ready to hand off
	if fromA.Kind == "collection" && !smp.Sealed {
		writeError(w, http.StatusConflict, "prior_leg_incomplete", "Collection must be completed and sealed before handoff")
		return
	}
	if fromA.Kind == "transport" && fromA.Status != "arrived" && fromA.Status != "delivered" && fromA.Status != "completed" {
		writeError(w, http.StatusConflict, "transport_leg_incomplete", "Transport leg must arrive or deliver before handoff")
		return
	}

	// Check adjacency & location matching between fromA and toA
	handoffLoc := fromA.ToLocationID
	if fromA.Kind == "node" && fromA.NodeID != "" {
		handoffLoc = fromA.NodeID
	}
	receiverLoc := toA.FromLocationID
	if toA.Kind == "node" && toA.NodeID != "" {
		receiverLoc = toA.NodeID
	} else if toA.Kind == "laboratory" && toA.LaboratoryID != "" {
		receiverLoc = toA.LaboratoryID
	}
	if handoffLoc != "" && receiverLoc != "" && handoffLoc != receiverLoc {
		writeError(w, http.StatusConflict, "invalid_handoff_route", "Assignments do not meet at the same handoff location")
		return
	}

	// Check sequence adjacency among active assignments for this sample
	if fromA.JourneyID == toA.JourneyID {
		if j := s.state.Journeys[fromA.JourneyID]; j != nil {
			// Verify there is no uncompleted transport leg between fromA and toA
			fromIdx, toIdx := -1, -1
			for idx, aid := range j.AssignmentIDs {
				if aid == fromA.AssignmentID {
					fromIdx = idx
				}
				if aid == toA.AssignmentID {
					toIdx = idx
				}
			}
			if fromIdx != -1 && toIdx != -1 {
				if toIdx <= fromIdx {
					writeError(w, http.StatusConflict, "nonadjacent_handoff", "Target assignment is not after source assignment")
					return
				}
				for k := fromIdx + 1; k < toIdx; k++ {
					midA := s.state.Assignments[j.AssignmentIDs[k]]
					if midA != nil && midA.Kind == "transport" {
						writeError(w, http.StatusConflict, "nonadjacent_handoff", "Cannot skip intermediate transport leg in handoff")
						return
					}
				}
			}
		}
	}

	if smp.SealedAt != "" {
		if stTime, err := parseTime(smp.SealedAt); err == nil && initAt.Before(stTime) {
			writeError(w, http.StatusConflict, "invalid_handoff_time", "Handoff cannot be initiated before sample was sealed")
			return
		}
	}

	h := &HandoffModel{
		HandoffID:        newUUID(),
		SampleID:         smp.SampleID,
		JourneyID:        fromA.JourneyID,
		FromAssignmentID: fromA.AssignmentID,
		ToAssignmentID:   toA.AssignmentID,
		SenderID:         actor.UserID,
		ReceiverID:       receiver.UserID,
		InitiatedAt:      formatTime(initAt),
		SenderConfirmed:  false,
		ReceiverConfirmed: false,
		Status:           "pending",
		CurrentHolderID:  smp.CurrentHolderID,
	}
	s.state.Handoffs[h.HandoffID] = h
	smp.PendingHandoffID = h.HandoffID

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "initiate_handoff", "handoff", h.HandoffID, true, initAt, map[string]interface{}{
		"handoffId":        h.HandoffID,
		"sampleId":         smp.SampleID,
		"fromAssignmentId": fromA.AssignmentID,
		"toAssignmentId":   toA.AssignmentID,
		"senderId":         actor.UserID,
		"receiverId":       receiver.UserID,
		"currentHolderId":  smp.CurrentHolderID,
	})
	smp.Timeline = append(smp.Timeline, ev)
	fromA.History = append(fromA.History, ev)
	toA.History = append(toA.History, ev)

	respData := map[string]interface{}{
		"handoffId":       h.HandoffID,
		"senderId":        h.SenderID,
		"receiverId":      h.ReceiverID,
		"currentHolderId": smp.CurrentHolderID,
		"status":          "pending",
	}
	s.saveIdempotencyLocked("initiate_handoff", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("handoff.initiated", "handoff", h.HandoffID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		HandoffID        *string `json:"handoffId"`
		ConfirmationSide *string `json:"confirmationSide"`
		ConfirmedAt      *string `json:"confirmedAt"`
		IdempotencyKey   *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.HandoffID == nil || req.ConfirmationSide == nil || req.ConfirmedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.HandoffID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid handoffId")
		return
	}
	side := strings.TrimSpace(*req.ConfirmationSide)
	if side != "sender" && side != "receiver" {
		writeError(w, http.StatusBadRequest, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
		return
	}
	confAt, err := parseTime(*req.ConfirmedAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid confirmedAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "confirm_handoff", "handoff", true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("confirm_handoff", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	h := s.state.Handoffs[*req.HandoffID]
	if h == nil {
		writeError(w, http.StatusNotFound, "not_found", "Handoff not found")
		return
	}
	if h.Status == "cancelled" {
		writeError(w, http.StatusConflict, "handoff_inactive", "Handoff is cancelled")
		return
	}

	if initT, err := parseTime(h.InitiatedAt); err == nil && confAt.Before(initT) {
		writeError(w, http.StatusConflict, "invalid_confirmation_time", "Confirmation time precedes handoff initiation time")
		return
	}

	if side == "sender" && actor.UserID != h.SenderID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "confirm_handoff", "handoff", h.HandoffID, false, confAt, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Only the sender may confirm the sender side")
		return
	}
	if side == "receiver" && actor.UserID != h.ReceiverID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "confirm_handoff", "handoff", h.HandoffID, false, confAt, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Only the receiver may confirm the receiver side")
		return
	}

	smp := s.state.Samples[h.SampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample not found")
		return
	}

	// If already confirmed on both sides, idempotent no-duplicate transfer
	if h.Status == "confirmed" {
		respData := map[string]interface{}{
			"handoffId":         h.HandoffID,
			"status":            h.Status,
			"senderConfirmed":   h.SenderConfirmed,
			"receiverConfirmed": h.ReceiverConfirmed,
			"currentHolderId":   h.CurrentHolderID,
		}
		s.saveIdempotencyLocked("confirm_handoff", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		_ = s.persistLocked(r.Context())
		writeData(w, http.StatusCreated, respData)
		return
	}

	if smp.CurrentHolderID != h.SenderID {
		writeError(w, http.StatusConflict, "custody_conflict", "Sender is no longer the current holder of the sample")
		return
	}

	if side == "sender" {
		h.SenderConfirmed = true
		h.SenderConfirmedAt = formatTime(confAt)
	} else {
		h.ReceiverConfirmed = true
		h.ReceiverConfirmedAt = formatTime(confAt)
	}

	if h.SenderConfirmed && h.ReceiverConfirmed {
		h.Status = "confirmed"
		smp.CurrentHolderID = h.ReceiverID
		h.CurrentHolderID = h.ReceiverID
		smp.PendingHandoffID = ""
		smp.LocationRecordedAt = formatTime(confAt)

		fromA := s.state.Assignments[h.FromAssignmentID]
		toA := s.state.Assignments[h.ToAssignmentID]
		if fromA != nil {
			if fromA.Status != "completed" && fromA.Status != "delivered" {
				if fromA.Kind == "transport" {
					fromA.Status = "delivered"
				} else {
					fromA.Status = "completed"
				}
				fromA.CompletedAt = formatTime(confAt)
			}
			alreadyIn := false
			for _, cid := range smp.CompletedLegIDs {
				if cid == fromA.AssignmentID {
					alreadyIn = true
					break
				}
			}
			if !alreadyIn {
				smp.CompletedLegIDs = append(smp.CompletedLegIDs, fromA.AssignmentID)
			}
			if fromA.CapacityReserved {
				fromA.CapacityReserved = false
				if senderUser := s.state.Users[h.SenderID]; senderUser != nil && senderUser.ReservedUnits > 0 {
					senderUser.ReservedUnits--
				}
			}
		}
		if toA != nil {
			if toA.Kind == "transport" && toA.Status == "accepted" {
				toA.Status = "picked_up"
				smp.Status = "in_transit"
			} else if toA.Kind == "node" {
				toA.Status = "in_progress"
				smp.Status = "at_node"
				if toA.NodeID != "" {
					smp.CurrentLocationID = toA.NodeID
					if loc := s.state.Locations[toA.NodeID]; loc != nil {
						c := loc.Coordinate
						smp.LatestLocation = &c
					}
				}
			} else if toA.Kind == "laboratory" {
				toA.Status = "in_progress"
				if toA.LaboratoryID != "" {
					smp.CurrentLocationID = toA.LaboratoryID
					if loc := s.state.Locations[toA.LaboratoryID]; loc != nil {
						c := loc.Coordinate
						smp.LatestLocation = &c
					}
				}
			}
			toA.LastProgressAt = formatTime(confAt)
		}

		// Mark corresponding stop completed on journey
		if j := s.state.Journeys[h.JourneyID]; j != nil {
			for idx := range j.OrderedStops {
				if j.OrderedStops[idx].LocationID == smp.CurrentLocationID && j.OrderedStops[idx].CompletedAt == "" {
					j.OrderedStops[idx].CompletedAt = formatTime(confAt)
					break
				}
			}
		}
	} else {
		h.CurrentHolderID = smp.CurrentHolderID
	}

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "confirm_handoff", "handoff", h.HandoffID, true, confAt, map[string]interface{}{
		"handoffId":         h.HandoffID,
		"sampleId":          smp.SampleID,
		"side":              side,
		"status":            h.Status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
		"currentHolderId":   smp.CurrentHolderID,
	})
	smp.Timeline = append(smp.Timeline, ev)
	if fromA := s.state.Assignments[h.FromAssignmentID]; fromA != nil {
		fromA.History = append(fromA.History, ev)
	}
	if toA := s.state.Assignments[h.ToAssignmentID]; toA != nil {
		toA.History = append(toA.History, ev)
	}

	respData := map[string]interface{}{
		"handoffId":         h.HandoffID,
		"status":            h.Status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
		"currentHolderId":   smp.CurrentHolderID,
	}
	s.saveIdempotencyLocked("confirm_handoff", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("handoff.confirmed", "handoff", h.HandoffID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		SampleID             *string  `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		LocationID           string   `json:"locationId"`
		ContainerType        *string  `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           *string  `json:"recordedAt"`
		IdempotencyKey       *string  `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.SampleID == nil || req.AssignmentID == nil || req.ContainerType == nil || req.ObservedTemperatureC == nil || req.RecordedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.SampleID) || !isValidUUID(*req.AssignmentID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid UUID")
		return
	}
	if req.LocationID != "" && !isValidUUID(req.LocationID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid locationId")
		return
	}
	recAt, err := parseTime(*req.RecordedAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid recordedAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "record_handling_checkpoint", "sample", true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("record_handling_checkpoint", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	smp := s.state.Samples[*req.SampleID]
	a := s.state.Assignments[*req.AssignmentID]
	if smp == nil || a == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample or assignment not found")
		return
	}
	if smp.Status == "received" || smp.Status == "cancelled" || smp.Status == "expired" {
		writeError(w, http.StatusConflict, "terminal_sample", "Sample is already in a terminal state")
		return
	}
	j := s.state.Journeys[a.JourneyID]
	if j != nil && (j.Status == "cancelled" || j.Status == "replaced" || j.Status == "expired") {
		writeError(w, http.StatusConflict, "journey_inactive", "Journey is inactive")
		return
	}
	if a.Status == "cancelled" {
		writeError(w, http.StatusConflict, "assignment_inactive", "Assignment is inactive")
		return
	}
	if smp.CurrentHolderID != actor.UserID || a.WorkerID != actor.UserID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "record_handling_checkpoint", "sample", smp.SampleID, false, recAt, map[string]interface{}{"reason": "forbidden"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "Only the current sample holder assigned to the active leg may record a checkpoint")
		return
	}
	if smp.SealedAt != "" {
		if stT, err := parseTime(smp.SealedAt); err == nil && recAt.Before(stT) {
			writeError(w, http.StatusConflict, "invalid_checkpoint_time", "Checkpoint time precedes sample sealing time")
			return
		}
	}

	obsCont := strings.TrimSpace(*req.ContainerType)
	obsTemp := *req.ObservedTemperatureC
	compliant := obsCont == smp.ContainerType && !math.IsNaN(obsTemp) && obsTemp >= smp.TemperatureMinC && obsTemp <= smp.TemperatureMaxC

	if !compliant {
		smp.Status = "exception"
		smp.Exception = map[string]interface{}{
			"reason":               "handling_excursion",
			"code":                 "handling_excursion",
			"observedContainer":    obsCont,
			"expectedContainer":    smp.ContainerType,
			"observedTemperatureC": obsTemp,
			"temperatureMinC":      smp.TemperatureMinC,
			"temperatureMaxC":      smp.TemperatureMaxC,
			"recordedAt":           formatTime(recAt),
		}
	}

	cp := &CheckpointModel{
		CheckpointID:         newUUID(),
		SampleID:             smp.SampleID,
		AssignmentID:         a.AssignmentID,
		LocationID:           req.LocationID,
		ContainerType:        obsCont,
		ObservedTemperatureC: obsTemp,
		RecordedAt:           formatTime(recAt),
		Compliant:            compliant,
		RecordedBy:           actor.UserID,
	}
	s.state.Checkpoints[cp.CheckpointID] = cp

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "record_handling_checkpoint", "sample", smp.SampleID, true, recAt, map[string]interface{}{
		"checkpointId":         cp.CheckpointID,
		"sampleId":             smp.SampleID,
		"assignmentId":         a.AssignmentID,
		"containerType":        obsCont,
		"observedTemperatureC": obsTemp,
		"compliant":            compliant,
		"sampleStatus":         smp.Status,
	})
	smp.Timeline = append(smp.Timeline, ev)
	a.History = append(a.History, ev)

	respData := map[string]interface{}{
		"checkpointId": cp.CheckpointID,
		"sampleId":     smp.SampleID,
		"compliant":    compliant,
		"sampleStatus": smp.Status,
	}
	s.saveIdempotencyLocked("record_handling_checkpoint", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("sample.checkpoint", "sample", smp.SampleID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		SampleID       *string `json:"sampleId"`
		LaboratoryID   *string `json:"laboratoryId"`
		ReceivedAt     *string `json:"receivedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.SampleID == nil || req.LaboratoryID == nil || req.ReceivedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if !isValidUUID(*req.SampleID) || !isValidUUID(*req.LaboratoryID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid UUID")
		return
	}
	recAt, err := parseTime(*req.ReceivedAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid receivedAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "confirm_laboratory_receipt", "sample", true, "laboratory_team")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("confirm_laboratory_receipt", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	smp := s.state.Samples[*req.SampleID]
	lab := s.state.Locations[*req.LaboratoryID]
	if smp == nil || lab == nil {
		writeError(w, http.StatusNotFound, "not_found", "Sample or laboratory not found")
		return
	}
	if actor.AssignedLocationID != "" && actor.AssignedLocationID != lab.LocationID {
		s.recordAuditLocked(actor.UserID, sess.ActiveRole, "confirm_laboratory_receipt", "sample", smp.SampleID, false, recAt, map[string]interface{}{"reason": "wrong_laboratory_operator"})
		_ = s.persistLocked(r.Context())
		writeError(w, http.StatusForbidden, "wrong_laboratory_operator", "Operator is not assigned to this laboratory")
		return
	}
	if !lab.Active || !lab.Functions.Laboratory || !lab.AcceptedSampleTypes[smp.SampleTypeID] {
		writeError(w, http.StatusConflict, "laboratory_unavailable", "Laboratory is inactive or does not accept this sample type")
		return
	}
	if smp.PendingHandoffID != "" {
		if ph := s.state.Handoffs[smp.PendingHandoffID]; ph != nil && ph.Status == "pending" {
			writeError(w, http.StatusConflict, "pending_handoff_exists", "Handoff to laboratory operator is still pending confirmation")
			return
		}
	}
	if smp.CurrentHolderID != actor.UserID {
		writeError(w, http.StatusConflict, "custody_conflict", "Laboratory operator must hold confirmed custody of the sample before confirming receipt")
		return
	}
	if !smp.Sealed || smp.Status == "exception" || smp.Status == "cancelled" || smp.Status == "expired" {
		writeError(w, http.StatusConflict, "receipt_not_ready", "Sample is not ready for normal receipt")
		return
	}
	if deadT, err := parseTime(smp.DeliveryDeadline); err == nil && recAt.After(deadT) {
		writeError(w, http.StatusConflict, "delivery_deadline_exceeded", "Sample received after delivery deadline")
		return
	}
	if smp.SealedAt != "" {
		if stT, err := parseTime(smp.SealedAt); err == nil && recAt.Before(stT) {
			writeError(w, http.StatusConflict, "invalid_receipt_time", "Receipt time precedes sample sealing time")
			return
		}
	}

	smp.Status = "received"
	smp.ReceivedLaboratoryID = lab.LocationID
	smp.ReceivedAt = formatTime(recAt)
	smp.CurrentLocationID = lab.LocationID
	c := lab.Coordinate
	smp.LatestLocation = &c
	smp.LocationRecordedAt = formatTime(recAt)

	if j := s.state.Journeys[smp.ActiveJourneyID]; j != nil {
		for _, aid := range j.LaboratoryAssignmentIDs {
			if la := s.state.Assignments[aid]; la != nil {
				la.Status = "completed"
				la.CompletedAt = formatTime(recAt)
				smp.CompletedLegIDs = append(smp.CompletedLegIDs, la.AssignmentID)
				if la.CapacityReserved {
					la.CapacityReserved = false
					if actor.ReservedUnits > 0 {
						actor.ReservedUnits--
					}
				}
			}
		}
		if len(j.OrderedStops) > 0 {
			j.OrderedStops[len(j.OrderedStops)-1].CompletedAt = formatTime(recAt)
		}
		// Check if all samples in journey are received
		allReceived := true
		for _, sid := range j.SampleIDs {
			if other := s.state.Samples[sid]; other != nil && other.Status != "received" {
				allReceived = false
				break
			}
		}
		if allReceived {
			j.Status = "completed"
			s.releaseJourneyCapacityLocked(j)
			s.recomputeServiceabilitySnapshotLocked()
		}
	}

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "confirm_laboratory_receipt", "sample", smp.SampleID, true, recAt, map[string]interface{}{
		"sampleId":     smp.SampleID,
		"laboratoryId": lab.LocationID,
		"status":       "received",
		"receivedAt":   smp.ReceivedAt,
	})
	smp.Timeline = append(smp.Timeline, ev)

	respData := map[string]interface{}{
		"sampleId":     smp.SampleID,
		"laboratoryId": lab.LocationID,
		"status":       "received",
		"receivedAt":   smp.ReceivedAt,
	}
	s.saveIdempotencyLocked("confirm_laboratory_receipt", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("sample.received", "sample", smp.SampleID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
