package main

import (
	"bytes"
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

//go:embed schema.sql
var schemaSQL string

type Store struct {
	mu      sync.RWMutex
	snapshotMu sync.RWMutex
	db      *pgxpool.Pool
	state   *AppStateData
	wsSubs  map[chan RealtimeEvent]struct{}
	wsMu    sync.Mutex
}

func NewStore(ctx context.Context, dbURL string) (*Store, error) {
	pool, err := pgxpool.New(ctx, dbURL)
	if err != nil {
		return nil, err
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, err
	}
	s := &Store{
		db:     pool,
		wsSubs: make(map[chan RealtimeEvent]struct{}),
	}
	if err := s.initDB(ctx); err != nil {
		pool.Close()
		return nil, err
	}
	return s, nil
}

func (s *Store) newDefaultState() *AppStateData {
	now := formatTime(time.Now().UTC())
	snap := &ServiceabilitySnapshot{
		Version:                    1,
		Status:                     "complete",
		ComputedAt:                 now,
		NetworkRevision:            0,
		Regions:                    []ServiceabilityRegion{},
		ActiveCollectionPointCount: 0,
		ReachableSampleTypes:       map[string]bool{},
	}
	st := &AppStateData{
		Users:                   make(map[string]*User),
		Sessions:                make(map[string]*Session),
		Locations:               make(map[string]*LocationModel),
		Connections:             make(map[string]*ConnectionModel),
		SampleTypes:             make(map[string]*SampleTypeModel),
		Samples:                 make(map[string]*SampleModel),
		Journeys:                make(map[string]*JourneyModel),
		Assignments:             make(map[string]*AssignmentModel),
		Handoffs:                make(map[string]*HandoffModel),
		Checkpoints:             make(map[string]*CheckpointModel),
		AuditLogs:               []AuditEntry{},
		RealtimeEvents:          []RealtimeEvent{},
		IdempotencyKeys:         make(map[string]*IdempotencyRecord),
		ServiceabilitySnapshots: []*ServiceabilitySnapshot{snap},
		CurrentSnapshot:         snap,
		NetworkRevision:         0,
		NextEventID:             1,
		NextRealtimeID:          1,
		NextAssignOrder:         1,
	}
	seedDefaultSampleTypes(st)
	return st
}

func seedDefaultSampleTypes(st *AppStateData) {
	amberID := deterministicUUID("default-sample-type-Amber")
	indigoID := deterministicUUID("default-sample-type-Indigo")
	frostID := deterministicUUID("default-sample-type-Frost")
	pulseID := deterministicUUID("default-sample-type-Pulse")

	if _, ok := st.SampleTypes[amberID]; !ok {
		st.SampleTypes[amberID] = &SampleTypeModel{
			SampleTypeID:               amberID,
			Name:                       "Amber",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Amber",
			ContainerType:              "standard_tube",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			IncompatibleSampleTypes:    []string{indigoID},
			RequiresCooledRoute:        false,
			BatchingAllowed:            true,
		}
	}
	if _, ok := st.SampleTypes[indigoID]; !ok {
		st.SampleTypes[indigoID] = &SampleTypeModel{
			SampleTypeID:               indigoID,
			Name:                       "Indigo",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Indigo",
			ContainerType:              "isolated_tube",
			TemperatureMinC:            15,
			TemperatureMaxC:            25,
			IncompatibleSampleTypes:    []string{amberID},
			RequiresCooledRoute:        false,
			BatchingAllowed:            true,
		}
	}
	if _, ok := st.SampleTypes[frostID]; !ok {
		st.SampleTypes[frostID] = &SampleTypeModel{
			SampleTypeID:               frostID,
			Name:                       "Frost",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Frost",
			ContainerType:              "cryo_vial",
			TemperatureMinC:            -20,
			TemperatureMaxC:            4,
			IncompatibleSampleTypes:    []string{},
			RequiresCooledRoute:        true,
			BatchingAllowed:            true,
		}
	}
	if _, ok := st.SampleTypes[pulseID]; !ok {
		st.SampleTypes[pulseID] = &SampleTypeModel{
			SampleTypeID:               pulseID,
			Name:                       "Pulse",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Pulse",
			ContainerType:              "stat_tube",
			TemperatureMinC:            2,
			TemperatureMaxC:            25,
			IncompatibleSampleTypes:    []string{},
			RequiresCooledRoute:        false,
			BatchingAllowed:            false,
		}
	}
}

func (s *Store) initDB(ctx context.Context) error {
	if _, err := s.db.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}

	var raw []byte
	err := s.db.QueryRow(ctx, `SELECT state_json FROM app_state WHERE id = 1`).Scan(&raw)
	if err == nil && len(raw) > 0 {
		var st AppStateData
		if uerr := json.Unmarshal(raw, &st); uerr == nil {
			s.ensureMaps(&st)
			s.state = &st
		}
	}
	if s.state == nil {
		s.state = s.newDefaultState()
	}

	adminUser := strings.TrimSpace(os.Getenv("ADMIN_USERNAME"))
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if len(s.state.Users) == 0 && adminUser != "" && adminPass != "" {
		uid := deterministicUUID("initial-admin-" + adminUser)
		s.state.Users[uid] = &User{
			UserID:           uid,
			Username:         adminUser,
			PasswordHash:     hashString(adminPass),
			FullName:         "System Administrator",
			Roles:            []string{"administrator"},
			Qualifications:   []string{},
			Certifications:   []Certification{},
			Active:           true,
			Available:        true,
			CapacityUnits:    10,
			AssignmentLocSeq: make(map[string]int),
			CreatedAt:        formatTime(time.Now().UTC()),
		}
	}

	return s.persistLocked(ctx)
}

func (s *Store) ensureMaps(st *AppStateData) {
	if st.Users == nil {
		st.Users = make(map[string]*User)
	}
	for _, u := range st.Users {
		if u.Roles == nil {
			u.Roles = []string{}
		}
		if u.Qualifications == nil {
			u.Qualifications = []string{}
		}
		if u.Certifications == nil {
			u.Certifications = []Certification{}
		}
		if u.AssignmentLocSeq == nil {
			u.AssignmentLocSeq = make(map[string]int)
		}
	}
	if st.Sessions == nil {
		st.Sessions = make(map[string]*Session)
	}
	if st.Locations == nil {
		st.Locations = make(map[string]*LocationModel)
	}
	for _, loc := range st.Locations {
		if loc.AcceptedSampleTypes == nil {
			loc.AcceptedSampleTypes = make(map[string]bool)
		}
	}
	if st.Connections == nil {
		st.Connections = make(map[string]*ConnectionModel)
	}
	if st.SampleTypes == nil {
		st.SampleTypes = make(map[string]*SampleTypeModel)
	}
	if st.Samples == nil {
		st.Samples = make(map[string]*SampleModel)
	}
	if st.Journeys == nil {
		st.Journeys = make(map[string]*JourneyModel)
	}
	if st.Assignments == nil {
		st.Assignments = make(map[string]*AssignmentModel)
	}
	for _, a := range st.Assignments {
		if a.DeclinedByWorkerIDs == nil {
			a.DeclinedByWorkerIDs = make(map[string]bool)
		}
	}
	if st.Handoffs == nil {
		st.Handoffs = make(map[string]*HandoffModel)
	}
	if st.Checkpoints == nil {
		st.Checkpoints = make(map[string]*CheckpointModel)
	}
	if st.AuditLogs == nil {
		st.AuditLogs = []AuditEntry{}
	}
	if st.RealtimeEvents == nil {
		st.RealtimeEvents = []RealtimeEvent{}
	}
	if st.IdempotencyKeys == nil {
		st.IdempotencyKeys = make(map[string]*IdempotencyRecord)
	}
	if st.NextEventID < 1 {
		st.NextEventID = len(st.AuditLogs) + 1
	}
	if st.NextRealtimeID < 1 {
		st.NextRealtimeID = int64(len(st.RealtimeEvents)) + 1
	}
	if st.NextAssignOrder < 1 {
		st.NextAssignOrder = 1
	}
	seedDefaultSampleTypes(st)
}

func (s *Store) persistLocked(ctx context.Context) error {
	raw, err := json.Marshal(s.state)
	if err != nil {
		return err
	}
	_, err = s.db.Exec(ctx, `
		INSERT INTO app_state (id, state_json, updated_at)
		VALUES (1, $1, NOW())
		ON CONFLICT (id) DO UPDATE SET state_json = EXCLUDED.state_json, updated_at = NOW()
	`, raw)
	if err != nil {
		return err
	}
	if s.state.CurrentSnapshot != nil {
		regRaw, _ := json.Marshal(s.state.CurrentSnapshot.Regions)
		_, _ = s.db.Exec(ctx, `
			INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
			VALUES ($1, $2, NOW(), $3, $4, $5)
			ON CONFLICT (version) DO UPDATE SET
				status = EXCLUDED.status,
				network_revision = EXCLUDED.network_revision,
				regions = EXCLUDED.regions,
				active_collection_point_count = EXCLUDED.active_collection_point_count
		`, s.state.CurrentSnapshot.Version, s.state.CurrentSnapshot.Status, s.state.CurrentSnapshot.NetworkRevision, regRaw, s.state.CurrentSnapshot.ActiveCollectionPointCount)
	}
	return nil
}

func (s *Store) SubscribeWS() chan RealtimeEvent {
	ch := make(chan RealtimeEvent, 128)
	s.wsMu.Lock()
	s.wsSubs[ch] = struct{}{}
	s.wsMu.Unlock()
	return ch
}

func (s *Store) UnsubscribeWS(ch chan RealtimeEvent) {
	s.wsMu.Lock()
	delete(s.wsSubs, ch)
	close(ch)
	s.wsMu.Unlock()
}

func (s *Store) emitRealtimeLocked(evType, entityType, entityID string, payload map[string]interface{}) RealtimeEvent {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	ev := RealtimeEvent{
		ID:         s.state.NextRealtimeID,
		Type:       evType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  formatTime(time.Now().UTC()),
	}
	s.state.NextRealtimeID++
	s.state.RealtimeEvents = append(s.state.RealtimeEvents, ev)

	s.wsMu.Lock()
	for ch := range s.wsSubs {
		select {
		case ch <- ev:
		default:
		}
	}
	s.wsMu.Unlock()
	return ev
}

func (s *Store) recordAuditLocked(actorID, role, action, entityType, entityID string, success bool, occurredAt time.Time, details map[string]interface{}) TimelineEntry {
	if occurredAt.IsZero() {
		occurredAt = time.Now().UTC()
	}
	if details == nil {
		details = map[string]interface{}{}
	}
	if actorID == "" {
		actorID = "anonymous"
	}
	if role == "" {
		role = "unselected"
	}
	if entityType == "" {
		entityType = "system"
	}
	if entityID == "" {
		entityID = "system"
	}
	evID := s.state.NextEventID
	s.state.NextEventID++
	ts := formatTime(occurredAt)
	auditID := newUUID()

	ae := AuditEntry{
		EventID:     evID,
		AuditID:     auditID,
		AuditID2:    auditID,
		ActorID:     actorID,
		ActorID2:    actorID,
		Role:        role,
		ActorRole:   role,
		Action:      action,
		EntityType:  entityType,
		EntityType2: entityType,
		EntityID:    entityID,
		EntityID2:   entityID,
		Success:     success,
		OccurredAt:  ts,
		OccurredAt2: ts,
		Details:     details,
	}
	s.state.AuditLogs = append(s.state.AuditLogs, ae)

	return TimelineEntry{
		EventID:    evID,
		Action:     action,
		ActorID:    actorID,
		Role:       role,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: ts,
		Details:    details,
	}
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, map[string]string{
		"error": msg,
		"code":  code,
	})
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{
		"data": data,
	})
}

func decodeStrictJSON(r *http.Request, dst interface{}) ([]byte, error) {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return nil, err
	}
	trimmed := bytes.TrimSpace(body)
	if len(trimmed) == 0 {
		return nil, fmt.Errorf("empty body")
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return body, err
	}
	if dec.More() {
		return body, fmt.Errorf("unexpected trailing data")
	}
	return trimmed, nil
}

func canonicalizeJSONForHash(raw []byte) string {
	var m map[string]interface{}
	if err := json.Unmarshal(raw, &m); err != nil {
		return hashString(string(raw))
	}
	b, err := json.Marshal(m)
	if err != nil {
		return hashString(string(raw))
	}
	return hashString(string(b))
}

func (s *Store) checkIdempotencyLocked(opID, actorID, idemKey string, rawBody []byte) (int, []byte, bool, bool) {
	scopeKey := opID + ":" + actorID + ":" + idemKey
	rec, exists := s.state.IdempotencyKeys[scopeKey]
	if !exists {
		return 0, nil, false, false
	}
	reqHash := canonicalizeJSONForHash(rawBody)
	if rec.RequestHash != reqHash {
		return 0, nil, true, true
	}
	return rec.StatusCode, rec.ResponseRaw, true, false
}

func (s *Store) saveIdempotencyLocked(opID, actorID, idemKey string, rawBody []byte, status int, data interface{}) []byte {
	respObj := map[string]interface{}{"data": data}
	respBytes, _ := json.Marshal(respObj)
	if idemKey != "" {
		scopeKey := opID + ":" + actorID + ":" + idemKey
		s.state.IdempotencyKeys[scopeKey] = &IdempotencyRecord{
			ScopeKey:    scopeKey,
			RequestHash: canonicalizeJSONForHash(rawBody),
			StatusCode:  status,
			ResponseRaw: respBytes,
			CreatedAt:   formatTime(time.Now().UTC()),
		}
	}
	return respBytes
}

