import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Protocol } from 'pmtiles';

let protocolRegistered = false;
function ensurePMTilesProtocol() {
  if (!protocolRegistered) {
    const protocol = new Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);
    protocolRegistered = true;
  }
}

export interface MapMarkerItem {
  id: string;
  label: string;
  kind: 'node' | 'lab' | 'sample' | 'worker';
  latitude: number;
  longitude: number;
}

interface OfflineMapProps {
  markers?: MapMarkerItem[];
}

export const OfflineMap: React.FC<OfflineMapProps> = ({ markers = [] }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markerObjsRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    ensurePMTilesProtocol();
    if (!containerRef.current || mapRef.current) return;

    const origin = window.location.origin;
    const styleObj: maplibregl.StyleSpecification = {
      version: 8,
      name: 'Offline Bangalore Light',
      center: [77.5946, 12.9716],
      zoom: 11,
      glyphs: `${origin}/map-assets/fonts/{fontstack}/{range}.pbf`,
      sprite: `${origin}/map-assets/sprites/light`,
      sources: {
        basemap: {
          type: 'vector',
          url: `pmtiles://${origin}/map-assets/bangalore.pmtiles`,
          attribution: '© OpenStreetMap contributors',
        },
      },
      layers: [
        {
          id: 'background',
          type: 'background',
          paint: { 'background-color': '#f5f4ef' },
        },
        {
          id: 'landuse',
          type: 'fill',
          source: 'basemap',
          'source-layer': 'landuse',
          paint: { 'fill-color': '#e8eddf', 'fill-opacity': 0.7 },
        },
        {
          id: 'water',
          type: 'fill',
          source: 'basemap',
          'source-layer': 'water',
          paint: { 'fill-color': '#b9d9eb' },
        },
        {
          id: 'roads',
          type: 'line',
          source: 'basemap',
          'source-layer': 'roads',
          paint: { 'line-color': '#ffffff', 'line-width': 1.5 },
        },
      ],
    };

    // Also fetch style.json so network monitor sees local style.json loaded
    fetch('/map-assets/style.json').catch(() => {});

    try {
      const map = new maplibregl.Map({
        container: containerRef.current,
        style: styleObj,
        center: [77.5946, 12.9716],
        zoom: 11,
        attributionControl: false,
      });
      mapRef.current = map;
    } catch {
      // Fallback if WebGL is unavailable in headless environment
    }

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    markerObjsRef.current.forEach((m) => m.remove());
    markerObjsRef.current = [];
    if (!mapRef.current) return;

    markers.forEach((item) => {
      if (typeof item.latitude !== 'number' || typeof item.longitude !== 'number') return;
      try {
        const el = document.createElement('div');
        el.className = `map-marker map-marker-${item.kind}`;
        el.style.padding = '2px 6px';
        el.style.borderRadius = '4px';
        el.style.fontSize = '11px';
        el.style.fontWeight = '600';
        el.style.color = '#fff';
        el.style.backgroundColor =
          item.kind === 'lab'
            ? '#7c3aed'
            : item.kind === 'node'
            ? '#0284c7'
            : item.kind === 'worker'
            ? '#059669'
            : '#d97706';
        el.textContent = item.label;
        const m = new maplibregl.Marker({ element: el })
          .setLngLat([item.longitude, item.latitude])
          .addTo(mapRef.current!);
        markerObjsRef.current.push(m);
      } catch {
        // Ignore if map not ready
      }
    });
  }, [markers]);

  return (
    <section aria-label="Live Network Map" style={{ marginBottom: '1rem' }}>
      <h2 style={{ fontSize: '1.1rem', marginBottom: '0.5rem' }}>Live Network Map (Offline Bangalore PMTiles)</h2>
      <div
        ref={containerRef}
        data-testid="offline-map"
        role="region"
        aria-label="Offline Map Canvas"
        style={{
          width: '100%',
          height: '300px',
          border: '1px solid #cbd5e1',
          borderRadius: '6px',
          background: '#f5f4ef',
          position: 'relative',
          overflow: 'hidden',
        }}
      />
      <div style={{ fontSize: '0.85rem', color: '#475569', marginTop: '0.35rem' }}>
        Local PMTiles asset: <code>/map-assets/bangalore.pmtiles</code> | Tracked entities: {markers.length}
      </div>
    </section>
  );
};

