                  onChange={(e) => setTempMax(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-window-start" style={{ display: 'block', fontWeight: 600 }}>
                  Earliest Collection Time
                </label>
                <input
                  id="req-window-start"
                  type="text"
                  value={windowStart}
                  onChange={(e) => setWindowStart(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-window-end" style={{ display: 'block', fontWeight: 600 }}>
                  Latest Collection Time
                </label>
                <input
                  id="req-window-end"
                  type="text"
                  value={windowEnd}
                  onChange={(e) => setWindowEnd(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-deadline" style={{ display: 'block', fontWeight: 600 }}>
                  Delivery Deadline
                </label>
                <input
                  id="req-deadline"
                  type="text"
                  value={deadlineAt}
                  onChange={(e) => setDeadlineAt(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
