package main

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func setupTestServer(t *testing.T) (*Store, http.Handler) {
	t.Helper()
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	store, err := NewStore(dbURL)
	if err != nil {
		t.Fatalf("NewStore failed: %v", err)
	}
	t.Cleanup(func() { store.Close() })

	ctx := context.Background()
	if err := store.ResetDatabase(ctx); err != nil {
		t.Fatalf("ResetDatabase failed: %v", err)
	}
	if err := store.InitSchemaAndState(ctx, "admin", "admin-pass-123"); err != nil {
		t.Fatalf("InitSchemaAndState failed: %v", err)
	}

	mux := http.NewServeMux()
	store.RegisterRoutes(mux, "/workspace/frontend/dist", "/opt/arena/map-assets")
	return store, mux
}

func doReq(t *testing.T, handler http.Handler, method, path, token string, body interface{}) (int, map[string]interface{}) {
	t.Helper()
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			t.Fatalf("encode body: %v", err)
		}
	}
	req := httptest.NewRequest(method, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	var resp map[string]interface{}
	_ = json.Unmarshal(rec.Body.Bytes(), &resp)
	return rec.Code, resp
}

func TestEndToEndLifecycleAndRules(t *testing.T) {
	_, srv := setupTestServer(t)

	// 1. Check /ready
	code, readyResp := doReq(t, srv, http.MethodGet, "/ready", "", nil)
	if code != http.StatusOK || readyResp["status"] != "ready" {
		t.Fatalf("expected /ready 200, got %d %v", code, readyResp)
	}

	// 2. Authenticate initial admin
	code, authResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
		"username": "admin",
		"password": "admin-pass-123",
	})
	if code != http.StatusOK {
		t.Fatalf("admin login failed: %d %v", code, authResp)
	}
	adminToken := authResp["data"].(map[string]interface{})["token"].(string)

	// 3. Configure network: Collection Node -> Hub -> Lab
	code, nodeResp := doReq(t, srv, http.MethodPost, "/api/configure-network-location", adminToken, map[string]interface{}{
		"name":            "Central Collection Point",
		"coordinate":      map[string]interface{}{"latitude": 12.9716, "longitude": 77.5946},
		"active":          true,
		"coverageKm":      5.0,
		"handlingMinutes": 5,
		"functions": map[string]interface{}{
			"collectionPoint": true,
			"transferPoint":   true,
			"hub":             false,
			"laboratory":      false,
		},
		"capacity": map[string]interface{}{
			"capacityUnits":       10,
			"cooledCapacityUnits": 5,
		},
		"idempotencyKey": "cfg-node-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("create collection node failed: %d %v", code, nodeResp)
	}
	nodeID := nodeResp["data"].(map[string]interface{})["locationId"].(string)

	amberID := deterministicUUID("default-sample-type-Amber")
	indigoID := deterministicUUID("default-sample-type-Indigo")
	frostID := deterministicUUID("default-sample-type-Frost")
	pulseID := deterministicUUID("default-sample-type-Pulse")

	code, labResp := doReq(t, srv, http.MethodPost, "/api/configure-network-location", adminToken, map[string]interface{}{
		"name":            "Bangalore Diagnostics Lab",
		"coordinate":      map[string]interface{}{"latitude": 12.9800, "longitude": 77.6100},
		"active":          true,
		"coverageKm":      5.0,
		"handlingMinutes": 10,
		"functions": map[string]interface{}{
			"collectionPoint": false,
			"transferPoint":   false,
			"hub":             false,
			"laboratory":      true,
		},
		"capacity": map[string]interface{}{
			"capacityUnits":       10,
			"cooledCapacityUnits": 5,
		},
		"acceptedSampleTypeIds": []string{amberID, indigoID, frostID, pulseID},
		"idempotencyKey":        "cfg-lab-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("create lab failed: %d %v", code, labResp)
	}
	labID := labResp["data"].(map[string]interface{})["locationId"].(string)

	// Connect Node -> Lab
	code, connResp := doReq(t, srv, http.MethodPost, "/api/configure-network-connection", adminToken, map[string]interface{}{
		"fromLocationId":      nodeID,
		"toLocationId":        labID,
		"active":              true,
		"travelMinutes":       20,
		"cooled":              true,
		"capacityUnits":       10,
		"cooledCapacityUnits": 5,
		"idempotencyKey":      "cfg-conn-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("create connection failed: %d %v", code, connResp)
	}

	// 4. Create users for roles
	createWorker := func(username string, roles, quals []string, locID string) (string, string) {
		body := map[string]interface{}{
			"username":       username,
			"password":       "pass-1234",
			"roles":          roles,
			"qualifications": quals,
			"active":         true,
			"available":      true,
			"capacityUnits":  5,
			"idempotencyKey": "user-" + username,
		}
		if locID != "" {
			body["assignedLocationId"] = locID
		}
		c, r := doReq(t, srv, http.MethodPost, "/api/manage-user-roles", adminToken, body)
		if c != http.StatusCreated {
			t.Fatalf("create user %s failed: %d %v", username, c, r)
		}
		uid := r["data"].(map[string]interface{})["userId"].(string)
		c, ar := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
			"username": username,
			"password": "pass-1234",
		})
		if c != http.StatusOK {
			t.Fatalf("login %s failed: %d %v", username, c, ar)
		}
		tok := ar["data"].(map[string]interface{})["token"].(string)
		return uid, tok
	}

	_, reqToken := createWorker("req1", []string{"requester"}, nil, "")
	collectorID, colToken := createWorker("col1", []string{"collection_professional"}, []string{"Amber", "Indigo", "Frost", "Pulse"}, "")
	courierID, courToken := createWorker("cour1", []string{"delivery_partner"}, nil, "")
	_, labWorkerToken := createWorker("labop1", []string{"laboratory_team"}, nil, labID)

	// 5. Dry-run serviceability check (must not create samples or reserve capacity)
	now := time.Now().UTC()
	reqPayload := map[string]interface{}{
		"origin": map[string]interface{}{
			"type":       "home",
			"coordinate": map[string]interface{}{"latitude": 12.9720, "longitude": 77.5950},
		},
		"sampleTypeId": amberID,
		"handling": map[string]interface{}{
			"containerType":   "standard_tube",
			"temperatureMinC": 2.0,
			"temperatureMaxC": 25.0,
		},
		"collectionWindow": map[string]interface{}{
			"earliestAt": now.Add(5 * time.Minute).Format(time.RFC3339),
			"latestAt":   now.Add(60 * time.Minute).Format(time.RFC3339),
		},
		"deliveryDeadlineAt": now.Add(180 * time.Minute).Format(time.RFC3339),
	}
	code, svcResp := doReq(t, srv, http.MethodPost, "/api/check-serviceability", reqToken, reqPayload)
	if code != http.StatusOK {
		t.Fatalf("check-serviceability failed: %d %v", code, svcResp)
	}
	svcData := svcResp["data"].(map[string]interface{})
	if svcData["serviceable"] != true {
		t.Fatalf("expected serviceable=true, got %v", svcData)
	}

	// Verify dry run created nothing in monitor-operations
	code, monResp := doReq(t, srv, http.MethodPost, "/api/monitor-operations", adminToken, map[string]interface{}{})
	if code != http.StatusOK {
		t.Fatalf("monitor-operations failed: %d %v", code, monResp)
	}
	if len(monResp["data"].(map[string]interface{})["samples"].([]interface{})) != 0 {
		t.Fatalf("dry run should not create any sample")
	}

	// 6. Create collection request
	reqPayload["idempotencyKey"] = "create-req-1"
	code, createResp := doReq(t, srv, http.MethodPost, "/api/create-collection-request", reqToken, reqPayload)
	if code != http.StatusCreated {
		t.Fatalf("create-collection-request failed: %d %v", code, createResp)
	}
	smpData := createResp["data"].(map[string]interface{})
	sampleID := smpData["sampleId"].(string)
	colAssignID := smpData["collectionAssignmentId"].(string)

	// 7. Collector accepts assignment, completes collection & seals sample
	code, _ = doReq(t, srv, http.MethodPost, "/api/accept-assignment", colToken, map[string]interface{}{
		"assignmentId":   colAssignID,
		"idempotencyKey": "acc-col-1",
	})
	if code != http.StatusOK {
		t.Fatalf("collector accept failed: %d", code)
	}

	code, sealResp := doReq(t, srv, http.MethodPost, "/api/complete-collection", colToken, map[string]interface{}{
		"sampleId":           sampleID,
		"assignmentId":       colAssignID,
		"collectedAt":        now.Add(10 * time.Minute).Format(time.RFC3339),
		"sealed":             true,
		"containerType":      "standard_tube",
		"observedTemperatureC": 10.0,
		"idempotencyKey":     "seal-1",
	})
	if code != http.StatusOK {
		t.Fatalf("complete-collection failed: %d %v", code, sealResp)
	}
	if sealResp["data"].(map[string]interface{})["currentHolderId"] != collectorID {
		t.Fatalf("expected collector to hold custody after sealing")
	}

	// 8. Courier accepts transport assignment
	code, workResp := doReq(t, srv, http.MethodPost, "/api/list-role-work", courToken, map[string]interface{}{
		"role": "delivery_partner",
	})
	if code != http.StatusOK {
		t.Fatalf("courier list-role-work failed: %d", code)
	}
	curWork := workResp["data"].(map[string]interface{})["currentWork"].([]interface{})
	if len(curWork) == 0 {
		t.Fatalf("expected courier to have offered transport assignment")
	}
	transAssignID := curWork[0].(map[string]interface{})["assignmentId"].(string)

	code, _ = doReq(t, srv, http.MethodPost, "/api/accept-assignment", courToken, map[string]interface{}{
		"assignmentId":   transAssignID,
		"idempotencyKey": "acc-cour-1",
	})
	if code != http.StatusOK {
		t.Fatalf("courier accept failed: %d", code)
	}

	// 9. Propose and dual-confirm handoff from collector to courier
	code, hoResp := doReq(t, srv, http.MethodPost, "/api/propose-handoff", colToken, map[string]interface{}{
		"sampleId":       sampleID,
		"fromHolderId":   collectorID,
		"toHolderId":     courierID,
		"assignmentId":   transAssignID,
		"idempotencyKey": "prop-ho-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("propose-handoff failed: %d %v", code, hoResp)
	}
	handoffID := hoResp["data"].(map[string]interface{})["handoffId"].(string)

	// Sender confirms first -> holder remains collector
	code, c1Resp := doReq(t, srv, http.MethodPost, "/api/confirm-handoff", colToken, map[string]interface{}{
		"handoffId":      handoffID,
		"party":          "sender",
		"confirmedAt":    now.Add(15 * time.Minute).Format(time.RFC3339),
		"idempotencyKey": "conf-ho-sender",
	})
	if code != http.StatusOK || c1Resp["data"].(map[string]interface{})["currentHolderId"] != collectorID {
		t.Fatalf("sender confirm should keep collector as holder until receiver confirms: %d %v", code, c1Resp)
	}

	// Receiver confirms second -> holder transfers to courier
	code, c2Resp := doReq(t, srv, http.MethodPost, "/api/confirm-handoff", courToken, map[string]interface{}{
		"handoffId":      handoffID,
		"party":          "receiver",
		"confirmedAt":    now.Add(16 * time.Minute).Format(time.RFC3339),
		"idempotencyKey": "conf-ho-receiver",
	})
	if code != http.StatusOK || c2Resp["data"].(map[string]interface{})["currentHolderId"] != courierID {
		t.Fatalf("receiver confirm should transfer custody to courier: %d %v", code, c2Resp)
	}

	// 10. Lab intake confirmation
	code, intakeResp := doReq(t, srv, http.MethodPost, "/api/confirm-lab-intake", labWorkerToken, map[string]interface{}{
		"sampleId":           sampleID,
		"laboratoryId":       labID,
		"receivedAt":         now.Add(30 * time.Minute).Format(time.RFC3339),
		"containerType":      "standard_tube",
		"observedTemperatureC": 12.0,
		"idempotencyKey":     "intake-1",
	})
	if code != http.StatusOK || intakeResp["data"].(map[string]interface{})["status"] != "received" {
		t.Fatalf("confirm-lab-intake failed: %d %v", code, intakeResp)
	}
}

