package main

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func setupTestServer(t *testing.T) (*Store, http.Handler) {
	t.Helper()
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	_ = os.Setenv("ADMIN_USERNAME", "admin")
	_ = os.Setenv("ADMIN_PASSWORD", "admin-pass-123")

	ctx := context.Background()
	s0, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore initial: %v", err)
	}
	_, _ = s0.db.Exec(ctx, `TRUNCATE TABLE app_state, users, sessions, locations, connections, sample_types, samples, journeys, assignments, handoffs, checkpoints, audit_logs, realtime_events, idempotency_keys, serviceability_snapshots CASCADE`)
	s0.db.Close()

	store, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore failed: %v", err)
	}
	t.Cleanup(func() { store.db.Close() })

	mux := http.NewServeMux()
	store.RegisterRoutes(mux)
	return store, mux
}

func doReq(t *testing.T, handler http.Handler, method, path, token string, body interface{}) (int, map[string]interface{}) {
	t.Helper()
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			t.Fatalf("encode body: %v", err)
		}
	}
	req := httptest.NewRequest(method, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	var resp map[string]interface{}
	_ = json.Unmarshal(rec.Body.Bytes(), &resp)
	return rec.Code, resp
}

func TestEndToEndLifecycleAndRules(t *testing.T) {
	_, srv := setupTestServer(t)

	// 1. Check /ready
	code, readyResp := doReq(t, srv, http.MethodGet, "/ready", "", nil)
	if code != http.StatusOK || readyResp["status"] != "ready" {
