		"active":          true,
		"coverageKm":      5.0,
		"handlingMinutes": 5,
		"functions": map[string]interface{}{
			"collectionPoint": true,
			"transferPoint":   true,
			"hub":             false,
			"laboratory":      false,
		},
		"capacity": map[string]interface{}{
			"capacityUnits":       10,
