   488	func (s *Store) isSampleLocationStaleLocked(smp *SampleModel) bool {
   489		if smp == nil || smp.LocationRecordedAt == "" {
   490			return false
   491		}
   492		if smp.Status == "received" || smp.Status == "cancelled" || smp.Status == "expired" {
   493			return false
   494		}
   495		t, err := parseTime(smp.LocationRecordedAt)
   496		if err != nil {
   497			return false
   498		}
   499		now := time.Now().UTC()
   500		if now.Sub(t) > 15*time.Minute {
   501			return true
   502		}
   503		// Also check if sample has a worker who recorded a stale/older location or if last progress is > 15m after locationRecordedAt
   504		if smp.ActiveJourneyID != "" {
   505			if j := s.state.Journeys[smp.ActiveJourneyID]; j != nil {
   506				for _, aid := range j.AssignmentIDs {
   507					if a := s.state.Assignments[aid]; a != nil && a.LastProgressAt != "" {
   508						if pt, err := parseTime(a.LastProgressAt); err == nil {
   509							if pt.Sub(t) > 15*time.Minute {
   510								return true
   511							}
   512						}
   513					}
   514				}
   515			}
   516		}
   517		return false
   518	}
