      {/* Sample Tracking, Freshness, Custodian, Route Progress, Exception Flag & Ordered Status History */}
      <section aria-label="Sample Tracking and Status History" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
        <h2 style={{ marginTop: 0 }}>Sample Tracking, Custody &amp; Status Timeline</h2>
        <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.75rem', alignItems: 'center' }}>
