package main

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func setupTestServer(t *testing.T) (*Store, http.Handler) {
	t.Helper()
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	mongoURI := os.Getenv("MONGODB_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017/arena"
	}
	redisURL := os.Getenv("REDIS_URL")
	if redisURL == "" {
		redisURL = "redis://127.0.0.1:6379/0"
	}
	_ = os.Setenv("ADMIN_USERNAME", "admin")
	_ = os.Setenv("ADMIN_PASSWORD", "admin-pass-123")

	ctx := context.Background()
	s0, err := NewStore(ctx, dbURL, mongoURI, redisURL)
	if err != nil {
		t.Fatalf("NewStore initial: %v", err)
	}
	if err := s0.ResetAll(ctx); err != nil {
		t.Fatalf("ResetAll failed: %v", err)
	}
	s0.Close()

	store, err := NewStore(ctx, dbURL, mongoURI, redisURL)
	if err != nil {
		t.Fatalf("NewStore failed: %v", err)
	}
	t.Cleanup(func() { store.Close() })

	mux := http.NewServeMux()
	store.RegisterRoutes(mux)
	return store, mux
}

func doReq(t *testing.T, handler http.Handler, method, path, token string, body interface{}) (int, map[string]interface{}) {
	t.Helper()
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			t.Fatalf("encode body: %v", err)
		}
	}
	req := httptest.NewRequest(method, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	var resp map[string]interface{}
	_ = json.Unmarshal(rec.Body.Bytes(), &resp)
	return rec.Code, resp
}

func TestEndToEndLifecycleAndRules(t *testing.T) {
	_, srv := setupTestServer(t)

	// 1. Check /ready
	code, readyResp := doReq(t, srv, http.MethodGet, "/ready", "", nil)
	if code != http.StatusOK || readyResp["status"] != "ready" {
		t.Fatalf("expected /ready 200, got %d %v", code, readyResp)
	}

	// 2. Authenticate initial admin
	code, authResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
		"username": "admin",
		"password": "admin-pass-123",
	})
	if code != http.StatusOK {
		t.Fatalf("admin login failed: %d %v", code, authResp)
	}
	adminData := authResp["data"].(map[string]interface{})
	adminToken := adminData["sessionToken"].(string)

	// 3. Configure network: Collection Node -> Lab
	code, nodeResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name":       "Central Collection Point",
		"coordinate": map[string]interface{}{"latitude": 12.9716, "longitude": 77.5946},
		"functions": map[string]interface{}{
			"collectionPoint": true,
			"transferPoint":   true,
			"hub":             false,
			"laboratory":      false,
		},
		"capacityUnits":       10,
		"cooledCapacityUnits": 5,
		"coverageKm":          5.0,
		"handlingMinutes":     5,
	})
	if code != http.StatusCreated {
		t.Fatalf("create collection node failed: %d %v", code, nodeResp)
	}
	nodeID := nodeResp["data"].(map[string]interface{})["id"].(string)

	amberID := defaultAmberID
	indigoID := defaultIndigoID
	frostID := defaultFrostID
	pulseID := defaultPulseID

	code, labResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name":       "Bangalore Diagnostics Lab",
		"coordinate": map[string]interface{}{"latitude": 12.9800, "longitude": 77.6100},
		"functions": map[string]interface{}{
			"collectionPoint": false,
			"transferPoint":   false,
			"hub":             false,
			"laboratory":      true,
		},
		"capacityUnits":         10,
		"cooledCapacityUnits":   5,
		"coverageKm":            5.0,
		"handlingMinutes":       10,
		"acceptedSampleTypeIds": []string{amberID, indigoID, frostID, pulseID},
	})
	if code != http.StatusCreated {
		t.Fatalf("create lab failed: %d %v", code, labResp)
	}
	labID := labResp["data"].(map[string]interface{})["id"].(string)

	// Connect Node -> Lab
	code, connResp := doReq(t, srv, http.MethodPost, "/api/create-connection", adminToken, map[string]interface{}{
		"fromLocationId":      nodeID,
		"toLocationId":        labID,
		"active":              true,
		"travelMinutes":       20,
		"cooled":              true,
		"capacityUnits":       10,
		"cooledCapacityUnits": 5,
	})
	if code != http.StatusCreated {
		t.Fatalf("create connection failed: %d %v", code, connResp)
	}

	// 4. Create users for roles
	createWorker := func(username string, roles, quals []string, locID string) (string, string) {
		body := map[string]interface{}{
			"username":             username,
			"password":             "pass-1234",
			"fullName":             username + " FullName",
			"roles":                roles,
			"certifiedSampleTypes": quals,
			"available":            true,
			"capacityUnits":        5,
		}
		if locID != "" {
			body["assignedLocationId"] = locID
		}
		c, r := doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, body)
		if c != http.StatusCreated {
			t.Fatalf("create user %s failed: %d %v", username, c, r)
		}
		uid := r["data"].(map[string]interface{})["userId"].(string)
		c, ar := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
			"username": username,
			"password": "pass-1234",
		})
		if c != http.StatusOK {
			t.Fatalf("login %s failed: %d %v", username, c, ar)
		}
		tok := ar["data"].(map[string]interface{})["sessionToken"].(string)
		return uid, tok
	}

	_, reqToken := createWorker("req1", []string{"requester"}, nil, "")
	collectorID, colToken := createWorker("col1", []string{"collection_professional"}, []string{"Amber", "Indigo", "Frost", "Pulse"}, "")
	courierID, courToken := createWorker("cour1", []string{"delivery_partner"}, nil, "")
	_, nodeWorkerToken := createWorker("nodeop1", []string{"node_handler"}, nil, nodeID)
	_, labWorkerToken := createWorker("labop1", []string{"laboratory_team"}, nil, labID)

	// 5. Dry-run serviceability check (must not create samples or reserve capacity)
	now := time.Now().UTC()
	code, svcResp := doReq(t, srv, http.MethodPost, "/api/check-serviceability", reqToken, map[string]interface{}{
		"origin":               map[string]interface{}{"latitude": 12.9720, "longitude": 77.5950},
		"originType":           "home",
		"sampleTypeId":         amberID,
		"requestedAt":          now.Format(time.RFC3339),
		"earliestCollectionAt": now.Add(5 * time.Minute).Format(time.RFC3339),
		"latestCollectionAt":   now.Add(60 * time.Minute).Format(time.RFC3339),
		"deliveryDeadline":     now.Add(180 * time.Minute).Format(time.RFC3339),
	})
	if code != http.StatusOK {
		t.Fatalf("serviceability check failed: %d %v", code, svcResp)
	}
	svcData := svcResp["data"].(map[string]interface{})
	if svcData["serviceable"] != true {
		t.Fatalf("expected serviceable=true, got %v", svcData)
	}

	// Verify dry run created nothing in operations state
	code, opsBefore := doReq(t, srv, http.MethodPost, "/api/read-operations-state", adminToken, map[string]interface{}{})
	if code != http.StatusOK {
		t.Fatalf("read operations failed: %d %v", code, opsBefore)
	}
	samplesBefore := opsBefore["data"].(map[string]interface{})["samples"].([]interface{})
	if len(samplesBefore) != 0 {
		t.Fatalf("dry run should not create samples, found %d", len(samplesBefore))
