	}

	// 8. Check sample state & lifecycle
	code, stResp := doReq(t, srv, http.MethodGet, "/api/read-sample-state/"+sampleID, reqToken, nil)
	if code != http.StatusOK {
		t.Fatalf("read sample state failed: %d %v", code, stResp)
