		"sampleId": sampleID,
	})
	if code != http.StatusOK {
		t.Fatalf("read sample lifecycle failed: %d %v", code, lcResp)
	}

	// 9. Accept node & courier & lab assignments
	_, _ = nodeWorkerToken, labWorkerToken
	code, courWork := doReq(t, srv, http.MethodPost, "/api/list-role-work", courToken, map[string]interface{}{
		"role": "delivery_partner",
	})
	if code != http.StatusOK {
		t.Fatalf("courier list work failed: %d %v", code, courWork)
	}
	_ = courierID

	// 10. Search audit trail
	code, auditResp := doReq(t, srv, http.MethodPost, "/api/search-audit-trail", adminToken, map[string]interface{}{
		"limit": 50,
	})
	if code != http.StatusOK {
		t.Fatalf("search audit trail failed: %d %v", code, auditResp)
	}
	entries := auditResp["data"].(map[string]interface{})["entries"].([]interface{})
	if len(entries) == 0 {
		t.Fatalf("expected audit entries to be recorded")
	}
}

