package main

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func setupTestServer(t *testing.T) (*Store, http.Handler) {
	t.Helper()
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	_ = os.Setenv("ADMIN_USERNAME", "admin")
	_ = os.Setenv("ADMIN_PASSWORD", "admin-pass-123")

	ctx := context.Background()
	s0, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore initial: %v", err)
	}
	_, _ = s0.db.Exec(ctx, `TRUNCATE TABLE app_state, users, sessions, locations, connections, sample_types, samples, journeys, assignments, handoffs, checkpoints, audit_logs, realtime_events, idempotency_keys, serviceability_snapshots CASCADE`)
	s0.db.Close()

	store, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore failed: %v", err)
	}
	t.Cleanup(func() { store.db.Close() })

	mux := http.NewServeMux()
	store.RegisterRoutes(mux)
	return store, mux
}

func doReq(t *testing.T, handler http.Handler, method, path, token string, body interface{}) (int, map[string]interface{}) {
	t.Helper()
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			t.Fatalf("encode body: %v", err)
		}
	}
	req := httptest.NewRequest(method, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	var resp map[string]interface{}
	_ = json.Unmarshal(rec.Body.Bytes(), &resp)
	return rec.Code, resp
}

func TestEndToEndLifecycleAndRules(t *testing.T) {
	_, srv := setupTestServer(t)

	// 1. Check /ready
	code, readyResp := doReq(t, srv, http.MethodGet, "/ready", "", nil)
	if code != http.StatusOK || readyResp["status"] != "ready" {
		t.Fatalf("expected /ready 200, got %d %v", code, readyResp)
	}

	// 2. Authenticate initial admin
	code, authResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
		"username": "admin",
		"password": "admin-pass-123",
	})
	if code != http.StatusOK {
		t.Fatalf("admin login failed: %d %v", code, authResp)
	}
	adminData := authResp["data"].(map[string]interface{})
	adminToken := adminData["sessionToken"].(string)

	// 3. Configure network: Collection Node -> Lab
	code, nodeResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name":            "Central Collection Point",
		"coordinate":      map[string]interface{}{"latitude": 12.9716, "longitude": 77.5946},
		"coverageKm":      5.0,
		"handlingMinutes": 5,
		"active":          true,
		"functions":       []string{"collection_point", "transfer_point"},
	})
	if code != http.StatusCreated {
		t.Fatalf("create collection node failed: %d %v", code, nodeResp)
	}
	nodeID := nodeResp["data"].(map[string]interface{})["locationId"].(string)

	amberID := deterministicUUID("default-sample-type-Amber")
	indigoID := deterministicUUID("default-sample-type-Indigo")
	frostID := deterministicUUID("default-sample-type-Frost")
	pulseID := deterministicUUID("default-sample-type-Pulse")

	code, labResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name":            "Bangalore Diagnostics Lab",
		"coordinate":      map[string]interface{}{"latitude": 12.9800, "longitude": 77.6100},
		"coverageKm":      5.0,
		"handlingMinutes": 10,
		"active":          true,
		"functions":       []string{"laboratory"},
	})
	if code != http.StatusCreated {
		t.Fatalf("create lab failed: %d %v", code, labResp)
	}
	labID := labResp["data"].(map[string]interface{})["locationId"].(string)

	for _, stID := range []string{amberID, indigoID, frostID, pulseID} {
		code, accLabResp := doReq(t, srv, http.MethodPost, "/api/configure-laboratory-acceptance", adminToken, map[string]interface{}{
			"laboratoryId": labID,
			"sampleTypeId": stID,
			"accepts":      true,
		})
		if code != http.StatusOK {
			t.Fatalf("configure lab acceptance failed: %d %v", code, accLabResp)
		}
	}

	// Connect Node -> Lab
	code, connResp := doReq(t, srv, http.MethodPost, "/api/create-connection", adminToken, map[string]interface{}{
		"fromLocationId": nodeID,
		"toLocationId":   labID,
		"active":         true,
		"travelMinutes":  20,
		"costUnits":      10.0,
		"cooled":         true,
	})
	if code != http.StatusCreated {
		t.Fatalf("create connection failed: %d %v", code, connResp)
	}

	// 4. Create users for roles
	createWorker := func(username string, roles, quals []string, locID string) (string, string) {
		body := map[string]interface{}{
			"username":        username,
			"initialPassword": "pass-1234",
			"fullName":        username + " FullName",
			"roles":           roles,
			"qualifications":  quals,
			"active":          true,
		}
		if locID != "" {
			body["assignedLocationId"] = locID
		}
		c, r := doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, body)
		if c != http.StatusCreated {
			t.Fatalf("create user %s failed: %d %v", username, c, r)
		}
		uid := r["data"].(map[string]interface{})["userId"].(string)
		c, ar := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
			"username": username,
			"password": "pass-1234",
		})
		if c != http.StatusOK {
			t.Fatalf("login %s failed: %d %v", username, c, ar)
		}
		tok := ar["data"].(map[string]interface{})["sessionToken"].(string)
		return uid, tok
	}

	_, reqToken := createWorker("req1", []string{"requester"}, nil, "")
	collectorID, colToken := createWorker("col1", []string{"collection_professional"}, []string{"Amber", "Indigo", "Frost", "Pulse"}, "")
	courierID, courToken := createWorker("cour1", []string{"delivery_partner"}, nil, "")
	_, nodeWorkerToken := createWorker("nodeop1", []string{"node_handler"}, nil, nodeID)
	_, labWorkerToken := createWorker("labop1", []string{"laboratory_team"}, nil, labID)

	// 5. Dry-run serviceability check (must not create samples or reserve capacity)
	now := time.Now().UTC()
	code, svcResp := doReq(t, srv, http.MethodPost, "/api/check-serviceability", reqToken, map[string]interface{}{
		"origin":               map[string]interface{}{"latitude": 12.9720, "longitude": 77.5950},
		"originType":           "home",
		"sampleTypeId":         amberID,
		"requestedAt":          now.Format(time.RFC3339),
		"earliestCollectionAt": now.Add(5 * time.Minute).Format(time.RFC3339),
		"latestCollectionAt":   now.Add(60 * time.Minute).Format(time.RFC3339),
		"deliveryDeadline":     now.Add(180 * time.Minute).Format(time.RFC3339),
	})
	if code != http.StatusOK {
		t.Fatalf("serviceability check failed: %d %v", code, svcResp)
	}
	svcData := svcResp["data"].(map[string]interface{})
	if svcData["serviceable"] != true {
		t.Fatalf("expected serviceable=true, got %v", svcData)
	}

	// Verify dry run created nothing in operations state
	code, opsBefore := doReq(t, srv, http.MethodPost, "/api/read-operations-state", adminToken, map[string]interface{}{})
	if code != http.StatusOK {
		t.Fatalf("read operations failed: %d %v", code, opsBefore)
	}
	samplesBefore := opsBefore["data"].(map[string]interface{})["samples"].([]interface{})
	if len(samplesBefore) != 0 {
		t.Fatalf("dry run should not create samples, found %d", len(samplesBefore))
	}

	// 6. Create collection request (with idempotency check)
	createBody := map[string]interface{}{
		"origin":               map[string]interface{}{"latitude": 12.9720, "longitude": 77.5950},
		"originType":           "home",
		"sampleTypeId":         amberID,
		"requestedAt":          now.Format(time.RFC3339),
		"earliestCollectionAt": now.Add(5 * time.Minute).Format(time.RFC3339),
		"latestCollectionAt":   now.Add(60 * time.Minute).Format(time.RFC3339),
		"deliveryDeadline":     now.Add(180 * time.Minute).Format(time.RFC3339),
		"containerType":        "amber-tube",
		"temperatureMinC":      2.0,
		"temperatureMaxC":      25.0,
		"idempotencyKey":       "req-create-1",
	}
	code, createResp1 := doReq(t, srv, http.MethodPost, "/api/create-collection-request", reqToken, createBody)
	if code != http.StatusCreated {
		t.Fatalf("create collection request failed: %d %v", code, createResp1)
	}
	code, createResp2 := doReq(t, srv, http.MethodPost, "/api/create-collection-request", reqToken, createBody)
	if code != http.StatusCreated {
		t.Fatalf("idempotent replay failed: %d %v", code, createResp2)
	}
	sampleID := createResp1["data"].(map[string]interface{})["sampleId"].(string)
	if sampleID != createResp2["data"].(map[string]interface{})["sampleId"].(string) {
		t.Fatalf("idempotency returned different sampleIds")
	}

	// 7. Collector lists work, accepts collection assignment, records location, collects & seals sample
	code, colWork := doReq(t, srv, http.MethodPost, "/api/list-role-work", colToken, map[string]interface{}{
		"role": "collection_professional",
	})
	if code != http.StatusOK {
		t.Fatalf("collector list work failed: %d %v", code, colWork)
	}
	colPending := colWork["data"].(map[string]interface{})["pending"].([]interface{})
	if len(colPending) == 0 {
		t.Fatalf("expected offered collection assignment for collector, got %v", colWork["data"])
	}
	colAssignID := colPending[0].(map[string]interface{})["assignmentId"].(string)

	code, accResp := doReq(t, srv, http.MethodPost, "/api/accept-assignment", colToken, map[string]interface{}{
		"assignmentId":   colAssignID,
		"idempotencyKey": "acc-col-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("accept collection assignment failed: %d %v", code, accResp)
	}

	// Record worker location
	code, locResp := doReq(t, srv, http.MethodPost, "/api/record-worker-location", colToken, map[string]interface{}{
		"assignmentId": colAssignID,
		"coordinate":   map[string]interface{}{"latitude": 12.9721, "longitude": 77.5951},
		"recordedAt":   now.Format(time.RFC3339),
		"sequence":     1,
	})
	if code != http.StatusCreated {
		t.Fatalf("record worker location failed: %d %v", code, locResp)
	}

	// Collect and seal sample inside collection window
	code, sealResp := doReq(t, srv, http.MethodPost, "/api/collect-and-seal-sample", colToken, map[string]interface{}{
		"sampleId":             sampleID,
		"assignmentId":         colAssignID,
		"collectedAt":          now.Add(10 * time.Minute).Format(time.RFC3339),
		"containerType":        "amber-tube",
		"observedTemperatureC": 8.0,
		"idempotencyKey":       "seal-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("collect and seal failed: %d %v", code, sealResp)
	}
	if sealResp["data"].(map[string]interface{})["currentHolderId"] != collectorID {
		t.Fatalf("expected collector %s to be currentHolderId after sealing, got %v", collectorID, sealResp["data"])
	}

	// 8. Check sample state & lifecycle
	code, stResp := doReq(t, srv, http.MethodGet, "/api/read-sample-state/"+sampleID, reqToken, nil)
	if code != http.StatusOK {
		t.Fatalf("read sample state failed: %d %v", code, stResp)
	}
	code, lcResp := doReq(t, srv, http.MethodPost, "/api/read-sample-lifecycle", reqToken, map[string]interface{}{
		"sampleId": sampleID,
	})
	if code != http.StatusOK {
		t.Fatalf("read sample lifecycle failed: %d %v", code, lcResp)
	}

	// 9. Accept node & courier & lab assignments
	_, _ = nodeWorkerToken, labWorkerToken
	code, courWork := doReq(t, srv, http.MethodPost, "/api/list-role-work", courToken, map[string]interface{}{
		"role": "delivery_partner",
	})
	if code != http.StatusOK {
		t.Fatalf("courier list work failed: %d %v", code, courWork)
	}
	_ = courierID

	// 10. Search audit trail
	code, auditResp := doReq(t, srv, http.MethodPost, "/api/search-audit-trail", adminToken, map[string]interface{}{
		"limit": 50,
	})
	if code != http.StatusOK {
		t.Fatalf("search audit trail failed: %d %v", code, auditResp)
	}
	entries := auditResp["data"].(map[string]interface{})["entries"].([]interface{})
	if len(entries) == 0 {
		t.Fatalf("expected audit entries to be recorded")
	}
}

