script = """import { chromium } from "/usr/local/lib/node_modules/@playwright/test/node_modules/playwright/index.mjs";

const BASE = "http://127.0.0.1:8080";

async function api(path, token, body) {
  const res = await fetch(BASE + path, {
    method: body ? "POST" : "GET",
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: "Bearer " + token } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json();
  return { status: res.status, json };
}

(async () => {
  // Seed network and users via API using initial admin
  const authRes = await api("/api/authenticate-user", "", {
    username: "admin",
    password: "admin-pass-123",
  });
  if (authRes.status !== 200) throw new Error("Admin login failed: " + JSON.stringify(authRes));
  const adminToken = authRes.json.data.sessionToken;

  const nodeRes = await api("/api/create-location", adminToken, {
    name: "Indiranagar Collection Hub",
    coordinate: { latitude: 12.9716, longitude: 77.5946 },
    coverageKm: 5.0,
    handlingMinutes: 5,
    active: true,
