		NetworkRevision:            0,
		Regions:                    []ServiceabilityRegion{},
		ActiveCollectionPointCount: 0,
		ReachableSampleTypes:       map[string]bool{},
	}
	st := &AppStateData{
		Users:                   make(map[string]*User),
		Sessions:                make(map[string]*Session),
		Locations:               make(map[string]*LocationModel),
		Connections:             make(map[string]*ConnectionModel),
		SampleTypes:             make(map[string]*SampleTypeModel),
		Samples:                 make(map[string]*SampleModel),
		Journeys:                make(map[string]*JourneyModel),
		Assignments:             make(map[string]*AssignmentModel),
		Handoffs:                make(map[string]*HandoffModel),
		Checkpoints:             make(map[string]*CheckpointModel),
		AuditLogs:               []AuditEntry{},
		RealtimeEvents:          []RealtimeEvent{},
		IdempotencyKeys:         make(map[string]*IdempotencyRecord),
		ServiceabilitySnapshots: []*ServiceabilitySnapshot{snap},
		CurrentSnapshot:         snap,
		NetworkRevision:         0,
		NextEventID:             1,
		NextRealtimeID:          1,
		NextAssignOrder:         1,
	}
	seedDefaultSampleTypes(st)
	return st
}

func seedDefaultSampleTypes(st *AppStateData) {
