package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

func (s *Store) startBackgroundWorkers(ctx context.Context) {
	ticker := time.NewTicker(2 * time.Second)
	go func() {
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				s.checkOfferTimeouts(ctx)
			}
		}
	}()
}

func (s *Store) checkOfferTimeouts(ctx context.Context) {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()
	changed := false

	for _, a := range s.state.Assignments {
		if a.Status != "offered" || a.OfferExpiresAt == "" {
			continue
		}
		expT, err := parseTime(a.OfferExpiresAt)
		if err != nil || !now.After(expT) {
			continue
		}
		// Offer expired without response -> treat as declined and re-offer to next eligible worker
		timedOutWorker := a.OfferedToWorkerID
		if a.DeclinedByWorkerIDs == nil {
			a.DeclinedByWorkerIDs = make(map[string]bool)
		}
		if timedOutWorker != "" {
			a.DeclinedByWorkerIDs[timedOutWorker] = true
			if u := s.state.Users[timedOutWorker]; u != nil {
				u.DeclineCount++
				u.LastDeclinedAt = formatTime(now)
			}
		}
		a.WorkerID = ""
		a.OfferedToWorkerID = ""
		a.Status = "pending"

		ev := s.recordAuditLocked("system", "dispatcher", "offer_timeout_declined", "assignment", a.AssignmentID, true, now, map[string]interface{}{
			"assignmentId":   a.AssignmentID,
			"timedOutWorker": timedOutWorker,
		})
		a.History = append(a.History, ev)

		smp := s.state.Samples[a.SampleID]
		var st *SampleTypeModel
		if smp != nil {
			smp.Timeline = append(smp.Timeline, ev)
			st = s.state.SampleTypes[smp.SampleTypeID]
		}

		nextW, anyQual := s.selectFairEligibleWorkerLocked(a, st, now, true)
		if nextW != nil {
			s.offerAssignmentToWorkerLocked(a, nextW, now)
		} else if !anyQual && smp != nil {
			smp.Status = "exception"
			smp.Exception = map[string]interface{}{
				"reason":     "no_qualified_worker",
				"code":       "no_qualified_worker",
				"occurredAt": formatTime(now),
			}
		}
		changed = true
	}

	if changed {
		_ = s.persistLocked(ctx)
	}
}

func main() {
	resetOnly := flag.Bool("reset", false, "Initialize database schema and exit")
	flag.Parse()

	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	store, err := NewStore(ctx, dbURL)
	if err != nil {
		log.Fatalf("failed to initialize store: %v", err)
	}
	defer store.db.Close()

	if *resetOnly {
		fmt.Println("Database schema and initial structures materialized.")
		return
	}

	store.startBackgroundWorkers(ctx)

	mux := http.NewServeMux()
	store.RegisterRoutes(mux)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	addr := "127.0.0.1:" + port

	srv := &http.Server{
		Addr:    addr,
		Handler: mux,
	}

	go func() {
		<-ctx.Done()
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_ = srv.Shutdown(shutdownCtx)
	}()

	log.Printf("Server listening on http://%s", addr)
	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("server error: %v", err)
	}
}

func (s *Store) RegisterRoutes(mux *http.ServeMux) {
	// Readiness
	mux.HandleFunc("/ready", s.handleReadiness)

	// Auth & Users
	mux.HandleFunc("/api/authenticate-user", s.handleAuthenticateUser)
	mux.HandleFunc("/api/select-active-role", s.handleSelectActiveRole)
	mux.HandleFunc("/api/create-user", s.handleCreateUser)
	mux.HandleFunc("/api/update-user-access", s.handleUpdateUserAccess)
	mux.HandleFunc("/api/read-user/", s.handleReadUser)

	// Network Locations, Connections, Capacities, Sample Types
	mux.HandleFunc("/api/create-location", s.handleCreateLocation)
	mux.HandleFunc("/api/update-location", s.handleUpdateLocation)
	mux.HandleFunc("/api/set-location-status", s.handleSetLocationStatus)
	mux.HandleFunc("/api/set-location-function-status", s.handleSetLocationFunctionStatus)
	mux.HandleFunc("/api/create-connection", s.handleCreateConnection)
	mux.HandleFunc("/api/set-connection-status", s.handleSetConnectionStatus)
	mux.HandleFunc("/api/create-sample-type", s.handleCreateSampleType)
