	if _, err := s.db.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}
	_, err := s.db.Exec(ctx, `
		TRUNCATE TABLE
			app_state,
			users,
			sessions,
			locations,
			connections,
			sample_types,
			samples,
			journeys,
			assignments,
			handoffs,
			checkpoints,
			audit_logs,
			serviceability_snapshots,
			idempotency_keys
		RESTART IDENTITY CASCADE
	`)
	if err != nil {
		return fmt.Errorf("truncate tables: %w", err)
	}

	s.state = s.newDefaultState()
	adminUser := strings.TrimSpace(os.Getenv("ADMIN_USERNAME"))
