	err := s.db.QueryRow(ctx, `SELECT state_json FROM app_state WHERE id = 1`).Scan(&raw)
	if err == nil && len(raw) > 0 {
		var st AppStateData
		if uerr := json.Unmarshal(raw, &st); uerr == nil {
			s.ensureMaps(&st)
			s.state = &st
		}
	}
	if s.state == nil {
		s.state = s.newDefaultState()
	}

	adminUser := strings.TrimSpace(os.Getenv("ADMIN_USERNAME"))
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if len(s.state.Users) == 0 && adminUser != "" && adminPass != "" {
