		select {
		case ch <- ev:
		default:
		}
	}
	s.wsMu.Unlock()
	return ev
}

func (s *Store) recordAuditLocked(actorID, role, action, entityType, entityID string, success bool, occurredAt time.Time, details map[string]interface{}) TimelineEntry {
	if occurredAt.IsZero() {
		occurredAt = time.Now().UTC()
	}
	if details == nil {
		details = map[string]interface{}{}
	}
	if actorID == "" {
		actorID = "anonymous"
	}
	if role == "" {
		role = "unselected"
	}
	if entityType == "" {
		entityType = "system"
	}
	if entityID == "" {
		entityID = "system"
	}
	evID := s.state.NextEventID
	s.state.NextEventID++
	ts := formatTime(occurredAt)
	auditID := newUUID()

	ae := AuditEntry{
		EventID:     evID,
		AuditID:     auditID,
		AuditID2:    auditID,
		ActorID:     actorID,
		ActorID2:    actorID,
		Role:        role,
		ActorRole:   role,
		Action:      action,
		EntityType:  entityType,
		EntityType2: entityType,
		EntityID:    entityID,
		EntityID2:   entityID,
		Success:     success,
		OccurredAt:  ts,
		OccurredAt2: ts,
		Details:     details,
	}
	s.state.AuditLogs = append(s.state.AuditLogs, ae)

	return TimelineEntry{
		EventID:    evID,
		Action:     action,
		ActorID:    actorID,
		Role:       role,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: ts,
		Details:    details,
	}
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, map[string]string{
		"error": msg,
		"code":  code,
	})
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{
		"data": data,
	})
}

func decodeStrictJSON(r *http.Request, dst interface{}) ([]byte, error) {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return nil, err
	}
	trimmed := bytes.TrimSpace(body)
	if len(trimmed) == 0 {
		return nil, fmt.Errorf("empty body")
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return body, err
	}
	if dec.More() {
		return body, fmt.Errorf("unexpected trailing data")
	}
	return trimmed, nil
}

func canonicalizeJSONForHash(raw []byte) string {
	var m map[string]interface{}
	if err := json.Unmarshal(raw, &m); err != nil {
		return hashString(string(raw))
	}
	b, err := json.Marshal(m)
	if err != nil {
		return hashString(string(raw))
	}
	return hashString(string(b))
}

func (s *Store) checkIdempotencyLocked(opID, actorID, idemKey string, rawBody []byte) (int, []byte, bool, bool) {
	scopeKey := opID + ":" + actorID + ":" + idemKey
	rec, exists := s.state.IdempotencyKeys[scopeKey]
	if !exists {
		return 0, nil, false, false
	}
	reqHash := canonicalizeJSONForHash(rawBody)
	if rec.RequestHash != reqHash {
		return 0, nil, true, true
	}
	return rec.StatusCode, rec.ResponseRaw, true, false
}

func (s *Store) saveIdempotencyLocked(opID, actorID, idemKey string, rawBody []byte, status int, data interface{}) []byte {
	respObj := map[string]interface{}{"data": data}
	respBytes, _ := json.Marshal(respObj)
	if idemKey != "" {
		scopeKey := opID + ":" + actorID + ":" + idemKey
		s.state.IdempotencyKeys[scopeKey] = &IdempotencyRecord{
			ScopeKey:    scopeKey,
			RequestHash: canonicalizeJSONForHash(rawBody),
			StatusCode:  status,
			ResponseRaw: respBytes,
			CreatedAt:   formatTime(time.Now().UTC()),
		}
	}
	return respBytes
}

