		respData["replacementPlanId"] = replJ.JourneyID
		respData["replacementJourney"] = s.buildJourneyPlanDTO(replJ)
	}

	s.saveIdempotencyLocked("reroute_journey", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("journey.rerouted", "journey", j.JourneyID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		ResourceType   *string `json:"resourceType"`
		ResourceID     *string `json:"resourceId"`
		Reason         string  `json:"reason"`
		OccurredAt     *string `json:"occurredAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.ResourceType == nil || req.ResourceID == nil || req.OccurredAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	resType := strings.TrimSpace(*req.ResourceType)
	validResTypes := map[string]bool{
		"location":   true,
		"node":       true,
		"laboratory": true,
		"connection": true,
		"route":      true,
		"worker":     true,
		"capacity":   true,
	}
	if !validResTypes[resType] {
		writeError(w, http.StatusBadRequest, "invalid_resource_type", "Invalid resourceType")
		return
	}
	occAt, err := parseTime(*req.OccurredAt)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_time", "Invalid occurredAt timestamp")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	actor, sess, ok := s.authAndRoleLocked(w, r, "report_disruption", "disruption", true, "dispatcher", "administrator")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("report_disruption", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	resID := strings.TrimSpace(*req.ResourceID)

	// Mark the disrupted resource unavailable and find affected active journeys
	affectedJourneys := []*JourneyModel{}
	switch resType {
	case "location", "node", "laboratory":
		loc := s.state.Locations[resID]
		if loc == nil {
			writeError(w, http.StatusNotFound, "not_found", "Location not found")
			return
		}
		if resType == "laboratory" {
			loc.Functions.Laboratory = false
		} else {
			loc.Active = false
		}
		for _, j := range s.state.Journeys {
			if j.Status != "active" && j.Status != "in_progress" {
				continue
			}
			for _, nid := range j.NodePathIDs {
				if nid == resID {
					affectedJourneys = append(affectedJourneys, j)
					break
				}
			}
		}

	case "connection", "route":
		conn := s.state.Connections[resID]
		if conn == nil {
			writeError(w, http.StatusNotFound, "not_found", "Connection not found")
			return
		}
		conn.Active = false
		for _, j := range s.state.Journeys {
			if j.Status != "active" && j.Status != "in_progress" {
				continue
			}
			for _, cid := range j.ConnectionIDs {
				if cid == resID {
					affectedJourneys = append(affectedJourneys, j)
					break
				}
			}
		}

	case "worker":
		u := s.state.Users[resID]
		if u == nil {
			writeError(w, http.StatusNotFound, "not_found", "Worker not found")
			return
		}
		u.Available = false
		for _, j := range s.state.Journeys {
			if j.Status != "active" && j.Status != "in_progress" {
				continue
			}
			for _, aid := range j.AssignmentIDs {
				a := s.state.Assignments[aid]
				if a != nil && (a.WorkerID == resID || a.OfferedToWorkerID == resID) && a.Status != "completed" && a.Status != "delivered" {
					affectedJourneys = append(affectedJourneys, j)
					break
				}
			}
		}

	case "capacity":
		if loc := s.state.Locations[resID]; loc != nil {
			loc.Capacity.CapacityUnits = loc.Capacity.ReservedUnits
			loc.Capacity.AvailableUnits = 0
			loc.Capacity.CooledCapacityUnits = loc.Capacity.CooledReservedUnits
			loc.Capacity.CooledAvailableUnits = 0
		} else if conn := s.state.Connections[resID]; conn != nil {
			conn.Capacity.CapacityUnits = conn.Capacity.ReservedUnits
			conn.Capacity.AvailableUnits = 0
			conn.Capacity.CooledCapacityUnits = conn.Capacity.CooledReservedUnits
			conn.Capacity.CooledAvailableUnits = 0
		} else {
			writeError(w, http.StatusNotFound, "not_found", "Capacity resource not found")
			return
		}
		for _, j := range s.state.Journeys {
			if j.Status != "active" && j.Status != "in_progress" {
				continue
			}
			for _, nid := range j.NodePathIDs {
				if nid == resID {
					affectedJourneys = append(affectedJourneys, j)
					break
				}
			}
		}
	}

	s.recomputeServiceabilitySnapshotLocked()

	affectedSampleIDs := []string{}
	replacementPlanIDs := []string{}
	overallStatus := "not_required"

	for _, j := range affectedJourneys {
		for _, sid := range j.SampleIDs {
			affectedSampleIDs = append(affectedSampleIDs, sid)
		}
		status, replJ := s.replanSingleJourneyLocked(j, actor.UserID, sess.ActiveRole, req.Reason, occAt)
		if replJ != nil && status == "replaced" {
			replacementPlanIDs = append(replacementPlanIDs, replJ.JourneyID)
		}
		if status == "expired" {
			overallStatus = "expired"
		} else if status == "exception" && overallStatus != "expired" {
			overallStatus = "exception"
		} else if status == "replaced" && overallStatus == "not_required" {
			overallStatus = "replaced"
		}
	}

	disruptionID := newUUID()
	respData := map[string]interface{}{
		"disruptionId":       disruptionID,
		"affectedSampleIds":  affectedSampleIDs,
		"replacementPlanIds": replacementPlanIDs,
		"replanStatus":       overallStatus,
	}

	s.recordAuditLocked(actor.UserID, sess.ActiveRole, "report_disruption", "disruption", disruptionID, true, occAt, respData)
	s.saveIdempotencyLocked("report_disruption", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("disruption.reported", "disruption", disruptionID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		JourneyID           *string  `json:"journeyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.SampleIDs == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	if !isValidUUID(*req.JourneyID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid journeyId")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "split_journey", "journey", true, "dispatcher", "administrator")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("split_journey", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	j := s.state.Journeys[*req.JourneyID]
	if j == nil {
		writeError(w, http.StatusNotFound, "not_found", "Journey not found")
		return
	}
	if j.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "Plan version mismatch")
		return
	}
	if j.Status == "cancelled" || j.Status == "completed" || j.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "Journey is inactive")
		return
	}

	if len(req.SampleIDs) == 0 || len(req.SampleIDs) >= len(j.SampleIDs) {
		writeError(w, http.StatusConflict, "invalid_split", "split sampleIds must be a non-empty proper subset of journey samples")
		return
	}
	inJ := map[string]bool{}
	for _, sid := range j.SampleIDs {
		inJ[sid] = true
	}
	splitSet := map[string]bool{}
	for _, sid := range req.SampleIDs {
		if !inJ[sid] || splitSet[sid] {
			writeError(w, http.StatusConflict, "invalid_split", "Sample is not part of this journey")
			return
		}
		splitSet[sid] = true
	}

	// Check if transport work is currently in progress mid-leg
	for _, aid := range j.TransportAssignmentIDs {
		if a := s.state.Assignments[aid]; a != nil && (a.Status == "picked_up" || a.Status == "in_transit") {
			writeError(w, http.StatusConflict, "split_in_progress", "Cannot split journey while transport leg is actively in transit")
			return
		}
	}

	var remainSamples []string
	var splitSamples []string
	for _, sid := range j.SampleIDs {
		if splitSet[sid] {
			splitSamples = append(splitSamples, sid)
		} else {
			remainSamples = append(remainSamples, sid)
		}
	}

	// Release split sample units from original journey so splitJourney can reserve them cleanly
	splitSmp := s.state.Samples[splitSamples[0]]
	splitST := s.state.SampleTypes[splitSmp.SampleTypeID]
	s.releaseJourneyCapacityLocked(j)
	_, _ = s.reserveJourneyCapacityLocked(j, j.NodePathIDs, j.ConnectionIDs, j.Cooled, len(remainSamples))

	j.SampleIDs = remainSamples
	j.CapacityUsed = len(remainSamples)
	if len(remainSamples) == 1 && len(j.ConnectionIDs) <= 1 {
		j.RouteMode = "direct"
	} else if len(remainSamples) == 1 {
		j.RouteMode = "multi_stop"
	}
	j.PlanVersion++

	baseTime, _ := parseTime(splitSmp.EarliestCollectionAt)
	if baseTime.IsZero() {
		baseTime = now
	}
	deadAt, _ := parseTime(splitSmp.DeliveryDeadline)
	route := s.evaluateServiceabilityAndRouteLocked(splitSmp.Origin, splitSmp.OriginType, j.OriginNodeID, splitST, baseTime, deadAt, len(splitSamples), splitSmp.Sealed)
	splitJ, _, _ := s.buildJourneyForSampleLocked(splitSmp, splitST, route, splitSmp.Sealed, actor.UserID, sess.ActiveRole, now)
	splitJ.ParentJourneyID = j.JourneyID
	splitJ.SampleIDs = splitSamples
	splitJ.CapacityUsed = len(splitSamples)
	if len(splitSamples) > 1 {
		splitJ.RouteMode = "batched"
	}
	j.SplitJourneyID = splitJ.JourneyID
	j.CapacityAvailable = s.computeMinPoolAvailableLocked(j.NodePathIDs, j.ConnectionIDs, j.Cooled)
	splitJ.CapacityAvailable = s.computeMinPoolAvailableLocked(splitJ.NodePathIDs, splitJ.ConnectionIDs, splitJ.Cooled)

	for _, sid := range splitSamples {
		if sm := s.state.Samples[sid]; sm != nil {
			sm.ActiveJourneyID = splitJ.JourneyID
			ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "split_journey", "sample", sm.SampleID, true, now, map[string]interface{}{
				"sourceJourneyId": j.JourneyID,
				"splitJourneyId":  splitJ.JourneyID,
			})
			sm.Timeline = append(sm.Timeline, ev)
		}
	}

	respData := map[string]interface{}{
		"journey":      s.buildJourneyPlanDTO(j),
		"splitJourney": s.buildJourneyPlanDTO(splitJ),
	}
	s.saveIdempotencyLocked("split_journey", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("journey.split", "journey", j.JourneyID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		TargetJourneyID     *string  `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.TargetJourneyID == nil || req.ExpectedPlanVersion == nil || req.SourceJourneyIDs == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	if !isValidUUID(*req.TargetJourneyID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid targetJourneyId")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "merge_journeys", "journey", true, "dispatcher", "administrator")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("merge_journeys", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	targetJ := s.state.Journeys[*req.TargetJourneyID]
	if targetJ == nil {
		writeError(w, http.StatusNotFound, "not_found", "Target journey not found")
		return
	}
	if targetJ.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "Plan version mismatch")
		return
	}
	if targetJ.Status == "cancelled" || targetJ.Status == "completed" || targetJ.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "Target journey is inactive")
		return
	}
	if len(req.SourceJourneyIDs) == 0 {
		writeError(w, http.StatusConflict, "invalid_merge", "sourceJourneyIds cannot be empty")
		return
	}

	var sourceJourneys []*JourneyModel
	for _, sjID := range req.SourceJourneyIDs {
		if !isValidUUID(sjID) || sjID == targetJ.JourneyID {
			writeError(w, http.StatusConflict, "invalid_merge", "Invalid sourceJourneyId")
			return
		}
		sj := s.state.Journeys[sjID]
		if sj == nil {
			writeError(w, http.StatusNotFound, "not_found", "Source journey not found")
			return
		}
		if sj.Status == "cancelled" || sj.Status == "completed" || sj.Status == "replaced" {
			writeError(w, http.StatusConflict, "inactive_plan", "Source journey is inactive")
			return
		}
		sourceJourneys = append(sourceJourneys, sj)
	}

	// Check if target or source has completed transport legs that make it a partial merge
	allJourneys := append([]*JourneyModel{targetJ}, sourceJourneys...)
	for _, aj := range allJourneys {
		for _, aid := range aj.TransportAssignmentIDs {
			if a := s.state.Assignments[aid]; a != nil && (a.Status == "picked_up" || a.Status == "in_transit" || a.Status == "delivered" || a.Status == "completed") {
				writeError(w, http.StatusConflict, "partial_journey_merge", "Cannot merge journey with transport legs already in progress or completed")
				return
			}
		}
		if aj.OriginNodeID != targetJ.OriginNodeID || aj.TargetLaboratoryID != targetJ.TargetLaboratoryID {
			writeError(w, http.StatusConflict, "partial_journey_merge", "Journeys do not share the same origin node and target laboratory")
			return
		}
	}

	// Collect all samples and validate compatibility, Pulse rules, deadlines, and worker capacity
	var allSampleIDs []string
	var allSamples []*SampleModel
	var allSampleTypes []*SampleTypeModel

	for _, aj := range allJourneys {
		for _, sid := range aj.SampleIDs {
			smp := s.state.Samples[sid]
			if smp == nil {
				continue
			}
			st := s.state.SampleTypes[smp.SampleTypeID]
			if isPulseSampleType(st) {
				s.recordAuditLocked(actor.UserID, sess.ActiveRole, "merge_journeys", "journey", targetJ.JourneyID, false, now, map[string]interface{}{"reason": "pulse_no_batch"})
				_ = s.persistLocked(r.Context())
				writeError(w, http.StatusConflict, "pulse_no_batch", "Pulse samples cannot be combined into a consolidation batch")
				return
			}
			allSampleIDs = append(allSampleIDs, sid)
			allSamples = append(allSamples, smp)
			allSampleTypes = append(allSampleTypes, st)
		}
	}

	// Pairwise compatibility check
	for i := 0; i < len(allSampleTypes); i++ {
		for j := i + 1; j < len(allSampleTypes); j++ {
			if !areSampleTypesCompatible(allSampleTypes[i], allSampleTypes[j]) {
				s.recordAuditLocked(actor.UserID, sess.ActiveRole, "merge_journeys", "journey", targetJ.JourneyID, false, now, map[string]interface{}{"reason": "incompatible_batch"})
				_ = s.persistLocked(r.Context())
				writeError(w, http.StatusConflict, "incompatible_batch", "Samples have incompatible container, temperature, or handling rules")
				return
			}
		}
	}

	// Check deadline for every sample against targetJ's estimatedDeliveryAt (accounting for latest collection time of all samples)
	latestStart, _ := parseTime(targetJ.EstimatedDeliveryAt)
	maxEarliest := time.Time{}
	for _, smp := range allSamples {
		if t, err := parseTime(smp.EarliestCollectionAt); err == nil && t.After(maxEarliest) {
			maxEarliest = t
		}
	}
	totalRouteMins := 0
	for _, nid := range targetJ.NodePathIDs {
		if loc := s.state.Locations[nid]; loc != nil {
			totalRouteMins += loc.HandlingMinutes
		}
	}
	for _, cid := range targetJ.ConnectionIDs {
		if conn := s.state.Connections[cid]; conn != nil {
			totalRouteMins += conn.TravelMinutes
		}
	}
	batchArrival := maxEarliest.Add(time.Duration(totalRouteMins) * time.Minute)
	if batchArrival.After(latestStart) {
		latestStart = batchArrival
	}
	for _, smp := range allSamples {
		if deadT, err := parseTime(smp.DeliveryDeadline); err == nil && latestStart.After(deadT) {
			s.recordAuditLocked(actor.UserID, sess.ActiveRole, "merge_journeys", "journey", targetJ.JourneyID, false, now, map[string]interface{}{"reason": "delivery_deadline_exceeded"})
			_ = s.persistLocked(r.Context())
			writeError(w, http.StatusConflict, "delivery_deadline_exceeded", "Batch arrival exceeds a sample's delivery deadline")
			return
		}
	}

	// Check assigned workers' capacity for batch size
	batchSize := len(allSampleIDs)
	for _, aid := range targetJ.TransportAssignmentIDs {
		if a := s.state.Assignments[aid]; a != nil && a.WorkerID != "" {
			if wu := s.state.Users[a.WorkerID]; wu != nil && wu.CapacityUnits < batchSize {
				s.recordAuditLocked(actor.UserID, sess.ActiveRole, "merge_journeys", "journey", targetJ.JourneyID, false, now, map[string]interface{}{"reason": "capacity_exceeded"})
				_ = s.persistLocked(r.Context())
				writeError(w, http.StatusConflict, "capacity_exceeded", "Batch size exceeds assigned worker's capacity")
				return
			}
		}
	}

	// Release source journeys' capacity and cancel their uncompleted transport/lab assignments
	s.releaseJourneyCapacityLocked(targetJ)
	for _, sj := range sourceJourneys {
		s.releaseJourneyCapacityLocked(sj)
	}
	okCap, capCode := s.reserveJourneyCapacityLocked(targetJ, targetJ.NodePathIDs, targetJ.ConnectionIDs, targetJ.Cooled, batchSize)
	if !okCap {
		// Restore original reservations
		_, _ = s.reserveJourneyCapacityLocked(targetJ, targetJ.NodePathIDs, targetJ.ConnectionIDs, targetJ.Cooled, len(targetJ.SampleIDs))
		for _, sj := range sourceJourneys {
			_, _ = s.reserveJourneyCapacityLocked(sj, sj.NodePathIDs, sj.ConnectionIDs, sj.Cooled, len(sj.SampleIDs))
		}
		writeError(w, http.StatusConflict, capCode, "Insufficient capacity for merged batch")
		return
	}

	for _, sj := range sourceJourneys {
		for _, aid := range sj.AssignmentIDs {
			a := s.state.Assignments[aid]
			if a == nil {
				continue
			}
			if a.Kind == "collection" {
				// Keep collection assignment and attach to targetJ
				a.JourneyID = targetJ.JourneyID
				targetJ.CollectionAssignmentIDs = append(targetJ.CollectionAssignmentIDs, a.AssignmentID)
				targetJ.AssignmentIDs = append([]string{a.AssignmentID}, targetJ.AssignmentIDs...)
			} else if a.Status != "completed" && a.Status != "delivered" {
				if a.CapacityReserved {
					a.CapacityReserved = false
					if u := s.state.Users[a.WorkerID]; u != nil && u.ReservedUnits > 0 {
						u.ReservedUnits--
					}
				}
				a.Status = "cancelled"
			}
		}
		sj.Status = "replaced"
		sj.ReplacementJourneyID = targetJ.JourneyID
	}

	targetJ.SampleIDs = allSampleIDs
	targetJ.RouteMode = "batched"
	targetJ.CapacityUsed = batchSize
	targetJ.EstimatedDeliveryAt = formatTime(latestStart)
	targetJ.PlanVersion++
	targetJ.CapacityAvailable = s.computeMinPoolAvailableLocked(targetJ.NodePathIDs, targetJ.ConnectionIDs, targetJ.Cooled)

	for _, aid := range targetJ.TransportAssignmentIDs {
		if a := s.state.Assignments[aid]; a != nil {
			a.SampleIDs = allSampleIDs
			a.UnitsReserved = batchSize
		}
	}

	for _, smp := range allSamples {
		smp.ActiveJourneyID = targetJ.JourneyID
		ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "merge_journeys", "sample", smp.SampleID, true, now, map[string]interface{}{
			"targetJourneyId": targetJ.JourneyID,
			"sampleIds":       allSampleIDs,
		})
		smp.Timeline = append(smp.Timeline, ev)
	}

	respData := s.buildJourneyPlanDTO(targetJ)
	s.saveIdempotencyLocked("merge_journeys", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("journey.merged", "journey", targetJ.JourneyID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	var req struct {
		JourneyID           *string                `json:"journeyId"`
		ExpectedPlanVersion *int                   `json:"expectedPlanVersion"`
		ChangeType          *string                `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      *string                `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req)
	if err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.ChangeType == nil || req.Changes == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON payload")
		return
	}
	if strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	if !isValidUUID(*req.JourneyID) {
		writeError(w, http.StatusBadRequest, "invalid_json", "Invalid journeyId")
		return
	}

	validChangeTypes := map[string]bool{
		"add_stop":        true,
		"remove_stop":     true,
		"reorder_stops":   true,
		"replace_worker":  true,
		"reassign_worker": true,
		"merge_samples":   true,
		"split_samples":   true,
		"split_batch":     true,
		"cancel_work":     true,
		"reroute":         true,
		"replace_route":   true,
	}
	changeType := strings.TrimSpace(*req.ChangeType)
	if !validChangeTypes[changeType] {
		writeError(w, http.StatusBadRequest, "invalid_change_type", "Invalid changeType")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "edit_active_plan", "journey", true, "dispatcher", "administrator")
	if !ok {
		return
	}

	stCode, cachedResp, exists, conflict := s.checkIdempotencyLocked("edit_active_plan", actor.UserID, *req.IdempotencyKey, rawBody)
	if conflict {
		writeError(w, http.StatusConflict, "idempotency_conflict", "Idempotency key reused with different payload")
		return
	}
	if exists {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(stCode)
		_, _ = w.Write(cachedResp)
		return
	}

	j := s.state.Journeys[*req.JourneyID]
	if j == nil {
		writeError(w, http.StatusNotFound, "not_found", "Journey not found")
		return
	}
	if j.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "Plan version mismatch")
		return
	}
	if j.Status == "cancelled" || j.Status == "completed" || j.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "Journey is inactive")
		return
	}

	switch changeType {
	case "replace_worker", "reassign_worker":
		aid, _ := req.Changes["assignmentId"].(string)
		wid, _ := req.Changes["workerId"].(string)
		if wid == "" {
			wid, _ = req.Changes["newWorkerId"].(string)
		}
		if aid == "" && len(j.TransportAssignmentIDs) > 0 {
			aid = j.TransportAssignmentIDs[0]
		}
		if !isValidUUID(aid) || !isValidUUID(wid) {
			writeError(w, http.StatusBadRequest, "invalid_worker", "Invalid assignmentId or workerId")
			return
		}
		a := s.state.Assignments[aid]
		newW := s.state.Users[wid]
		if a == nil || a.JourneyID != j.JourneyID {
			writeError(w, http.StatusConflict, "invalid_assignment", "Assignment does not belong to journey")
			return
		}
		if newW == nil {
			writeError(w, http.StatusBadRequest, "invalid_worker", "Worker not found")
			return
		}
		if a.Status == "completed" || a.Status == "delivered" {
			writeError(w, http.StatusConflict, "completed_work_immutable", "Cannot reassign completed work")
			return
		}
		if a.Status == "picked_up" || a.Status == "in_transit" {
			writeError(w, http.StatusConflict, "work_in_progress", "Cannot replace worker while sample custody is in transit")
			return
		}
		smp := s.state.Samples[a.SampleID]
		var st *SampleTypeModel
		if smp != nil {
			st = s.state.SampleTypes[smp.SampleTypeID]
		}
		okQual, _ := s.isWorkerEligibleForAssignmentLocked(newW, a, st, now, false)
		if !okQual {
			writeError(w, http.StatusConflict, "ineligible_worker", "Replacement worker is not eligible")
			return
		}
		if !newW.Available {
			writeError(w, http.StatusConflict, "worker_unavailable", "Replacement worker is unavailable")
			return
		}
		if newW.CapacityUnits < j.CapacityUsed {
			writeError(w, http.StatusConflict, "capacity_exceeded", "Worker does not have enough capacity for this journey")
			return
		}
		if a.CapacityReserved {
			a.CapacityReserved = false
			if oldW := s.state.Users[a.WorkerID]; oldW != nil && oldW.ReservedUnits > 0 {
				oldW.ReservedUnits--
			}
		}
		s.offerAssignmentToWorkerLocked(a, newW, now)
		j.PlanVersion++

	case "reorder_stops":
		// Validate stop order: pickup must be first, delivery must be last, completed stops cannot be moved
		rawStopIDs, okS := req.Changes["stopIds"].([]interface{})
		rawLocIDs, okL := req.Changes["locationIds"].([]interface{})
		if !okS && !okL {
			writeError(w, http.StatusConflict, "invalid_stop_order", "Missing stopIds or locationIds")
			return
		}
		var newOrder []JourneyStop
		if okS {
			if len(rawStopIDs) != len(j.OrderedStops) {
				writeError(w, http.StatusConflict, "invalid_stop_order", "Stop count mismatch")
				return
			}
			byID := map[string]JourneyStop{}
			for _, stp := range j.OrderedStops {
				byID[stp.StopID] = stp
			}
			seen := map[string]bool{}
			for idx, rs := range rawStopIDs {
				sid, _ := rs.(string)
				stp, exists := byID[sid]
				if !exists || seen[sid] {
					writeError(w, http.StatusConflict, "invalid_stop_order", "Invalid or duplicate stopId")
					return
				}
				seen[sid] = true
				if j.OrderedStops[idx].CompletedAt != "" && j.OrderedStops[idx].StopID != sid {
					writeError(w, http.StatusConflict, "completed_work_immutable", "Cannot reorder completed stops")
					return
				}
				newOrder = append(newOrder, stp)
			}
		} else {
			if len(rawLocIDs) != len(j.OrderedStops) {
				writeError(w, http.StatusConflict, "invalid_stop_order", "Location count mismatch")
				return
			}
			byLoc := map[string]JourneyStop{}
			for _, stp := range j.OrderedStops {
				byLoc[stp.LocationID] = stp
			}
			seen := map[string]bool{}
			for idx, rl := range rawLocIDs {
				lid, _ := rl.(string)
				stp, exists := byLoc[lid]
				if !exists || seen[lid] {
					writeError(w, http.StatusConflict, "invalid_stop_order", "Invalid or duplicate locationId")
					return
				}
				seen[lid] = true
				if j.OrderedStops[idx].CompletedAt != "" && j.OrderedStops[idx].LocationID != lid {
					writeError(w, http.StatusConflict, "completed_work_immutable", "Cannot reorder completed stops")
					return
				}
				newOrder = append(newOrder, stp)
			}
		}
		if len(newOrder) < 2 || newOrder[0].StopType != "pickup" || newOrder[len(newOrder)-1].StopType != "delivery" {
			writeError(w, http.StatusConflict, "invalid_stop_order", "Pickup must precede handoff and delivery stops")
			return
		}
		// Verify connections exist for every adjacent pair
		var newConns []string
		var newNodePath []string
		for idx, stp := range newOrder {
			newOrder[idx].Sequence = idx + 1
			newNodePath = append(newNodePath, stp.LocationID)
			if idx > 0 {
				fromID := newOrder[idx-1].LocationID
				toID := stp.LocationID
				var matchedConn *ConnectionModel
				for _, conn := range s.state.Connections {
					if conn.Active && conn.FromLocationID == fromID && conn.ToLocationID == toID {
						if !j.Cooled || conn.Cooled {
							matchedConn = conn
							break
						}
					}
				}
				if matchedConn == nil {
					writeError(w, http.StatusConflict, "invalid_route", "No active valid connection for reordered stops")
					return
				}
				newConns = append(newConns, matchedConn.ConnectionID)
			}
		}
		j.OrderedStops = newOrder
		j.NodePathIDs = newNodePath
		j.ConnectionIDs = newConns
		j.PlanVersion++

	case "add_stop":
		locID, _ := req.Changes["locationId"].(string)
		if !isValidUUID(locID) {
			writeError(w, http.StatusConflict, "invalid_stop", "Invalid locationId")
			return
		}
		loc := s.state.Locations[locID]
		if loc == nil || !loc.Active || (!loc.Functions.TransferPoint && !loc.Functions.Hub) {
			writeError(w, http.StatusConflict, "invalid_stop", "Stop location is inactive or not a transfer/hub node")
			return
		}
		if dwellVal, hasDwell := req.Changes["dwellMinutes"]; hasDwell {
			if dv, ok := dwellVal.(float64); ok && dv < 0 {
				writeError(w, http.StatusBadRequest, "invalid_dwell", "dwellMinutes cannot be negative")
				return
			}
		}
		// Check Pulse samples cannot have added batch/wait stops
		for _, sid := range j.SampleIDs {
			if smp := s.state.Samples[sid]; smp != nil {
				if isPulseSampleType(s.state.SampleTypes[smp.SampleTypeID]) {
					writeError(w, http.StatusConflict, "pulse_no_wait", "Pulse sample cannot wait at additional consolidation stop")
					return
				}
			}
		}
		// Insert before final delivery stop and validate connections, capacity, and deadline
		if len(j.NodePathIDs) < 2 {
			writeError(w, http.StatusConflict, "invalid_stop", "Journey cannot accept intermediate stop")
			return
		}
		prevNode := j.NodePathIDs[len(j.NodePathIDs)-2]
		finalNode := j.NodePathIDs[len(j.NodePathIDs)-1]
		var conn1, conn2 *ConnectionModel
		for _, c := range s.state.Connections {
			if c.Active && (!j.Cooled || c.Cooled) {
				if c.FromLocationID == prevNode && c.ToLocationID == locID {
					conn1 = c
				}
				if c.FromLocationID == locID && c.ToLocationID == finalNode {
					conn2 = c
				}
			}
		}
		if conn1 == nil || conn2 == nil {
			writeError(w, http.StatusConflict, "no_valid_route", "No valid connections through added stop")
			return
		}
		if !hasResourceCapacity(loc.Capacity, j.Cooled, j.CapacityUsed) ||
			!hasResourceCapacity(conn1.Capacity, j.Cooled, j.CapacityUsed) ||
			!hasResourceCapacity(conn2.Capacity, j.Cooled, j.CapacityUsed) {
			if j.Cooled {
				writeError(w, http.StatusConflict, "cooled_capacity_exhausted", "Cooled capacity exhausted on added stop")
			} else {
				writeError(w, http.StatusConflict, "capacity_exhausted", "Capacity exhausted on added stop")
			}
			return
		}
		// Check deadline
		extraMins := conn1.TravelMinutes + conn2.TravelMinutes + loc.HandlingMinutes
		if len(j.ConnectionIDs) > 0 {
			if oldLast := s.state.Connections[j.ConnectionIDs[len(j.ConnectionIDs)-1]]; oldLast != nil {
				extraMins -= oldLast.TravelMinutes
			}
		}
		estT, _ := parseTime(j.EstimatedDeliveryAt)
		newEstT := estT.Add(time.Duration(extraMins) * time.Minute)
		for _, sid := range j.SampleIDs {
			if smp := s.state.Samples[sid]; smp != nil {
				if deadT, err := parseTime(smp.DeliveryDeadline); err == nil && newEstT.After(deadT) {
					writeError(w, http.StatusConflict, "delivery_deadline_exceeded", "Adding stop would exceed sample delivery deadline")
					return
				}
			}
		}

		// Rebuild path with added stop
		newNodes := append([]string{}, j.NodePathIDs[:len(j.NodePathIDs)-1]...)
		newNodes = append(newNodes, locID, finalNode)
		newConns := append([]string{}, j.ConnectionIDs[:len(j.ConnectionIDs)-1]...)
		newConns = append(newConns, conn1.ConnectionID, conn2.ConnectionID)

		s.releaseJourneyCapacityLocked(j)
		_, _ = s.reserveJourneyCapacityLocked(j, newNodes, newConns, j.Cooled, j.CapacityUsed)
		j.NodePathIDs = newNodes
		j.ConnectionIDs = newConns
		j.RouteMode = "multi_stop"
		if j.CapacityUsed > 1 {
			j.RouteMode = "batched"
		}
		j.EstimatedDeliveryAt = formatTime(newEstT)
		c := loc.Coordinate
		newStop := JourneyStop{
			StopID:       newUUID(),
			LocationID:   locID,
			LocationID2:  locID,
			StopType:     "handoff",
			StopType2:    "handoff",
			Sequence:     len(j.OrderedStops),
			EstimatedAt:  formatTime(newEstT.Add(-time.Duration(conn2.TravelMinutes) * time.Minute)),
			EstimatedAt2: formatTime(newEstT.Add(-time.Duration(conn2.TravelMinutes) * time.Minute)),
			DwellMinutes: loc.HandlingMinutes,
			Coordinate:   &c,
		}
		lastStop := j.OrderedStops[len(j.OrderedStops)-1]
		lastStop.Sequence = len(j.OrderedStops) + 1
		lastStop.EstimatedAt = formatTime(newEstT)
		lastStop.EstimatedAt2 = formatTime(newEstT)
		j.OrderedStops = append(j.OrderedStops[:len(j.OrderedStops)-1], newStop, lastStop)
		j.PlanVersion++
		j.CapacityAvailable = s.computeMinPoolAvailableLocked(j.NodePathIDs, j.ConnectionIDs, j.Cooled)

	case "remove_stop":
		locID, _ := req.Changes["locationId"].(string)
		stopID, _ := req.Changes["stopId"].(string)
		targetIdx := -1
		for idx, stp := range j.OrderedStops {
			if (locID != "" && stp.LocationID == locID) || (stopID != "" && stp.StopID == stopID) {
				targetIdx = idx
				break
			}
		}
		if targetIdx <= 0 || targetIdx >= len(j.OrderedStops)-1 {
			writeError(w, http.StatusConflict, "invalid_stop", "Can only remove an intermediate stop")
			return
		}
		if j.OrderedStops[targetIdx].CompletedAt != "" {
			writeError(w, http.StatusConflict, "completed_work_immutable", "Cannot remove a completed stop")
			return
		}
		prevID := j.OrderedStops[targetIdx-1].LocationID
		nextID := j.OrderedStops[targetIdx+1].LocationID
		var directConn *ConnectionModel
		for _, c := range s.state.Connections {
			if c.Active && c.FromLocationID == prevID && c.ToLocationID == nextID && (!j.Cooled || c.Cooled) {
				directConn = c
				break
			}
		}
		if directConn == nil {
			writeError(w, http.StatusConflict, "no_valid_route", "No direct connection after removing stop")
			return
		}
		j.OrderedStops = append(j.OrderedStops[:targetIdx], j.OrderedStops[targetIdx+1:]...)
		for idx := range j.OrderedStops {
			j.OrderedStops[idx].Sequence = idx + 1
		}
		if len(j.OrderedStops) == 2 && j.CapacityUsed == 1 {
			j.RouteMode = "direct"
		}
		j.PlanVersion++

	case "reroute", "replace_route":
		_, replJ := s.replanSingleJourneyLocked(j, actor.UserID, sess.ActiveRole, "edit_active_plan", now)
		if replJ != nil {
			j = replJ
		} else {
			writeError(w, http.StatusConflict, "no_valid_route", "No valid replacement route available")
			return
		}

	case "cancel_work":
		for _, aid := range j.AssignmentIDs {
			if a := s.state.Assignments[aid]; a != nil {
				if a.Status == "completed" || a.Status == "delivered" {
					continue
				}
				a.Status = "cancelled"
			}
		}
		j.Status = "cancelled"
		j.PlanVersion++
		s.releaseJourneyCapacityLocked(j)

	default:
		j.PlanVersion++
	}

	ev := s.recordAuditLocked(actor.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, now, map[string]interface{}{
		"journeyId":   j.JourneyID,
		"changeType":  changeType,
		"planVersion": j.PlanVersion,
	})
	j.History = append(j.History, ev)

	respData := s.buildJourneyPlanDTO(j)
	s.saveIdempotencyLocked("edit_active_plan", actor.UserID, *req.IdempotencyKey, rawBody, http.StatusCreated, respData)
	s.emitRealtimeLocked("journey.edited", "journey", j.JourneyID, respData)
	_ = s.persistLocked(r.Context())

	writeData(w, http.StatusCreated, respData)
}

func (s *Store) handleReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UTC()

	actor, sess, ok := s.authAndRoleLocked(w, r, "read_ui_bootstrap", "ui", false)
	if !ok {
		return
	}

	roleSelectionRequired := len(actor.Roles) > 1 && (!sess.ExplicitlySelected || sess.ActiveRole == "")

	userDTO := map[string]interface{}{
		"userId":                actor.UserID,
		"username":              actor.Username,
		"roles":                 actor.Roles,
		"activeRole":            sess.ActiveRole,
		"roleSelectionRequired": roleSelectionRequired,
	}
	if actor.FullName != "" {
		userDTO["fullName"] = actor.FullName
	}

	resp := map[string]interface{}{
		"user":       userDTO,
		"serverTime": formatTime(now),
	}

	if sess.ActiveRole == "requester" {
		reqSamples := []map[string]interface{}{}
		for _, smp := range s.state.Samples {
			if smp.RequesterID == actor.UserID {
				dto := s.buildSampleStateDTO(smp)
				dto["status"] = smp.Status
				dto["sealed"] = smp.Sealed
				if smp.CurrentHolderID != "" {
					dto["currentHolderId"] = smp.CurrentHolderID
				}
				if smp.Exception != nil {
					dto["exception"] = smp.Exception
				}
				if smp.CompletedLegIDs != nil {
					dto["completedLegIds"] = smp.CompletedLegIDs
				} else {
					dto["completedLegIds"] = []string{}
				}
				reqSamples = append(reqSamples, dto)
			}
		}
		resp["requesterSamples"] = reqSamples
	} else if sess.ActiveRole == "dispatcher" || sess.ActiveRole == "administrator" {
		resp["operations"] = s.buildOperationsStateLocked("")
	} else if sess.ActiveRole == "laboratory_team" || sess.ActiveRole == "node_handler" {
		myLocs := []map[string]interface{}{}
		assignedLoc := s.state.Locations[actor.AssignedLocationID]
		for _, loc := range s.state.Locations {
			include := false
			if actor.AssignedLocationID != "" && loc.LocationID == actor.AssignedLocationID {
				include = true
			} else if sess.ActiveRole == "laboratory_team" && (assignedLoc == nil || !assignedLoc.Functions.Laboratory) && loc.Functions.Laboratory {
				include = true
			} else if sess.ActiveRole == "node_handler" && (assignedLoc == nil || (!assignedLoc.Functions.CollectionPoint && !assignedLoc.Functions.TransferPoint && !assignedLoc.Functions.Hub)) && (loc.Functions.CollectionPoint || loc.Functions.TransferPoint || loc.Functions.Hub) {
				include = true
			}
			if include {
				accIDs := []string{}
				for stID, ok := range loc.AcceptedSampleTypes {
					if ok {
						accIDs = append(accIDs, stID)
					}
				}
				sort.Strings(accIDs)
				myLocs = append(myLocs, map[string]interface{}{
					"id":                    loc.LocationID,
					"locationId":            loc.LocationID,
					"name":                  loc.Name,
					"coordinate":            loc.Coordinate,
					"active":                loc.Active,
					"coverageKm":            loc.CoverageKm,
					"handlingMinutes":       loc.HandlingMinutes,
					"functions":             loc.Functions,
					"capacity":              loc.Capacity,
					"acceptedSampleTypeIds": accIDs,
				})
			}
		}
		resp["operations"] = map[string]interface{}{
			"samples":                   []map[string]interface{}{},
			"workers":                   []map[string]interface{}{},
			"locations":                 myLocs,
			"connections":               []map[string]interface{}{},
			"routes":                    []map[string]interface{}{},
			"handoffs":                  []map[string]interface{}{},
			"delays":                    []map[string]interface{}{},
			"exceptions":                []map[string]interface{}{},
			"assignmentCountSpread":     0,
			"ineligibleAssignmentCount": 0,
		}
	}

	writeData(w, http.StatusOK, resp)
}

var wsUpgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

func (s *Store) handleStreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}

	sinceStr := strings.TrimSpace(r.URL.Query().Get("since"))
	var since int64 = 0
	if sinceStr != "" {
		v, err := strconv.ParseInt(sinceStr, 10, 64)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "invalid_json", "Invalid since parameter")
			return
		}
		since = v
	}

	s.mu.Lock()
	_, _, ok := s.authAndRoleLocked(w, r, "stream_realtime_events", "events", false)
	if !ok {
		s.mu.Unlock()
		return
	}

	var events []RealtimeEvent
	var cursor int64 = since
	for _, ev := range s.state.RealtimeEvents {
		if ev.ID > since {
			events = append(events, ev)
		}
		if ev.ID > cursor {
			cursor = ev.ID
		}
	}
	s.mu.Unlock()
	if events == nil {
		events = []RealtimeEvent{}
	}

	// Check if client requested WebSocket upgrade
	if strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		respHeader := http.Header{}
		if proto := r.Header.Get("Sec-WebSocket-Protocol"); proto != "" {
			parts := strings.Split(proto, ",")
			if len(parts) > 0 {
				respHeader.Set("Sec-WebSocket-Protocol", strings.TrimSpace(parts[0]))
			}
		}
		conn, err := wsUpgrader.Upgrade(w, r, respHeader)
		if err != nil {
			return
		}
		defer conn.Close()

		for _, ev := range events {
			if err := conn.WriteJSON(ev); err != nil {
				return
			}
		}

		sub := s.SubscribeWS()
		defer s.UnsubscribeWS(sub)

		done := make(chan struct{})
		go func() {
			defer close(done)
			for {
				if _, _, err := conn.ReadMessage(); err != nil {
					return
				}
			}
		}()

		for {
			select {
			case <-done:
				return
			case <-r.Context().Done():
				return
			case ev, ok := <-sub:
				if !ok {
					return
				}
				if err := conn.WriteJSON(ev); err != nil {
					return
				}
			}
		}
	}

	writeData(w, http.StatusOK, map[string]interface{}{
		"events": events,
		"cursor": cursor,
	})
}

func (s *Store) handleReadiness(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Method not allowed")
		return
	}
	if err := s.db.Ping(r.Context()); err != nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "starting"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
}

