import { chromium } from "/usr/local/lib/node_modules/@playwright/test/node_modules/playwright/index.mjs";

const BASE = "http://127.0.0.1:8080";

async function api(path, token, body) {
  const res = await fetch(BASE + path, {
    method: body ? "POST" : "GET",
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: "Bearer " + token } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json();
  return { status: res.status, json };
}

(async () => {
  // Seed network and users via API using initial admin
  const authRes = await api("/api/authenticate-user", "", {
    username: "admin",
    password: "admin-pass-123",
  });
  if (authRes.status !== 200) throw new Error("Admin login failed: " + JSON.stringify(authRes));
  const adminToken = authRes.json.data.sessionToken;

  const nodeRes = await api("/api/create-location", adminToken, {
    name: "Indiranagar Collection Hub",
    coordinate: { latitude: 12.9716, longitude: 77.5946 },
    coverageKm: 5.0,
    handlingMinutes: 5,
    active: true,
    functions: ["collection_point", "transfer_point", "hub"],
  });
  const nodeId = nodeRes.json.data.locationId;

  const labRes = await api("/api/create-location", adminToken, {
    name: "Central Clinical Lab",
    coordinate: { latitude: 12.98, longitude: 77.61 },
    coverageKm: 5.0,
    handlingMinutes: 10,
    active: true,
    functions: ["laboratory"],
  });
  const labId = labRes.json.data.locationId;

  // Configure capacity on lab
  await api("/api/configure-capacity", adminToken, {
    resourceId: labId,
    capacityUnits: 25,
    cooledCapacityUnits: 12,
  });

  // Read operations state to get default sampleTypeIds
  const amberId = "62c47901-4b11-49d9-adf1-f1327479f575";

  await api("/api/configure-laboratory-acceptance", adminToken, {
    laboratoryId: labId,
    sampleTypeId: amberId,
    accepts: true,
  });

  await api("/api/create-connection", adminToken, {
    fromLocationId: nodeId,
    toLocationId: labId,
    travelMinutes: 15,
    costUnits: 5,
    cooled: true,
    active: true,
  });

  // Create multi-role user with all roles
  await api("/api/create-user", adminToken, {
    username: "multirole",
    initialPassword: "pass-123",
    fullName: "Multi Role Worker",
    roles: ["requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher"],
    qualifications: ["Amber", "Indigo", "Frost", "Pulse"],
    active: true,
    assignedLocationId: labId,
  });

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  const externalRequests = [];
  page.on("request", (req) => {
    const url = req.url();
    if (!url.startsWith("http://127.0.0.1:8080") && !url.startsWith("ws://127.0.0.1:8080") && !url.startsWith("data:") && !url.startsWith("blob:")) {
      externalRequests.push(url);
    }
  });

  // 1. login_rejects_invalid_credentials
  await page.goto(BASE);
  await page.getByLabel("Username").fill("admin");
  await page.getByLabel("Password").fill("wrong-password");
  await page.getByRole("button", { name: "Sign In" }).click();
  await page.getByRole("alert").waitFor({ state: "visible" });
  console.log("PASS 1: login_rejects_invalid_credentials");

