import React, { useState, useEffect, useCallback } from 'react';
import { OfflineMap, MapMarkerItem } from './OfflineMap';

const DEFAULT_SAMPLE_TYPES = [
  { id: '62c47901-4b11-49d9-adf1-f1327479f575', name: 'Amber', container: 'standard_tube', minC: 15, maxC: 25 },
  { id: 'a0e30701-3a4e-4bb9-864a-aed9566e3b60', name: 'Indigo', container: 'isolated_tube', minC: 15, maxC: 25 },
  { id: '92360f2f-c258-473e-a8b1-719754af7830', name: 'Frost', container: 'cryo_vial', minC: -20, maxC: 4 },
  { id: '90948078-e9f1-4dda-b0ec-478fcba02079', name: 'Pulse', container: 'stat_tube', minC: 2, maxC: 25 },
];

function makeIdempotencyKey(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function App() {
  const [token, setToken] = useState<string>(() => localStorage.getItem('session_token') || '');
  const [user, setUser] = useState<any>(null);
  const [activeRole, setActiveRole] = useState<string>('');
  const [usernameInput, setUsernameInput] = useState('');
  const [passwordInput, setPasswordInput] = useState('');
  const [authError, setAuthError] = useState('');
  const [actionMessage, setActionMessage] = useState('');
  const [actionError, setActionError] = useState('');

  // Role work state
  const [currentWork, setCurrentWork] = useState<any[]>([]);
  const [pastWork, setPastWork] = useState<any[]>([]);
  const [allWorkItems, setAllWorkItems] = useState<any[]>([]);

  // Sample & Requester state
  const [requesterSamples, setRequesterSamples] = useState<any[]>([]);
  const [selectedSample, setSelectedSample] = useState<any>(null);
  const [sampleLookupId, setSampleLookupId] = useState('');

  // Request / Serviceability form state
  const [originType, setOriginType] = useState('home');
  const [originLat, setOriginLat] = useState('12.9716');
  const [originLng, setOriginLng] = useState('77.5946');
  const [sampleTypeId, setSampleTypeId] = useState(DEFAULT_SAMPLE_TYPES[0].id);
  const [containerType, setContainerType] = useState('standard_tube');
  const [tempMin, setTempMin] = useState('15');
  const [tempMax, setTempMax] = useState('25');
  const [windowStart, setWindowStart] = useState(() => new Date(Date.now() - 60000).toISOString());
  const [windowEnd, setWindowEnd] = useState(() => new Date(Date.now() + 65 * 60000).toISOString());
  const [deadlineAt, setDeadlineAt] = useState(() => new Date(Date.now() + 180 * 60000).toISOString());
  const [requestFormError, setRequestFormError] = useState('');
  const [serviceabilityResult, setServiceabilityResult] = useState<any>(null);

  // Worker location form state
  const [workerLat, setWorkerLat] = useState('12.9720');
  const [workerLng, setWorkerLng] = useState('77.5950');
  const [workerSeq, setWorkerSeq] = useState(1);
  const [lastRecordedLocation, setLastRecordedLocation] = useState<any>(null);

  // Capacity state (lab worker / node handler / admin)
  const [ownLocations, setOwnLocations] = useState<any[]>([]);
  const [capTargetId, setCapTargetId] = useState('');
  const [capRegular, setCapRegular] = useState('10');
  const [capCooled, setCapCooled] = useState('5');

  // Operations monitor state
  const [operationsState, setOperationsState] = useState<any>(null);

  // Audit search state
  const [auditQuery, setAuditQuery] = useState('');
  const [auditActionFilter, setAuditActionFilter] = useState('');
  const [auditRoleFilter, setAuditRoleFilter] = useState('');
  const [auditEntries, setAuditEntries] = useState<any[]>([]);
  const [checkpointTemp, setCheckpointTemp] = useState('22');

  const apiCall = useCallback(
    async (path: string, method: string = 'POST', body?: any, overrideToken?: string) => {
      const authToken = overrideToken !== undefined ? overrideToken : token;
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
      };
      if (authToken) {
        headers['Authorization'] = `Bearer ${authToken}`;
      }
      const res = await fetch(path, {
        method,
        headers,
        body: body !== undefined ? JSON.stringify(body) : undefined,
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) {
        const errObj = json?.error || { code: 'request_failed', message: `HTTP ${res.status}` };
        const error: any = new Error(errObj.message || errObj.code || 'Request failed');
        error.code = errObj.code;
        error.status = res.status;
        throw error;
      }
      return json?.data;
    },
    [token]
  );

  const loadRoleWork = useCallback(
    async (roleToLoad: string, authToken?: string) => {
      if (!roleToLoad) return;
      try {
        const data = await apiCall('/api/list-role-work', 'POST', { role: roleToLoad }, authToken);
        const cur = [...(data?.pending || []), ...(data?.inProgress || []), ...(data?.currentWork || [])];
        const past = [...(data?.completed || []), ...(data?.pastWork || [])];
        setCurrentWork(cur);
        setPastWork(past);
        setAllWorkItems(data?.items || [...cur, ...past]);
      } catch {
        // Ignore if role work fails prior to role selection
      }
    },
    [apiCall]
  );

  const loadMonitorAndAudit = useCallback(
    async (roleToLoad: string, authToken?: string) => {
      if (roleToLoad !== 'dispatcher' && roleToLoad !== 'administrator') return;
      try {
        const ops = await apiCall('/api/read-operations-state', 'POST', {}, authToken);
        setOperationsState(ops);
      } catch {
        // Ignore
      }
      try {
        const aud = await apiCall('/api/search-audit-trail', 'POST', { limit: 50 }, authToken);
        setAuditEntries(aud?.entries || []);
      } catch {
        // Ignore
      }
    },
    [apiCall]
  );

  const loadBootstrap = useCallback(
    async (overrideToken?: string) => {
      const activeTok = overrideToken !== undefined ? overrideToken : token;
      if (!activeTok) return;
      try {
        const data = await apiCall('/api/ui/bootstrap', 'GET', undefined, activeTok);
        if (data?.user) {
          const role = data.user.activeRole || data.user.roles?.[0] || '';
          if (data.requesterSamples) {
            setRequesterSamples(data.requesterSamples);
            if (data.requesterSamples.length > 0 && !selectedSample) {
              setSelectedSample(data.requesterSamples[0]);
            }
          }
          if (data.operations) {
            setOperationsState(data.operations);
            if (data.operations.locations) {
              setOwnLocations(data.operations.locations);
              if (data.operations.locations.length > 0) {
                const firstLoc = data.operations.locations[0];
                setCapTargetId(firstLoc.locationId || firstLoc.id);
                if (firstLoc.capacity) {
                  setCapRegular(String(firstLoc.capacity.capacityUnits ?? 10));
                  setCapCooled(String(firstLoc.capacity.cooledCapacityUnits ?? 5));
                }
              }
            }
          } else {
            setOwnLocations([]);
          }
          if (role && !data.user.roleSelectionRequired) {
            await loadRoleWork(role, activeTok);
            await loadMonitorAndAudit(role, activeTok);
          }
          setUser(data.user);
          setActiveRole(role);
        }
      } catch (err: any) {
        if (err.status === 401) {
          localStorage.removeItem('session_token');
          setToken('');
          setUser(null);
        }
      }
    },
    [apiCall, token, loadRoleWork, loadMonitorAndAudit, selectedSample]
  );

  useEffect(() => {
    if (token) {
      loadBootstrap(token);
    }
  }, [token]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    setActionError('');
    setActionMessage('');
    if (!usernameInput.trim() || !passwordInput) {
      setAuthError('Invalid credentials: username and password are required');
      return;
    }
    try {
      const data = await apiCall(
        '/api/authenticate-user',
        'POST',
        { username: usernameInput.trim(), password: passwordInput },
        ''
      );
      const sessionTok = data.sessionToken || data.token;
      localStorage.setItem('session_token', sessionTok);
      setToken(sessionTok);
      const roleReq = data.roleSelectionRequired ?? (!data.activeRole && (data.roles?.length || 0) > 1);
      setUser({
        userId: data.userId,
        username: data.username || usernameInput.trim(),
        roles: data.roles || [],
        activeRole: data.activeRole || '',
        roleSelectionRequired: roleReq,
      });
      const initialRole = data.activeRole || (data.roles?.length === 1 ? data.roles[0] : '');
      setActiveRole(initialRole);
      await loadBootstrap(sessionTok);
    } catch (err: any) {
      setAuthError(`Invalid username or password (${err.code || 'invalid_credentials'})`);
    }
  };

  const handleSignOut = () => {
    localStorage.removeItem('session_token');
    setToken('');
    setUser(null);
    setActiveRole('');
    setCurrentWork([]);
    setPastWork([]);
    setAllWorkItems([]);
    setRequesterSamples([]);
    setSelectedSample(null);
    setOperationsState(null);
    setAuditEntries([]);
    setAuthError('');
    setActionMessage('');
    setActionError('');
  };

  const handleRoleSwitch = async (newRole: string) => {
    setActionError('');
    setActionMessage('');
    try {
      const data = await apiCall('/api/select-active-role', 'POST', { role: newRole });
      await loadBootstrap();
      setUser((prev: any) =>
        prev
          ? {
              ...prev,
              roles: data.roles || prev.roles,
              activeRole: data.activeRole,
              roleSelectionRequired: false,
            }
          : prev
      );
      setActiveRole(data.activeRole);
      setActionMessage(`Switched active role to ${data.activeRole}`);
    } catch (err: any) {
      setActionError(`Failed to switch role: ${err.message}`);
    }
  };

  const buildOriginAndWindowPayload = () => {
    const lat = parseFloat(originLat);
    const lng = parseFloat(originLng);
    if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      throw new Error('Validation error: Origin latitude and longitude must be valid coordinates');
    }
    if (!sampleTypeId.trim()) {
      throw new Error('Validation error: Sample Type ID is required');
    }
    if (!containerType.trim()) {
      throw new Error('Validation error: Container type is required');
    }
    const minT = parseFloat(tempMin);
    const maxT = parseFloat(tempMax);
    if (Number.isNaN(minT) || Number.isNaN(maxT) || minT > maxT) {
      throw new Error('Validation error: Temperature range is invalid (min temperature cannot exceed max temperature)');
    }
    const ws = new Date(windowStart);
    const we = new Date(windowEnd);
    const dl = new Date(deadlineAt);
    if (Number.isNaN(ws.getTime()) || Number.isNaN(we.getTime()) || Number.isNaN(dl.getTime())) {
      throw new Error('Validation error: Collection window and delivery deadline must be valid ISO dates');
    }
    if (we.getTime() < ws.getTime()) {
      throw new Error('Validation error: Collection window latest time must be after earliest time (invalid_collection_window)');
    }
    if (dl.getTime() <= ws.getTime()) {
      throw new Error('Validation error: Delivery deadline must be after collection window start (invalid_delivery_deadline)');
    }
    const reqAt = new Date(Math.min(Date.now(), ws.getTime() - 1000)).toISOString();
    return {
      origin: { latitude: lat, longitude: lng },
      originType,
      sampleTypeId: sampleTypeId.trim(),
      requestedAt: reqAt,
      deliveryDeadline: dl.toISOString(),
      earliestCollectionAt: ws.toISOString(),
      latestCollectionAt: we.toISOString(),
      containerType: containerType.trim(),
      temperatureMinC: minT,
      temperatureMaxC: maxT,
    };
  };

  const handleCheckServiceability = async () => {
    setRequestFormError('');
    setServiceabilityResult(null);
    try {
      const full = buildOriginAndWindowPayload();
      const payload = {
        origin: full.origin,
        originType: full.originType,
        sampleTypeId: full.sampleTypeId,
        requestedAt: full.requestedAt,
        deliveryDeadline: full.deliveryDeadline,
        earliestCollectionAt: full.earliestCollectionAt,
        latestCollectionAt: full.latestCollectionAt,
      };
      const data = await apiCall('/api/check-serviceability', 'POST', payload);
      setServiceabilityResult(data);
    } catch (err: any) {
      setRequestFormError(err.message || 'Validation error');
    }
  };

  const handleCreateCollectionRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setRequestFormError('');
    setActionMessage('');
    try {
      const payload = {
        ...buildOriginAndWindowPayload(),
        idempotencyKey: makeIdempotencyKey('create-req'),
      };
      const data = await apiCall('/api/create-collection-request', 'POST', payload);
      setActionMessage(`Created sample request: ${data.sampleId}`);
      setSelectedSample(data);
      setRequesterSamples((prev) => [data, ...prev]);
      await handleLookupSample(data.sampleId);
      await loadBootstrap();
    } catch (err: any) {
      setRequestFormError(`Validation error (${err.code || 'invalid_request'}): ${err.message}`);
    }
  };

  const handleLookupSample = async (idToRead?: string) => {
    const target = (idToRead ?? sampleLookupId).trim();
    if (!target) return;
    setActionError('');
    try {
      const stateData = await apiCall(`/api/read-sample-state/${encodeURIComponent(target)}`, 'GET');
      let lcData: any = {};
      try {
        lcData = await apiCall('/api/read-sample-lifecycle', 'POST', { sampleId: target });
      } catch {
        // Ignore if lifecycle read fails
      }
      setSelectedSample({ ...stateData, ...lcData });
    } catch (err: any) {
      setActionError(`Could not load sample: ${err.message}`);
    }
  };

  const handleAcceptAssignment = async (assignmentId: string) => {
    setActionError('');
    setActionMessage('');
    try {
      const updated = await apiCall('/api/accept-assignment', 'POST', {
        assignmentId,
        idempotencyKey: makeIdempotencyKey('accept'),
      });
      setActionMessage(`Accepted assignment ${updated.assignmentId} (status: ${updated.status})`);
      setCurrentWork((prev) =>
        prev.map((item) => (item.assignmentId === assignmentId ? { ...item, ...updated, status: 'accepted' } : item))
      );
      await loadRoleWork(activeRole);
    } catch (err: any) {
      setActionError(`Accept assignment failed: ${err.message}`);
    }
  };

  const handleDeclineAssignment = async (assignmentId: string) => {
    setActionError('');
    setActionMessage('');
    try {
      const updated = await apiCall('/api/decline-assignment', 'POST', {
        assignmentId,
        reason: 'Worker declined via UI',
        idempotencyKey: makeIdempotencyKey('decline'),
      });
      setActionMessage(`Declined assignment ${updated.assignmentId}`);
      await loadRoleWork(activeRole);
    } catch (err: any) {
      setActionError(`Decline assignment failed: ${err.message}`);
    }
  };

  const handleCollectAndSeal = async (sampleId: string, assignmentId: string) => {
    setActionError('');
    setActionMessage('');
    try {
      await apiCall('/api/collect-and-seal-sample', 'POST', {
        sampleId,
        assignmentId,
        collectedAt: new Date().toISOString(),
        containerType: containerType || 'amber-vial',
        observedTemperatureC: parseFloat(checkpointTemp) || 22,
        idempotencyKey: makeIdempotencyKey('seal'),
      });
      setActionMessage(`Collected and sealed sample ${sampleId}`);
      await loadRoleWork(activeRole);
      await handleLookupSample(sampleId);
    } catch (err: any) {
      setActionError(`Collect and seal failed: ${err.message}`);
    }
  };

  const handleRecordCheckpoint = async (sampleId: string, assignmentId: string) => {
    setActionError('');
    setActionMessage('');
    try {
      await apiCall('/api/record-handling-checkpoint', 'POST', {
        sampleId,
        assignmentId,
        containerType: containerType || 'amber-vial',
        observedTemperatureC: parseFloat(checkpointTemp) || 22,
        recordedAt: new Date().toISOString(),
        idempotencyKey: makeIdempotencyKey('checkpoint'),
      });
      setActionMessage(`Recorded handling checkpoint for sample ${sampleId}`);
      await loadRoleWork(activeRole);
      await handleLookupSample(sampleId);
    } catch (err: any) {
      setActionError(`Handling checkpoint failed: ${err.message}`);
    }
  };

  const handleRecordWorkerLocation = async (e: React.FormEvent, sampleId?: string, journeyId?: string) => {
    e.preventDefault();
    setActionError('');
    setActionMessage('');
    try {
      const lat = parseFloat(workerLat);
      const lng = parseFloat(workerLng);
      const firstWork = currentWork[0] || allWorkItems[0];
      const assignmentId = firstWork?.assignmentId || firstWork?.assignment_id;
      if (!assignmentId) {
        throw new Error('No active assignment available to record location for');
      }
      const body: any = {
        assignmentId,
        coordinate: { latitude: lat, longitude: lng },
        recordedAt: new Date().toISOString(),
        sequence: workerSeq,
      };

      const data = await apiCall('/api/record-worker-location', 'POST', body);
      setLastRecordedLocation(data);
      setWorkerSeq((s) => s + 1);
      setActionMessage(
        `Recorded location (${data.coordinate.latitude}, ${data.coordinate.longitude}) at ${data.recordedAt}`
      );
      await loadRoleWork(activeRole);
      await loadBootstrap();
    } catch (err: any) {
      setActionError(`Record location failed: ${err.message}`);
    }
  };

  const handleConfigureCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!capTargetId) return;
    setActionError('');
    setActionMessage('');
    try {
      const data = await apiCall('/api/configure-capacity', 'POST', {
        resourceId: capTargetId,
        capacityUnits: parseInt(capRegular, 10),
        cooledCapacityUnits: parseInt(capCooled, 10),
      });
      setActionMessage(`Updated capacity for ${data.resourceId}`);
      await loadBootstrap();
      await loadRoleWork(activeRole);
    } catch (err: any) {
      setActionError(`Configure capacity failed: ${err.message}`);
    }
  };

  const handleSearchAudit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setActionError('');
    try {
      const body: any = { limit: 100 };
      if (auditQuery.trim()) body.query = auditQuery.trim();
      if (auditActionFilter.trim()) body.action = auditActionFilter.trim();
      if (auditRoleFilter.trim()) body.role = auditRoleFilter.trim();
      const data = await apiCall('/api/search-audit-trail', 'POST', body);
      setAuditEntries(data?.entries || []);
    } catch (err: any) {
      setActionError(`Audit search failed: ${err.message}`);
    }
  };

  // Build map markers from known locations, workers, and samples
  const mapMarkers: MapMarkerItem[] = [];
  if (operationsState?.locations) {
    operationsState.locations.forEach((loc: any) => {
      if (loc.coordinate) {
        mapMarkers.push({
          id: `loc-${loc.locationId || loc.id}`,
          label: loc.name || 'Node',
          kind: loc.functions?.laboratory ? 'lab' : 'node',
          latitude: loc.coordinate.latitude,
          longitude: loc.coordinate.longitude,
        });
      }
    });
  }
  if (operationsState?.workers) {
    operationsState.workers.forEach((w: any) => {
      const coord = w.latestLocation || w.coordinate;
      if (coord) {
        mapMarkers.push({
          id: `worker-${w.workerId || w.userId}`,
          label: w.fullName || w.username || 'Worker',
          kind: 'worker',
          latitude: coord.latitude,
          longitude: coord.longitude,
        });
      }
    });
  }
  const sampleCoord = selectedSample?.latestLocation || selectedSample?.lastKnownCoordinate || selectedSample?.origin;
  if (sampleCoord) {
    mapMarkers.push({
      id: `sample-${selectedSample.sampleId}`,
      label: `Sample ${selectedSample.sampleId.slice(0, 6)}`,
      kind: 'sample',
      latitude: sampleCoord.latitude,
      longitude: sampleCoord.longitude,
    });
  }
  if (lastRecordedLocation?.coordinate) {
    mapMarkers.push({
      id: 'worker-self',
      label: 'My Recorded Location',
      kind: 'worker',
      latitude: lastRecordedLocation.coordinate.latitude,
      longitude: lastRecordedLocation.coordinate.longitude,
    });
  }

  // Unauthenticated view: Sign In form
  if (!token || !user) {
    return (
      <main style={{ maxWidth: '480px', margin: '3rem auto', fontFamily: 'sans-serif', padding: '1.5rem', border: '1px solid #cbd5e1', borderRadius: '8px' }}>
        <h1>Lab Sample Pickup &amp; Delivery System</h1>
        <h2>Sign In</h2>
        {authError && (
          <div role="alert" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px' }}>
            {authError}
          </div>
        )}
        <form onSubmit={handleLogin} aria-label="Sign In Form">
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="login-username" style={{ display: 'block', fontWeight: 600, marginBottom: '0.25rem' }}>
              Username
            </label>
            <input
              id="login-username"
              name="username"
              type="text"
              value={usernameInput}
              onChange={(e) => setUsernameInput(e.target.value)}
              style={{ width: '100%', padding: '0.5rem', boxSizing: 'border-box' }}
            />
          </div>
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="login-password" style={{ display: 'block', fontWeight: 600, marginBottom: '0.25rem' }}>
              Password
            </label>
            <input
              id="login-password"
              name="password"
              type="password"
              value={passwordInput}
              onChange={(e) => setPasswordInput(e.target.value)}
              style={{ width: '100%', padding: '0.5rem', boxSizing: 'border-box' }}
            />
          </div>
          <button
            type="submit"
            style={{ padding: '0.6rem 1.2rem', background: '#0284c7', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 600 }}
          >
            Sign In
          </button>
        </form>
      </main>
    );
  }

  // Compute capacity items for laboratory_team / node_handler
  const capacityFromWork = allWorkItems.find((i) => i.destinationCapacity)?.destinationCapacity;
  const capacityLocations = ownLocations.length > 0 ? ownLocations : operationsState?.locations || [];

  return (
    <div style={{ fontFamily: 'sans-serif', maxWidth: '1280px', margin: '0 auto', padding: '1rem' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #e2e8f0', paddingBottom: '0.75rem', marginBottom: '1rem' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '1.4rem' }}>Lab Sample Pickup &amp; Delivery System</h1>
          <div style={{ fontSize: '0.9rem', color: '#475569', marginTop: '0.25rem' }}>
            Signed in as: <strong>{user.username}</strong> ({user.userId}) | Current Active Role: <strong data-testid="active-role-badge">{activeRole || 'None selected'}</strong>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <div>
            <label htmlFor="active-role-select" style={{ marginRight: '0.5rem', fontWeight: 600 }}>
              Active Role
            </label>
            <select
              id="active-role-select"
              aria-label="Active Role"
              value={activeRole}
              onChange={(e) => handleRoleSwitch(e.target.value)}
              style={{ padding: '0.4rem' }}
            >
              {activeRole === '' && <option value="">-- Select Role --</option>}
              {(user.roles || []).map((r: string) => (
                <option key={r} value={r}>
                  {r}
                </option>
              ))}
            </select>
          </div>
          <button
            type="button"
            onClick={handleSignOut}
            style={{ padding: '0.45rem 0.9rem', background: '#dc2626', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
          >
            Sign Out
          </button>
        </div>
      </header>

      {user.roleSelectionRequired && (
        <div role="alert" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#fef3c7', color: '#92400e', borderRadius: '4px' }}>
          Please select an active role to continue. Available roles: {(user.roles || []).join(', ')}
          <div style={{ marginTop: '0.5rem', display: 'flex', gap: '0.5rem' }}>
            {(user.roles || []).map((r: string) => (
              <button key={r} type="button" onClick={() => handleRoleSwitch(r)}>
                Use role: {r}
              </button>
            ))}
          </div>
        </div>
      )}

      {actionMessage && (
        <div role="status" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#dcfce7', color: '#166534', borderRadius: '4px' }}>
          {actionMessage}
        </div>
      )}
      {actionError && (
        <div role="alert" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px' }}>
          {actionError}
        </div>
      )}

      {/* Offline MapLibre GL JS + PMTiles Map */}
      <OfflineMap markers={mapMarkers} />

      {/* Role Work Section (Current Work & Past Work) */}
      <section aria-label="Role Work View" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ marginTop: 0 }}>My Role Work ({activeRole})</h2>
          <button type="button" onClick={() => loadRoleWork(activeRole)}>
            Refresh Work
          </button>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
          <section aria-label="Current Work">
            <h3>Current Work ({currentWork.length})</h3>
            {currentWork.length === 0 ? (
              <p>No active or offered assignments.</p>
            ) : (
              currentWork.map((item) => (
                <div key={item.assignmentId} style={{ border: '1px solid #94a3b8', borderRadius: '4px', padding: '0.75rem', marginBottom: '0.75rem' }}>
                  <div>
                    <strong>Assignment ID:</strong> {item.assignmentId}
                  </div>
                  <div>
                    <strong>Status:</strong> <span>{item.status}</span> | <strong>Leg Type:</strong> {item.legType}
                  </div>
                  {item.sampleId && (
                    <div>
                      <strong>Sample ID:</strong> {item.sampleId}{' '}
                      <button type="button" onClick={() => handleLookupSample(item.sampleId)}>
                        View Sample
                      </button>
                    </div>
                  )}
                  {item.journeyId && (
                    <div>
                      <strong>Journey ID:</strong> {item.journeyId}
                    </div>
                  )}
                  {item.destinationCapacity && (
                    <div style={{ marginTop: '0.35rem', fontSize: '0.9rem' }}>
                      <strong>Destination Capacity:</strong> Regular {item.destinationCapacity.availableUnits}/{item.destinationCapacity.capacityUnits} (Reserved: {item.destinationCapacity.reservedUnits}) | Cooled {item.destinationCapacity.cooledAvailableUnits}/{item.destinationCapacity.cooledCapacityUnits} (Reserved: {item.destinationCapacity.cooledReservedUnits})
                    </div>
                  )}
                  <div style={{ marginTop: '0.5rem', display: 'flex', gap: '0.5rem', flexWrap: 'wrap', alignItems: 'center' }}>
                    {(item.status === 'offered' || item.status === 'pending') && (
                      <>
                        <button type="button" onClick={() => handleAcceptAssignment(item.assignmentId)}>
                          Accept Assignment
                        </button>
                        <button type="button" onClick={() => handleDeclineAssignment(item.assignmentId)}>
                          Decline Assignment
                        </button>
                      </>
                    )}
                    {(item.status === 'accepted' || item.status === 'in_progress') && item.sampleId && (
                      <>
                        {(item.kind === 'collection' || item.legType === 'collection' || activeRole === 'collection_professional') && (
                          <button type="button" onClick={() => handleCollectAndSeal(item.sampleId, item.assignmentId)}>
                            Collect &amp; Seal Sample
                          </button>
                        )}
                        <label htmlFor={`chk-temp-${item.assignmentId}`}>Observed Temp (C)</label>
                        <input
                          id={`chk-temp-${item.assignmentId}`}
                          type="number"
                          step="any"
                          value={checkpointTemp}
                          onChange={(e) => setCheckpointTemp(e.target.value)}
                          style={{ width: '70px' }}
                        />
                        <button type="button" onClick={() => handleRecordCheckpoint(item.sampleId, item.assignmentId)}>
                          Record Handling Checkpoint
                        </button>
                      </>
                    )}
                  </div>
                  {((item.timeline && item.timeline.length > 0) || (item.history && item.history.length > 0)) && (
                    <div style={{ marginTop: '0.5rem' }}>
                      <strong>Assignment Status Timeline:</strong>
                      <ol>
                        {(item.timeline || item.history || []).map((h: any, idx: number) => (
                          <li key={h.eventId || idx}>
                            {h.status || h.action} - {h.recordedAt || h.occurredAt}
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                </div>
              ))
            )}
          </section>

          <section aria-label="Past Work">
            <h3>Past Work ({pastWork.length})</h3>
            {pastWork.length === 0 ? (
              <p>No completed assignments yet.</p>
            ) : (
              pastWork.map((item) => (
                <div key={item.assignmentId} style={{ border: '1px solid #cbd5e1', borderRadius: '4px', padding: '0.75rem', marginBottom: '0.75rem', background: '#f8fafc' }}>
                  <div>
                    <strong>Assignment ID:</strong> {item.assignmentId}
                  </div>
                  <div>
                    <strong>Status:</strong> <span>{item.status}</span> | <strong>Leg Type:</strong> {item.legType || item.kind}
                  </div>
                  {item.sampleId && (
                    <div>
                      <strong>Sample ID:</strong> {item.sampleId}{' '}
                      <button type="button" onClick={() => handleLookupSample(item.sampleId)}>
                        View Sample
                      </button>
                      <div style={{ marginTop: '0.5rem', display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
                        <label htmlFor={`chk-temp-past-${item.assignmentId}`}>Observed Temp (C)</label>
                        <input
                          id={`chk-temp-past-${item.assignmentId}`}
                          type="number"
                          step="any"
                          value={checkpointTemp}
                          onChange={(e) => setCheckpointTemp(e.target.value)}
                          style={{ width: '70px' }}
                        />
                        <button type="button" onClick={() => handleRecordCheckpoint(item.sampleId, item.assignmentId)}>
                          Record Handling Checkpoint
                        </button>
                      </div>
                    </div>
                  )}
                  {((item.timeline && item.timeline.length > 0) || (item.history && item.history.length > 0)) && (
                    <div style={{ marginTop: '0.5rem' }}>
                      <strong>Assignment Status Timeline:</strong>
                      <ol>
                        {(item.timeline || item.history || []).map((h: any, idx: number) => (
                          <li key={h.eventId || idx}>
                            {h.status || h.action} - {h.recordedAt || h.occurredAt}
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                </div>
              ))
            )}
          </section>
        </div>
      </section>

      {/* Field Worker Location Recording (collection_professional & delivery_partner) */}
      {(activeRole === 'collection_professional' || activeRole === 'delivery_partner') && (
        <section aria-label="Worker Location Recording" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <h2 style={{ marginTop: 0 }}>Record Worker Location</h2>
          <form onSubmit={(e) => handleRecordWorkerLocation(e)} style={{ display: 'flex', gap: '1rem', alignItems: 'flex-end', flexWrap: 'wrap' }}>
            <div>
              <label htmlFor="worker-lat" style={{ display: 'block', fontWeight: 600 }}>
                Latitude
              </label>
              <input
                id="worker-lat"
                type="number"
                step="any"
                value={workerLat}
                onChange={(e) => setWorkerLat(e.target.value)}
              />
            </div>
            <div>
              <label htmlFor="worker-lng" style={{ display: 'block', fontWeight: 600 }}>
                Longitude
              </label>
              <input
                id="worker-lng"
                type="number"
                step="any"
                value={workerLng}
                onChange={(e) => setWorkerLng(e.target.value)}
              />
            </div>
            <button type="submit">Record Location</button>
          </form>
          {lastRecordedLocation && (
            <div style={{ marginTop: '0.5rem' }}>
              Last Recorded Worker Coordinate: {lastRecordedLocation.coordinate.latitude}, {lastRecordedLocation.coordinate.longitude} (Freshness: {lastRecordedLocation.locationStale ? 'Stale' : 'Fresh'})
            </div>
          )}
        </section>
      )}

      {/* Laboratory / Node Capacity View & Configuration */}
      {(activeRole === 'laboratory_team' || activeRole === 'node_handler' || activeRole === 'administrator') && (
        <section aria-label="Laboratory Capacity" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <h2 style={{ marginTop: 0 }}>Facility Capacity Overview &amp; Configuration</h2>
          {capacityLocations.length > 0 ? (
            capacityLocations.map((loc: any) => (
              <div key={loc.locationId || loc.id} style={{ padding: '0.75rem', border: '1px solid #e2e8f0', borderRadius: '4px', marginBottom: '0.5rem' }}>
                <div>
                  <strong>Facility:</strong> {loc.name} ({loc.locationId || loc.id})
                </div>
                {loc.capacity && (
                  <div>
                    <span>Regular Capacity: {loc.capacity.capacityUnits}</span> |{' '}
                    <span>Regular Reserved: {loc.capacity.reservedUnits}</span> |{' '}
                    <span>Regular Available: {loc.capacity.availableUnits}</span> |{' '}
                    <span>Cooled Capacity: {loc.capacity.cooledCapacityUnits}</span> |{' '}
                    <span>Cooled Reserved: {loc.capacity.cooledReservedUnits}</span> |{' '}
                    <span>Cooled Available: {loc.capacity.cooledAvailableUnits}</span>
                  </div>
                )}
              </div>
            ))
          ) : capacityFromWork ? (
            <div style={{ padding: '0.75rem', border: '1px solid #e2e8f0', borderRadius: '4px', marginBottom: '0.5rem' }}>
              <span>Regular Capacity: {capacityFromWork.capacityUnits}</span> |{' '}
              <span>Regular Reserved: {capacityFromWork.reservedUnits}</span> |{' '}
              <span>Regular Available: {capacityFromWork.availableUnits}</span> |{' '}
              <span>Cooled Capacity: {capacityFromWork.cooledCapacityUnits}</span> |{' '}
              <span>Cooled Reserved: {capacityFromWork.cooledReservedUnits}</span> |{' '}
              <span>Cooled Available: {capacityFromWork.cooledAvailableUnits}</span>
            </div>
          ) : (
            <p>No facility capacity records loaded.</p>
          )}

          <form onSubmit={handleConfigureCapacity} style={{ display: 'flex', gap: '1rem', alignItems: 'flex-end', marginTop: '0.75rem', flexWrap: 'wrap' }}>
            <div>
              <label htmlFor="cap-target-id" style={{ display: 'block', fontWeight: 600 }}>
                Target Facility ID
              </label>
              <input
                id="cap-target-id"
                type="text"
                value={capTargetId}
                onChange={(e) => setCapTargetId(e.target.value)}
              />
            </div>
            <div>
              <label htmlFor="cap-regular" style={{ display: 'block', fontWeight: 600 }}>
                Regular Capacity Units
              </label>
              <input
                id="cap-regular"
                type="number"
                value={capRegular}
                onChange={(e) => setCapRegular(e.target.value)}
              />
            </div>
            <div>
              <label htmlFor="cap-cooled" style={{ display: 'block', fontWeight: 600 }}>
                Cooled Capacity Units
              </label>
              <input
                id="cap-cooled"
                type="number"
                value={capCooled}
                onChange={(e) => setCapCooled(e.target.value)}
              />
            </div>
            <button type="submit">Update Capacity</button>
          </form>
        </section>
      )}

      {/* Requester Serviceability Check & Collection Request Form */}
      {(activeRole === 'requester' || activeRole === 'administrator') && (
        <section aria-label="Collection Request Form" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <h2 style={{ marginTop: 0 }}>Check Serviceability &amp; Create Collection Request</h2>
          {requestFormError && (
            <div role="alert" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px' }}>
              {requestFormError}
            </div>
          )}
          {serviceabilityResult && (
            <div role="status" aria-label="Serviceability Dry Run Result" style={{ padding: '0.75rem', marginBottom: '1rem', background: '#e0f2fe', color: '#075985', borderRadius: '4px' }}>
              <strong>Serviceability Check (Dry Run — No Request Created):</strong>{' '}
              <span>{serviceabilityResult.serviceable ? 'Serviceable' : 'Unserviceable'}</span> |{' '}
              <span>Reason: {serviceabilityResult.reason}</span> |{' '}
              <span>Version: {serviceabilityResult.serviceabilityVersion}</span>
              {serviceabilityResult.targetLaboratoryId && (
                <span> | Target Lab: {serviceabilityResult.targetLaboratoryId}</span>
              )}
            </div>
          )}
          <form onSubmit={handleCreateCollectionRequest}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '0.75rem', marginBottom: '0.75rem' }}>
              <div>
                <label htmlFor="req-origin-type" style={{ display: 'block', fontWeight: 600 }}>
                  Origin Type
                </label>
                <select id="req-origin-type" value={originType} onChange={(e) => setOriginType(e.target.value)} style={{ width: '100%', padding: '0.4rem' }}>
                  <option value="home">home</option>
                  <option value="clinic">clinic</option>
                  <option value="node">node</option>
                </select>
              </div>
              <div>
                <label htmlFor="req-origin-lat" style={{ display: 'block', fontWeight: 600 }}>
                  Origin Latitude
                </label>
                <input
                  id="req-origin-lat"
                  type="text"
                  value={originLat}
                  onChange={(e) => setOriginLat(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-origin-lng" style={{ display: 'block', fontWeight: 600 }}>
                  Origin Longitude
                </label>
                <input
                  id="req-origin-lng"
                  type="text"
