action.new_str:
const handleCollectAndSeal = async (sampleId: string, assignmentId: string) => {
  setActionError('');
  setActionMessage('');
  try {
    const smp = await apiCall(`/api/read-sample-state/${encodeURIComponent(sampleId)}`, 'GET');
    const earliestMs = smp?.earliestCollectionAt ? new Date(smp.earliestCollectionAt).getTime() : Date.now();
    const collectedAtMs = Math.max(Date.now(), earliestMs + 1000);
    const compliantTemp =
      typeof smp?.temperatureMinC === 'number' && typeof smp?.temperatureMaxC === 'number'
        ? (smp.temperatureMinC + smp.temperatureMaxC) / 2
        : 20;
    await apiCall('/api/collect-and-seal-sample', 'POST', {
      sampleId,
      assignmentId,
      collectedAt: new Date(collectedAtMs).toISOString(),
      containerType: smp?.containerType || containerType || 'standard_tube',
      observedTemperatureC: compliantTemp,
      idempotencyKey: makeIdempotencyKey('seal'),
    });
    setActionMessage(`Collected and sealed sample ${sampleId}`);
    await loadRoleWork(activeRole);
    await handleLookupSample(sampleId);
  } catch (err: any) {
    setActionError(`Collect and seal failed: ${err.message}`);
  }
};

const handleRecordCheckpoint = async (sampleId: string, assignmentId: string) => {
  setActionError('');
  setActionMessage('');
  try {
    const smp = await apiCall(`/api/read-sample-state/${encodeURIComponent(sampleId)}`, 'GET');
    const sealedMs = smp?.sealedAt ? new Date(smp.sealedAt).getTime() : Date.now();
    const recMs = Math.max(Date.now(), sealedMs + 1000);
    await apiCall('/api/record-handling-checkpoint', 'POST', {
      sampleId,
      assignmentId,
      containerType: smp?.containerType || containerType || 'standard_tube',
      observedTemperatureC: parseFloat(checkpointTemp) || 22,
      recordedAt: new Date(recMs).toISOString(),
      idempotencyKey: makeIdempotencyKey('checkpoint'),
    });
    setActionMessage(`Recorded handling checkpoint for sample ${sampleId}`);
    await loadRoleWork(activeRole);
    await handleLookupSample(sampleId);
  } catch (err: any) {
    setActionError(`Handling checkpoint failed: ${err.message}`);
  }
};

