                      {st.name}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label htmlFor="req-container" style={{ display: 'block', fontWeight: 600 }}>
                  Container Type
                </label>
                <input
                  id="req-container"
                  type="text"
                  value={containerType}
                  onChange={(e) => setContainerType(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-min" style={{ display: 'block', fontWeight: 600 }}>
                  Min Temperature (C)
                </label>
                <input
                  id="req-temp-min"
                  type="text"
                  value={tempMin}
                  onChange={(e) => setTempMin(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-max" style={{ display: 'block', fontWeight: 600 }}>
                  Max Temperature (C)
                </label>
                <input
                  id="req-temp-max"
                  type="text"
                  value={tempMax}
                  onChange={(e) => setTempMax(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-window-start" style={{ display: 'block', fontWeight: 600 }}>
                  Earliest Collection Time
                </label>
                <input
                  id="req-window-start"
                  type="text"
                  value={windowStart}
                  onChange={(e) => setWindowStart(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-window-end" style={{ display: 'block', fontWeight: 600 }}>
                  Latest Collection Time
                </label>
                <input
                  id="req-window-end"
                  type="text"
                  value={windowEnd}
                  onChange={(e) => setWindowEnd(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-deadline" style={{ display: 'block', fontWeight: 600 }}>
                  Delivery Deadline
                </label>
                <input
                  id="req-deadline"
                  type="text"
                  value={deadlineAt}
                  onChange={(e) => setDeadlineAt(e.target.value)}
                  style={{ width: '100%', padding: '0.4rem', boxSizing: 'border-box' }}
                />
              </div>
            </div>
            <div style={{ display: 'flex', gap: '0.75rem' }}>
              <button type="button" onClick={handleCheckServiceability}>
                Check Serviceability
              </button>
              <button type="submit">Create Collection Request</button>
            </div>
          </form>
        </section>
      )}

      {/* Sample Tracking, Freshness, Custodian, Route Progress, Exception Flag & Ordered Status History */}
      <section aria-label="Sample Tracking and Status History" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
        <h2 style={{ marginTop: 0 }}>Sample Tracking, Custody &amp; Status Timeline</h2>
        <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.75rem', alignItems: 'center' }}>
          <label htmlFor="sample-lookup-input" style={{ fontWeight: 600 }}>
            Inspect Sample ID:
          </label>
          <input
            id="sample-lookup-input"
            type="text"
            placeholder="Enter Sample UUID"
            value={sampleLookupId}
            onChange={(e) => setSampleLookupId(e.target.value)}
            style={{ width: '320px', padding: '0.4rem' }}
          />
          <button type="button" onClick={() => handleLookupSample()}>
            Load Sample
          </button>
        </div>

        {requesterSamples.length > 0 && (
          <div style={{ marginBottom: '0.75rem' }}>
            <strong>My Samples ({requesterSamples.length}):</strong>{' '}
            {requesterSamples.map((smp) => (
              <button
                key={smp.sampleId}
                type="button"
                onClick={() => setSelectedSample(smp)}
                style={{ marginRight: '0.5rem', marginBottom: '0.25rem' }}
              >
                {smp.sampleId.slice(0, 8)} ({smp.status})
              </button>
            ))}
          </div>
        )}

        {selectedSample ? (
          <section aria-label="Selected Sample Details" style={{ border: '1px solid #94a3b8', borderRadius: '6px', padding: '1rem', background: '#f8fafc' }}>
            <h3>Sample {selectedSample.sampleId}</h3>

            {(selectedSample.status === 'exception' || selectedSample.state?.status === 'exception' || selectedSample.exception) && (
              <div
                role="alert"
                aria-label="Sample Exception"
                style={{ padding: '0.75rem', marginBottom: '0.75rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px', fontWeight: 600 }}
              >
                Exception Flag: {selectedSample.exception?.code || 'exception'} — {selectedSample.exception?.reason || 'Sample flagged as exception'}
              </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '0.75rem', marginBottom: '0.75rem' }}>
              <div>
                <strong>Status:</strong> <span>{selectedSample.status || selectedSample.state?.status}</span>
              </div>
              <div>
                <strong>Current Custodian:</strong>{' '}
                <span aria-label="Sample Custodian">{selectedSample.currentHolderId || 'Unsealed / Origin'}</span>
              </div>
              <div>
                <strong>Current Location:</strong>{' '}
                <span aria-label="Sample Location">
                  {(selectedSample.latestLocation || selectedSample.lastKnownCoordinate || selectedSample.origin)
                    ? `${(selectedSample.latestLocation || selectedSample.lastKnownCoordinate || selectedSample.origin).latitude}, ${(selectedSample.latestLocation || selectedSample.lastKnownCoordinate || selectedSample.origin).longitude}`
                    : 'Unknown'}
                </span>
              </div>
              <div>
                <strong>Location Freshness:</strong>{' '}
                <span aria-label="Sample Freshness" style={{ fontWeight: 700, color: selectedSample.locationStale ? '#dc2626' : '#16a34a' }}>
                  {selectedSample.locationStale ? 'Stale' : 'Fresh'}
                </span>{' '}
                (Last Updated: {selectedSample.locationRecordedAt || 'N/A'})
              </div>
              <div>
                <strong>Delivery Deadline:</strong> {selectedSample.deliveryDeadline || selectedSample.deliveryDeadlineAt}
              </div>
              <div>
                <strong>Journey ID:</strong> {selectedSample.activeJourneyId || selectedSample.journeyId}
              </div>
            </div>

            <div style={{ marginBottom: '0.75rem' }}>
              <h4>Route Progress {selectedSample.route ? `(Plan Version ${selectedSample.route.planVersion} — ${selectedSample.route.routeMode})` : ''}</h4>
              <ol aria-label="Route Progress">
                {selectedSample.route?.orderedStops ? (
                  selectedSample.route.orderedStops.map((stop: any) => (
                    <li key={stop.sequence}>
                      Stop #{stop.sequence}: {stop.kind} at {stop.locationId} —{' '}
                      <strong>{stop.completed ? 'Completed' : 'Pending'}</strong>
                    </li>
                  ))
                ) : (
                  <>
                    <li>
                      Origin ({selectedSample.originType || 'origin'}) —{' '}
                      <strong>{(selectedSample.completedLegIds?.length || 0) > 0 || selectedSample.sealed ? 'Completed' : 'Pending'}</strong>
                    </li>
                    {selectedSample.targetLaboratoryId && (
                      <li>
                        Target Laboratory {selectedSample.targetLaboratoryId} —{' '}
                        <strong>{(selectedSample.status || selectedSample.state?.status) === 'received' ? 'Completed' : 'Pending'}</strong>
                      </li>
                    )}
                  </>
                )}
              </ol>
            </div>

            <div>
              <h4>Ordered Status History</h4>
              <ol aria-label="Ordered Status History">
                {(selectedSample.timeline || selectedSample.history || []).map((ev: any, idx: number) => (
                  <li key={ev.eventId || idx}>
                    <strong>{ev.status || ev.action}</strong> | Time: {ev.recordedAt || ev.occurredAt}
                    {ev.role ? ` | Role: ${ev.role}` : ''}
                    {ev.actorId ? ` | Actor: ${ev.actorId}` : ''}
                  </li>
                ))}
              </ol>
            </div>
          </section>
        ) : (
          <p>Select or enter a Sample ID to view its status history, location freshness, custodian, and route progress.</p>
        )}
      </section>

      {/* Dispatcher & Administrator Operations Monitor Dashboard */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section aria-label="Operations Monitor Dashboard" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h2 style={{ marginTop: 0 }}>Operations Monitor Dashboard</h2>
            <button type="button" onClick={() => loadMonitorAndAudit(activeRole)}>
              Refresh Monitor
            </button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '1rem' }}>
            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Samples ({operationsState?.samples?.length || 0})</h3>
              <ul>
                {(operationsState?.samples || []).map((s: any) => (
                  <li key={s.sampleId}>
                    <button type="button" onClick={() => setSelectedSample(s)} style={{ marginRight: '0.35rem' }}>
                      {s.sampleId.slice(0, 8)}
                    </button>
                    Status: <strong>{s.status}</strong> | Holder: {s.currentHolderId || 'None'} |{' '}
                    <span>{s.locationStale ? 'Stale' : 'Fresh'}</span>
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Workers ({operationsState?.workers?.length || 0})</h3>
              <ul>
                {(operationsState?.workers || []).map((w: any) => (
                  <li key={w.workerId || w.userId}>
                    {w.fullName || w.username || w.workerId} ({(w.roles || []).join(', ')}) — {w.available ? 'Available' : 'Unavailable'} |{' '}
                    {w.locationStale ? 'Stale' : 'Fresh'}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Collection Nodes &amp; Laboratories ({operationsState?.locations?.length || 0})</h3>
              <ul>
                {(operationsState?.locations || []).map((loc: any) => (
                  <li key={loc.locationId || loc.id}>
                    {loc.name} ({loc.active ? 'Active' : 'Inactive'}) — Cap: {loc.capacity?.availableUnits}/{loc.capacity?.capacityUnits}, Cooled: {loc.capacity?.cooledAvailableUnits}/{loc.capacity?.cooledCapacityUnits}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Routes ({operationsState?.routes?.length || 0}) &amp; Connections ({operationsState?.connections?.length || 0})</h3>
              <ul>
                {(operationsState?.routes || []).map((rt: any) => (
                  <li key={rt.journeyId}>
                    Journey {rt.journeyId.slice(0, 8)} (v{rt.planVersion}, {rt.routeMode}) — {rt.status}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Handoffs ({operationsState?.handoffs?.length || 0}) &amp; Delays ({operationsState?.delays?.length || 0})</h3>
              <ul>
                {(operationsState?.handoffs || []).map((h: any) => (
                  <li key={h.handoffId}>
                    Handoff {h.handoffId.slice(0, 8)}: {h.fromHolderId?.slice(0, 6)} → {h.toHolderId?.slice(0, 6)} ({h.status})
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', padding: '0.75rem', borderRadius: '4px' }}>
              <h3>Exceptions ({operationsState?.exceptions?.length || 0})</h3>
              <ul>
                {(operationsState?.exceptions || []).map((ex: any) => (
                  <li key={ex.sampleId} style={{ color: '#991b1b' }}>
                    Sample {ex.sampleId.slice(0, 8)}: {ex.code} — {ex.reason}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </section>
      )}

      {/* Searchable Audit Trail (Dispatcher & Administrator) */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section aria-label="Audit Trail" style={{ border: '1px solid #cbd5e1', borderRadius: '6px', padding: '1rem', marginBottom: '1rem' }}>
