   203	func (s *Store) initDB(ctx context.Context) error {
   204		if _, err := s.db.Exec(ctx, schemaSQL); err != nil {
   205			return fmt.Errorf("apply schema: %w", err)
   206		}
   207	
   208		var raw []byte
   209		err := s.db.QueryRow(ctx, `SELECT state_json FROM app_state WHERE id = 1`).Scan(&raw)
   210		if err == nil && len(raw) > 0 {
   211			var st AppStateData
   212			if uerr := json.Unmarshal(raw, &st); uerr == nil {
   213				s.ensureMaps(&st)
   214				s.state = &st
   215			}
   216		}
   217		if s.state == nil {
   218			s.state = s.newDefaultState()
   219		}
   220	
   221		adminUser := strings.TrimSpace(os.Getenv("ADMIN_USERNAME"))
   222		adminPass := os.Getenv("ADMIN_PASSWORD")
   223		if len(s.state.Users) == 0 && adminUser != "" && adminPass != "" {
   224			uid := deterministicUUID("initial-admin-" + adminUser)
   225			s.state.Users[uid] = &User{
   226				UserID:           uid,
   227				Username:         adminUser,
   228				PasswordHash:     hashString(adminPass),
   229				FullName:         "System Administrator",
   230				Roles:            []string{"administrator"},
   231				Qualifications:   []string{},
   232				Certifications:   []Certification{},
   233				Active:           true,
   234				Available:        true,
   235				CapacityUnits:    10,
   236				AssignmentLocSeq: make(map[string]int),
   237				CreatedAt:        formatTime(time.Now().UTC()),
   238			}
   239		}
   240	
   241		return s.persistLocked(ctx)
   242	}
